window.SOURCE_SNAPSHOT = {"index.html":"\u003c!doctype html>\n\u003chtml lang=\"en\">\n  \u003chead>\n    \u003cmeta charset=\"utf-8\" />\n    \u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    \u003cmeta\n      http-equiv=\"Content-Security-Policy\"\n      content=\"default-src 'none'; script-src 'self'; style-src 'self' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'none'; form-action 'none'\"\n    />\n    \u003cmeta\n      name=\"description\"\n      content=\"Sai Kalyandurg, Project and Product Manager in Chicago, and a front-end developer. Start with the profile or the UI skills.\"\n    />\n    \u003ctitle>Sai Kalyandurg\u003c/title>\n    \u003clink rel=\"icon\" href=\"favicon.svg\" type=\"image/svg+xml\" />\n    \u003clink rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n    \u003clink rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n    \u003clink\n      rel=\"stylesheet\"\n      href=\"https://fonts.googleapis.com/css2?family=Public+Sans:wght@400..700&family=Source+Code+Pro:wght@400;500;600&family=Source+Serif+4:opsz,wght@8..60,400..700&display=swap\"\n    />\n    \u003clink rel=\"stylesheet\" href=\"css/base.css\" />\n    \u003clink rel=\"stylesheet\" href=\"css/entrance.css\" />\n  \u003c/head>\n  \u003cbody class=\"entrance\">\n    \u003cmain class=\"stage\" id=\"stage\">\n      \u003cdiv class=\"codefall\" aria-hidden=\"true\">\n        \u003cpre>\nconst can = (role, permission) =&gt;\n  role !== undefined &amp;&amp;\n  PERMISSIONS[role].includes(permission);\n\nfunction parseNewRisk(input: unknown) {\n  const errors: Fields = {};\n  if (title.length &lt; 3)\n    errors.title = \"Enter at least 3 characters.\";\n  if (!EMAIL.test(owner))\n    errors.owner = \"Enter a valid email address.\";\n  if (Object.keys(errors).length &gt; 0)\n    return { ok: false, errors };\n  return { ok: true, value };\n}\n\nconst retryable = (e: unknown) =&gt;\n  e instanceof NetworkError ||\n  e instanceof TimeoutError ||\n  (e instanceof HttpError &amp;&amp; e.status &gt;= 500);\n\nconst backoff = (attempt: number) =&gt;\n  300 * 2 ** attempt + Math.random() * 100;\n\nfunction reducer(state: State, action: Action) {\n  switch (action.type) {\n    case \"load/start\":\n      return { ...state, load: \"loading\" };\n    case \"update/rollback\":\n      return restore(state, action.previous);\n    default:\n      return assertNever(action);\n  }\n}\u003c/pre>\n        \u003cpre>\n@container (max-width: 40rem) {\n  .lab-table thead { position: absolute; }\n  .lab-table tr { display: block; }\n  .lab-table td::before {\n    content: attr(data-label);\n  }\n}\n\n:root {\n  --accent: #1e4e8c;\n  --serif: \"Source Serif 4\", Georgia, serif;\n}\n@media (prefers-color-scheme: dark) {\n  :root { --accent: #8db4ea; }\n}\n\n.grid {\n  display: grid;\n  grid-template-columns:\n    repeat(auto-fit, minmax(15.5rem, 1fr));\n  gap: 2.5rem 2.25rem;\n}\n\n&lt;form class=\"form\" novalidate&gt;\n  &lt;label for=\"f-email\"&gt;Email&lt;/label&gt;\n  &lt;input id=\"f-email\" type=\"email\"\n         autocomplete=\"email\" required&gt;\n  &lt;p id=\"f-status\" role=\"status\"&gt;&lt;/p&gt;\n&lt;/form&gt;\u003c/pre>\n        \u003cpre>\nexport const authGuard: CanActivateFn = (route, state) =&gt; {\n  const auth = inject(AuthService);\n  const router = inject(Router);\n  if (!auth.isSignedIn())\n    return router.createUrlTree([\"/sign-in\"], {\n      queryParams: { returnUrl: state.url },\n    });\n  return true;\n};\n\nexport function safeReturnUrl(url: string | null) {\n  return url &amp;&amp; url.startsWith(\"/\") &amp;&amp; !url.startsWith(\"//\")\n    ? url\n    : \"/risks\";\n}\n\nexport const authInterceptor: HttpInterceptorFn =\n  (req, next) =&gt; {\n    if (!req.url.startsWith(API_PREFIX))\n      return next(req);\n    return next(req.clone({\n      setHeaders: { Authorization: `Bearer ${token}` },\n    }));\n  };\u003c/pre>\n      \u003c/div>\n\n      \u003cdiv class=\"wrap intro\">\n        \u003cp class=\"kicker\">Project &amp; Product Manager · Chicago, IL\u003c/p>\n        \u003ch1 class=\"greet\" id=\"greet\">Hi, I'm Sai Kalyandurg.\u003c/h1>\n        \u003cp class=\"lede\">\n          I deliver cloud transformation and platform programs for a living. I also write the\n          interfaces, and this site is built to prove it.\n        \u003c/p>\n        \u003cp class=\"ask\" id=\"ask\">What would you like to see first?\u003c/p>\n        \u003cdiv class=\"choices\">\n          \u003ca class=\"choice\" href=\"profile.html\" data-choice=\"profile\">\n            \u003cspan class=\"choice-label\">Profile and work\u003c/span>\n            \u003cspan class=\"choice-title\">Who I am and what I have delivered\u003c/span>\n            \u003cspan class=\"choice-text\">\n              Experience, results, certifications, and my projects on GitHub with their file\n              structure.\n            \u003c/span>\n            \u003cpre class=\"choice-peek\">\nADMIS     $1.5M program, 2 yr to 18 mo\nFidelity  330K clients onboarded\nLowe's    56 teams on platforms I built\u003c/pre>\n            \u003cspan class=\"choice-go\">Open the profile\u003c/span>\n          \u003c/a>\n          \u003ca class=\"choice\" href=\"ui.html\" data-choice=\"ui\">\n            \u003cspan class=\"choice-label\">Skills in UI development\u003c/span>\n            \u003cspan class=\"choice-title\">See the code run, then read it\u003c/span>\n            \u003cspan class=\"choice-text\">\n              A working enterprise UI in HTML, CSS, TypeScript and React, with Angular beside it.\n            \u003c/span>\n            \u003cpre class=\"choice-peek\" aria-hidden=\"true\">\nif (!can(role, \"risk:update\"))\n  throw new HttpError(403);\u003c/pre>\n            \u003cspan class=\"choice-go\">Open the live demo\u003c/span>\n          \u003c/a>\n        \u003c/div>\n        \u003cp class=\"quick\">\n          Or go straight to \u003ca href=\"projects.html\">projects\u003c/a> or\n          \u003ca href=\"profile.html#contact\">contact\u003c/a>.\n        \u003c/p>\n      \u003c/div>\n    \u003c/main>\n    \u003cdiv class=\"curtain\" aria-hidden=\"true\">\u003c/div>\n    \u003cscript src=\"data/settings.js\">\u003c/script>\n    \u003cscript src=\"js/entrance.js\">\u003c/script>\n  \u003c/body>\n\u003c/html>\n","profile.html":"\u003c!doctype html>\n\u003chtml lang=\"en\">\n  \u003chead>\n    \u003cmeta charset=\"utf-8\" />\n    \u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    \u003cmeta\n      http-equiv=\"Content-Security-Policy\"\n      content=\"default-src 'none'; script-src 'self'; style-src 'self' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; img-src 'self' data:; connect-src 'self' https://api.web3forms.com; object-src 'none'; base-uri 'none'; form-action 'none'\"\n    />\n    \u003cmeta\n      name=\"description\"\n      content=\"Experience, results, skills and certifications for Sai Kalyandurg, Project and Product Manager in Chicago.\"\n    />\n    \u003ctitle>Sai Kalyandurg, Profile\u003c/title>\n    \u003clink rel=\"icon\" href=\"favicon.svg\" type=\"image/svg+xml\" />\n    \u003clink rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n    \u003clink rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n    \u003clink\n      rel=\"stylesheet\"\n      href=\"https://fonts.googleapis.com/css2?family=Public+Sans:wght@400..700&family=Source+Code+Pro:wght@400;500;600&family=Source+Serif+4:opsz,wght@8..60,400..700&display=swap\"\n    />\n    \u003clink rel=\"stylesheet\" href=\"css/base.css\" />\n    \u003clink rel=\"stylesheet\" href=\"css/profile.css\" />\n  \u003c/head>\n  \u003cbody>\n    \u003ca class=\"skip\" href=\"#top\">Skip to content\u003c/a>\n    \u003cheader class=\"nav\">\n      \u003cdiv class=\"wrap\">\n        \u003ca class=\"brand\" href=\"index.html\" data-site=\"name\">Sai Kalyandurg\u003c/a>\n        \u003cnav aria-label=\"Main\">\n          \u003cul>\n            \u003cli>\u003ca href=\"profile.html\" aria-current=\"page\">Profile\u003c/a>\u003c/li>\n            \u003cli>\u003ca href=\"projects.html\">Projects\u003c/a>\u003c/li>\n            \u003cli>\u003ca href=\"ui.html\">UI skills\u003c/a>\u003c/li>\n            \u003cli>\u003ca href=\"profile.html#contact\">Contact\u003c/a>\u003c/li>\n          \u003c/ul>\n        \u003c/nav>\n        \u003ca class=\"btn btn-primary btn-sm\" href=\"ui.html#source\">Read the source\u003c/a>\n      \u003c/div>\n    \u003c/header>\n    \u003cmain id=\"top\">\n      \u003cdiv class=\"wrap\">\n        \u003caside class=\"say\" aria-label=\"A note from Sai\">\n          \u003cspan class=\"say-avatar\" aria-hidden=\"true\">SK\u003c/span>\n          \u003cdiv class=\"say-body\">\n            \u003cp class=\"say-text\">\n              Here is who I am and what I have delivered. Scroll for the detail, or jump to what you\n              need.\n            \u003c/p>\n            \u003cdiv class=\"say-actions\">\n              \u003ca class=\"btn btn-sm\" href=\"#experience\">Experience\u003c/a>\n              \u003ca class=\"btn btn-sm\" href=\"#skills\">Skills\u003c/a>\n              \u003ca class=\"btn btn-sm\" href=\"#credentials\">Certifications\u003c/a>\n              \u003ca class=\"btn btn-sm\" href=\"#contact\">Contact\u003c/a>\n            \u003c/div>\n          \u003c/div>\n        \u003c/aside>\n      \u003c/div>\n\n      \u003csection class=\"wrap hero\" aria-labelledby=\"name\">\n        \u003cdiv>\n          \u003ch1 id=\"name\" data-site=\"name\">Sai Kalyandurg\u003c/h1>\n          \u003cp class=\"title-line\">\n            \u003cspan data-site=\"title\">Project &amp; Product Manager\u003c/span>,\n            \u003cspan data-site=\"location\">Chicago, IL\u003c/span>\n          \u003c/p>\n          \u003cp class=\"lede\" id=\"lead\">\u003c/p>\n          \u003cdiv class=\"cta\" id=\"hero-links\">\n            \u003ca class=\"btn btn-primary\" href=\"#contact\">Get in touch\u003c/a>\n            \u003ca class=\"btn\" href=\"projects.html\">See my projects\u003c/a>\n            \u003ca class=\"btn\" href=\"#\" data-site-link=\"linkedin\">LinkedIn\u003c/a>\n            \u003ca class=\"btn\" href=\"#\" data-site-link=\"github\">GitHub\u003c/a>\n            \u003ca class=\"btn\" href=\"#\" data-site-link=\"resumeUrl\">Resume (PDF)\u003c/a>\n          \u003c/div>\n        \u003c/div>\n        \u003cdl class=\"facts\" id=\"facts\">\u003c/dl>\n      \u003c/section>\n\n      \u003csection class=\"wrap results\" aria-label=\"Results from my resume\">\n        \u003cul class=\"results-list\" id=\"results\">\u003c/ul>\n      \u003c/section>\n\n      \u003csection class=\"wrap section\" id=\"summary\" aria-labelledby=\"h-summary\">\n        \u003ch2 id=\"h-summary\">Summary\u003c/h2>\n        \u003cdiv>\u003cp class=\"prose\" id=\"summary-text\">\u003c/p>\u003c/div>\n      \u003c/section>\n\n      \u003csection class=\"wrap section\" id=\"experience\" aria-labelledby=\"h-exp\">\n        \u003ch2 id=\"h-exp\">Experience\u003c/h2>\n        \u003cdiv id=\"experience-list\">\u003c/div>\n      \u003c/section>\n\n      \u003csection class=\"wrap section\" id=\"skills\" aria-labelledby=\"h-skills\">\n        \u003ch2 id=\"h-skills\">Skills\u003c/h2>\n        \u003cdl class=\"defs\" id=\"skills-list\">\u003c/dl>\n      \u003c/section>\n\n      \u003csection class=\"wrap section\" id=\"credentials\" aria-labelledby=\"h-cred\">\n        \u003ch2 id=\"h-cred\">Certifications and education\u003c/h2>\n        \u003cdiv class=\"cred-grid\">\n          \u003cdiv>\n            \u003ch3 class=\"sub-title\">Certifications\u003c/h3>\n            \u003cul class=\"cred-list\" id=\"cert-list\">\u003c/ul>\n          \u003c/div>\n          \u003cdiv>\n            \u003ch3 class=\"sub-title\">Education\u003c/h3>\n            \u003cul class=\"cred-list\" id=\"edu-list\">\u003c/ul>\n          \u003c/div>\n        \u003c/div>\n      \u003c/section>\n\n      \u003csection class=\"wrap section\" id=\"contact\" aria-labelledby=\"h-contact\">\n        \u003ch2 id=\"h-contact\">Contact\u003c/h2>\n        \u003cdiv class=\"contact-grid\">\n          \u003cdl class=\"contact-info\">\n            \u003cdiv>\n              \u003cdt>Email\u003c/dt>\n              \u003cdd>\n                \u003ca id=\"c-email\" href=\"#\">Email me\u003c/a>\n                \u003cbutton type=\"button\" class=\"btn btn-sm\" id=\"copy-email\">Copy\u003c/button>\n              \u003c/dd>\n            \u003c/div>\n            \u003cdiv>\n              \u003cdt>Elsewhere\u003c/dt>\n              \u003cdd>\n                \u003ca class=\"btn btn-sm\" href=\"#\" data-site-link=\"linkedin\">LinkedIn\u003c/a>\n                \u003ca class=\"btn btn-sm\" href=\"#\" data-site-link=\"github\">GitHub\u003c/a>\n              \u003c/dd>\n            \u003c/div>\n            \u003cdiv>\n              \u003cdt>Based in\u003c/dt>\n              \u003cdd data-site=\"location\">Chicago, IL\u003c/dd>\n            \u003c/div>\n          \u003c/dl>\n          \u003cform class=\"form\" id=\"contact-form\" novalidate>\n            \u003cdiv class=\"field\">\n              \u003clabel for=\"f-name\">Name\u003c/label>\n              \u003cinput\n                id=\"f-name\"\n                name=\"name\"\n                type=\"text\"\n                autocomplete=\"name\"\n                required\n                maxlength=\"120\"\n              />\n            \u003c/div>\n            \u003cdiv class=\"field\">\n              \u003clabel for=\"f-email\">Your email\u003c/label>\n              \u003cinput\n                id=\"f-email\"\n                name=\"email\"\n                type=\"email\"\n                autocomplete=\"email\"\n                required\n                maxlength=\"200\"\n              />\n            \u003c/div>\n            \u003cdiv class=\"field\">\n              \u003clabel for=\"f-message\">Message\u003c/label>\n              \u003ctextarea id=\"f-message\" name=\"message\" required maxlength=\"4000\">\u003c/textarea>\n            \u003c/div>\n            \u003cdiv class=\"hp\" aria-hidden=\"true\">\n              \u003clabel for=\"f-botcheck\">Leave this empty\u003c/label>\n              \u003cinput id=\"f-botcheck\" name=\"botcheck\" type=\"text\" tabindex=\"-1\" autocomplete=\"off\" />\n            \u003c/div>\n            \u003cdiv class=\"actions\">\n              \u003cbutton class=\"btn btn-primary\" id=\"f-send\" type=\"submit\">Send message\u003c/button>\n              \u003cp class=\"status\" id=\"f-status\" role=\"status\" aria-live=\"polite\">\u003c/p>\n            \u003c/div>\n          \u003c/form>\n        \u003c/div>\n      \u003c/section>\n\n      \u003csection class=\"next wrap\" aria-labelledby=\"next-title\">\n        \u003ch2 id=\"next-title\">Where to next?\u003c/h2>\n        \u003cp class=\"next-lede\">\n          You have the background. The projects page shows the code, and the UI skills page runs it.\n        \u003c/p>\n        \u003cdiv class=\"next-grid\">\n          \u003ca class=\"next-card\" href=\"projects.html\">\n            \u003cstrong>Projects on GitHub\u003c/strong>\n            \u003cspan>Browse each project's file structure and open the files.\u003c/span>\n            \u003cem>See the projects\u003c/em>\n          \u003c/a>\n          \u003ca class=\"next-card\" href=\"ui.html\">\n            \u003cstrong>UI skills, live\u003c/strong>\n            \u003cspan>Sign in, break it, and read the source behind every behavior.\u003c/span>\n            \u003cem>Open the demo\u003c/em>\n          \u003c/a>\n        \u003c/div>\n      \u003c/section>\n    \u003c/main>\n    \u003cfooter class=\"foot\">\n      \u003cdiv class=\"wrap\">\n        \u003cspan>© \u003cspan data-year>\u003c/span> \u003cspan data-site=\"name\">Sai Kalyandurg\u003c/span>\u003c/span>\n        \u003cspan>\n          Plain HTML, CSS and TypeScript.\n          \u003ca href=\"ui.html#source\">Read the source\u003c/a>\n          \u003cspan data-site-show=\"siteRepo\">\n            \u003cspan class=\"foot-sep\" aria-hidden=\"true\">·\u003c/span>\n            \u003ca href=\"#\" data-site-link=\"siteRepo\">This site on GitHub\u003c/a>\n          \u003c/span>\n        \u003c/span>\n      \u003c/div>\n    \u003c/footer>\n    \u003cscript src=\"data/settings.js\">\u003c/script>\n    \u003cscript src=\"data/profile.js\">\u003c/script>\n    \u003cscript src=\"js/common.js\">\u003c/script>\n    \u003cscript src=\"js/profile.js\">\u003c/script>\n  \u003c/body>\n\u003c/html>\n","projects.html":"\u003c!doctype html>\n\u003chtml lang=\"en\">\n  \u003chead>\n    \u003cmeta charset=\"utf-8\" />\n    \u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    \u003cmeta\n      http-equiv=\"Content-Security-Policy\"\n      content=\"default-src 'none'; script-src 'self'; style-src 'self' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; img-src 'self' data:; connect-src 'self' https://api.github.com; object-src 'none'; base-uri 'none'; form-action 'none'\"\n    />\n    \u003cmeta\n      name=\"description\"\n      content=\"Projects by Sai Kalyandurg, with GitHub links and a browsable file structure for each repository.\"\n    />\n    \u003ctitle>Sai Kalyandurg, Projects\u003c/title>\n    \u003clink rel=\"icon\" href=\"favicon.svg\" type=\"image/svg+xml\" />\n    \u003clink rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n    \u003clink rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n    \u003clink\n      rel=\"stylesheet\"\n      href=\"https://fonts.googleapis.com/css2?family=Public+Sans:wght@400..700&family=Source+Code+Pro:wght@400;500;600&family=Source+Serif+4:opsz,wght@8..60,400..700&display=swap\"\n    />\n    \u003clink rel=\"stylesheet\" href=\"css/base.css\" />\n    \u003clink rel=\"stylesheet\" href=\"css/projects.css\" />\n  \u003c/head>\n  \u003cbody>\n    \u003ca class=\"skip\" href=\"#top\">Skip to content\u003c/a>\n    \u003cheader class=\"nav\">\n      \u003cdiv class=\"wrap\">\n        \u003ca class=\"brand\" href=\"index.html\" data-site=\"name\">Sai Kalyandurg\u003c/a>\n        \u003cnav aria-label=\"Main\">\n          \u003cul>\n            \u003cli>\u003ca href=\"profile.html\">Profile\u003c/a>\u003c/li>\n            \u003cli>\u003ca href=\"projects.html\" aria-current=\"page\">Projects\u003c/a>\u003c/li>\n            \u003cli>\u003ca href=\"ui.html\">UI skills\u003c/a>\u003c/li>\n            \u003cli>\u003ca href=\"profile.html#contact\">Contact\u003c/a>\u003c/li>\n          \u003c/ul>\n        \u003c/nav>\n        \u003ca class=\"btn btn-primary btn-sm\" href=\"ui.html#source\">Read the source\u003c/a>\n      \u003c/div>\n    \u003c/header>\n    \u003cmain id=\"top\">\n      \u003cdiv class=\"wrap\">\n        \u003caside class=\"say\" aria-label=\"A note from Sai\">\n          \u003cspan class=\"say-avatar\" aria-hidden=\"true\">SK\u003c/span>\n          \u003cdiv class=\"say-body\">\n            \u003cp class=\"say-text\">\n              Here is what I have built. Each project links to its GitHub repository, and you can\n              open its file structure right here before you leave.\n            \u003c/p>\n            \u003cdiv class=\"say-actions\">\n              \u003ca class=\"btn btn-sm\" href=\"#projects\">Projects\u003c/a>\n              \u003ca class=\"btn btn-sm\" href=\"ui.html\">How I build UI\u003c/a>\n            \u003c/div>\n          \u003c/div>\n        \u003c/aside>\n      \u003c/div>\n\n      \u003csection class=\"wrap page-head\" aria-labelledby=\"h-projects\">\n        \u003ch1 id=\"h-projects\">Projects\u003c/h1>\n        \u003cp class=\"page-lede\">\n          Open a project's file structure to see how it is organized. When the repository is linked,\n          the tree is read live from GitHub and every file opens on GitHub.\n        \u003c/p>\n      \u003c/section>\n\n      \u003csection class=\"wrap github\" id=\"github\" aria-labelledby=\"h-github\" hidden>\n        \u003cdiv class=\"github-card\">\n          \u003cdiv>\n            \u003ch2 id=\"h-github\">On GitHub\u003c/h2>\n            \u003cp class=\"gh-handle\" id=\"gh-handle\">\u003c/p>\n            \u003cp class=\"gh-bio\" id=\"gh-bio\">\u003c/p>\n            \u003cp class=\"gh-stats num\" id=\"gh-stats\">\u003c/p>\n            \u003cp class=\"gh-note\" id=\"gh-note\" role=\"status\">\u003c/p>\n          \u003c/div>\n          \u003ca class=\"btn btn-primary\" id=\"gh-open\" href=\"#\" target=\"_blank\" rel=\"noopener noreferrer\"\n            >Open my GitHub profile\u003c/a\n          >\n        \u003c/div>\n      \u003c/section>\n\n      \u003csection class=\"wrap projects\" id=\"projects\" aria-label=\"Project list\">\n        \u003cul class=\"project-list\" id=\"project-list\">\u003c/ul>\n      \u003c/section>\n\n      \u003csection class=\"wrap projects\" id=\"recent\" aria-labelledby=\"h-recent\" hidden>\n        \u003ch2 class=\"list-title\" id=\"h-recent\">Recent repositories\u003c/h2>\n        \u003cul class=\"project-list\" id=\"recent-list\">\u003c/ul>\n      \u003c/section>\n\n      \u003csection class=\"wrap guide\" aria-labelledby=\"h-guide\">\n        \u003ch2 id=\"h-guide\">How to read a repository in two minutes\u003c/h2>\n        \u003col class=\"guide-list\">\n          \u003cli>\n            \u003cstrong>Start with README.md.\u003c/strong> It says what the project does and how to run it.\n          \u003c/li>\n          \u003cli>\n            \u003cstrong>Find the entry point.\u003c/strong> Look in \u003ccode>src/\u003c/code> for a file like\n            \u003ccode>main\u003c/code> or \u003ccode>App\u003c/code>, then follow its imports.\n          \u003c/li>\n          \u003cli>\n            \u003cstrong>Check the tests.\u003c/strong> A \u003ccode>tests/\u003c/code> folder shows what the author\n            considers important to keep working.\n          \u003c/li>\n          \u003cli>\n            \u003cstrong>Look at the automation.\u003c/strong> \u003ccode>.github/workflows/\u003c/code> shows how the\n            project is checked and shipped.\n          \u003c/li>\n        \u003c/ol>\n      \u003c/section>\n\n      \u003csection class=\"next wrap\" aria-labelledby=\"next-title\">\n        \u003ch2 id=\"next-title\">Where to next?\u003c/h2>\n        \u003cp class=\"next-lede\">\n          Projects show what I deliver. The UI skills page shows how I write front-end code, running\n          live.\n        \u003c/p>\n        \u003cdiv class=\"next-grid\">\n          \u003ca class=\"next-card\" href=\"ui.html\">\n            \u003cstrong>UI skills, live\u003c/strong>\n            \u003cspan>Sign in, break it, and read the source behind every behavior.\u003c/span>\n            \u003cem>Open the demo\u003c/em>\n          \u003c/a>\n          \u003ca class=\"next-card\" href=\"profile.html\">\n            \u003cstrong>Profile\u003c/strong>\n            \u003cspan>Experience, results, skills and certifications.\u003c/span>\n            \u003cem>Read the profile\u003c/em>\n          \u003c/a>\n        \u003c/div>\n      \u003c/section>\n    \u003c/main>\n    \u003cfooter class=\"foot\">\n      \u003cdiv class=\"wrap\">\n        \u003cspan>© \u003cspan data-year>\u003c/span> \u003cspan data-site=\"name\">Sai Kalyandurg\u003c/span>\u003c/span>\n        \u003cspan>\n          Plain HTML, CSS and TypeScript.\n          \u003ca href=\"ui.html#source\">Read the source\u003c/a>\n          \u003cspan data-site-show=\"siteRepo\">\n            \u003cspan class=\"foot-sep\" aria-hidden=\"true\">·\u003c/span>\n            \u003ca href=\"#\" data-site-link=\"siteRepo\">This site on GitHub\u003c/a>\n          \u003c/span>\n        \u003c/span>\n      \u003c/div>\n    \u003c/footer>\n    \u003cscript src=\"data/settings.js\">\u003c/script>\n    \u003cscript src=\"data/projects.js\">\u003c/script>\n    \u003cscript src=\"js/common.js\">\u003c/script>\n    \u003cscript src=\"js/github.js\">\u003c/script>\n    \u003cscript src=\"js/projects.js\">\u003c/script>\n  \u003c/body>\n\u003c/html>\n","ui.html":"\u003c!doctype html>\n\u003chtml lang=\"en\">\n  \u003chead>\n    \u003cmeta charset=\"utf-8\" />\n    \u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    \u003cmeta\n      http-equiv=\"Content-Security-Policy\"\n      content=\"default-src 'none'; script-src 'self' https://cdnjs.cloudflare.com; style-src 'self' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; img-src 'self' data:; connect-src 'self'; object-src 'none'; base-uri 'none'; form-action 'none'\"\n    />\n    \u003cmeta\n      name=\"description\"\n      content=\"A working enterprise UI in HTML, CSS, TypeScript and React, with Angular beside it, and the source behind every behavior.\"\n    />\n    \u003ctitle>Sai Kalyandurg, UI skills\u003c/title>\n    \u003clink rel=\"icon\" href=\"favicon.svg\" type=\"image/svg+xml\" />\n    \u003clink rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n    \u003clink rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n    \u003clink\n      rel=\"stylesheet\"\n      href=\"https://fonts.googleapis.com/css2?family=Public+Sans:wght@400..700&family=Source+Code+Pro:wght@400;500;600&family=Source+Serif+4:opsz,wght@8..60,400..700&display=swap\"\n    />\n    \u003clink rel=\"stylesheet\" href=\"css/base.css\" />\n    \u003clink rel=\"stylesheet\" href=\"css/ui.css\" />\n    \u003clink rel=\"stylesheet\" href=\"css/lab.css\" />\n  \u003c/head>\n  \u003cbody>\n    \u003ca class=\"skip\" href=\"#top\">Skip to content\u003c/a>\n    \u003cheader class=\"nav\">\n      \u003cdiv class=\"wrap\">\n        \u003ca class=\"brand\" href=\"index.html\" data-site=\"name\">Sai Kalyandurg\u003c/a>\n        \u003cnav aria-label=\"Main\">\n          \u003cul>\n            \u003cli>\u003ca href=\"profile.html\">Profile\u003c/a>\u003c/li>\n            \u003cli>\u003ca href=\"projects.html\">Projects\u003c/a>\u003c/li>\n            \u003cli>\u003ca href=\"ui.html\" aria-current=\"page\">UI skills\u003c/a>\u003c/li>\n            \u003cli>\u003ca href=\"profile.html#contact\">Contact\u003c/a>\u003c/li>\n          \u003c/ul>\n        \u003c/nav>\n        \u003ca class=\"btn btn-primary btn-sm\" href=\"ui.html#source\">Read the source\u003c/a>\n      \u003c/div>\n    \u003c/header>\n    \u003cmain id=\"top\">\n      \u003cdiv class=\"wrap\">\n        \u003caside class=\"say\" aria-label=\"A note from Sai\">\n          \u003cspan class=\"say-avatar\" aria-hidden=\"true\">SK\u003c/span>\n          \u003cdiv class=\"say-body\">\n            \u003cp class=\"say-text\">\n              This is the part I would show an engineer. The demo below is real code. Try it, then\n              open the files behind it.\n            \u003c/p>\n            \u003cdiv class=\"say-actions\">\n              \u003ca class=\"btn btn-sm\" href=\"#lab\">Try the live demo\u003c/a>\n              \u003ca class=\"btn btn-sm\" href=\"#source\">Read the source\u003c/a>\n            \u003c/div>\n          \u003c/div>\n        \u003c/aside>\n      \u003c/div>\n\n      \u003csection class=\"proof\" id=\"proof\" aria-labelledby=\"proof-title\">\n        \u003cdiv class=\"wrap\">\n          \u003ch1 id=\"proof-title\">Skills are easy to list. This page runs them.\u003c/h1>\n          \u003cp class=\"proof-lede\">\n            Sign-in sessions, role checks, validation, error recovery, state and responsive layouts\n            are working code on this page, written in HTML, CSS, TypeScript and React, with the\n            Angular equivalents beside them. Try each one, then read the code behind it.\n          \u003c/p>\n          \u003cdiv class=\"cta\">\n            \u003ca class=\"btn btn-light\" href=\"#lab\">Try the live demo\u003c/a>\n            \u003ca class=\"btn btn-outline-light\" href=\"#source\">Read the source code\u003c/a>\n          \u003c/div>\n          \u003cul class=\"concerns\">\n            \u003cli class=\"concern\">\n              \u003ch2>Authentication\u003c/h2>\n              \u003cp>\n                Sign in against a simulated server. Sessions expire, renew and end cleanly, and the\n                token stays in memory, never in localStorage.\n              \u003c/p>\n              \u003cdiv class=\"cta\">\n                \u003cbutton type=\"button\" class=\"btn btn-light btn-sm\" data-try=\"session\">\n                  Try it\n                \u003c/button>\n                \u003cbutton type=\"button\" class=\"btn btn-outline-light btn-sm\" data-code=\"tsx:session\">\n                  Read the code\n                \u003c/button>\n              \u003c/div>\n            \u003c/li>\n            \u003cli class=\"concern\">\n              \u003ch2>Authorization\u003c/h2>\n              \u003cp>\n                Roles decide what the screen offers and what the API accepts. A viewer who skips the\n                button still gets a 403.\n              \u003c/p>\n              \u003cdiv class=\"cta\">\n                \u003cbutton type=\"button\" class=\"btn btn-light btn-sm\" data-try=\"risks\">Try it\u003c/button>\n                \u003cbutton\n                  type=\"button\"\n                  class=\"btn btn-outline-light btn-sm\"\n                  data-code=\"tsx:permissions\"\n                >\n                  Read the code\n                \u003c/button>\n              \u003c/div>\n            \u003c/li>\n            \u003cli class=\"concern\">\n              \u003ch2>Validation\u003c/h2>\n              \u003cp>\n                Fields check on blur and on submit, errors are announced, focus lands on the first\n                problem, and the server re-checks every payload.\n              \u003c/p>\n              \u003cdiv class=\"cta\">\n                \u003cbutton type=\"button\" class=\"btn btn-light btn-sm\" data-try=\"validation\">\n                  Try it\n                \u003c/button>\n                \u003cbutton type=\"button\" class=\"btn btn-outline-light btn-sm\" data-code=\"tsx:parse\">\n                  Read the code\n                \u003c/button>\n              \u003c/div>\n            \u003c/li>\n            \u003cli class=\"concern\">\n              \u003ch2>Security\u003c/h2>\n              \u003cp>\n                Untrusted text is escaped or sanitized against an allow-list, links are limited to\n                https, and sign-in resists guessing.\n              \u003c/p>\n              \u003cdiv class=\"cta\">\n                \u003cbutton type=\"button\" class=\"btn btn-light btn-sm\" data-try=\"validation\">\n                  Try it\n                \u003c/button>\n                \u003cbutton type=\"button\" class=\"btn btn-outline-light btn-sm\" data-code=\"tsx:sanitize\">\n                  Read the code\n                \u003c/button>\n              \u003c/div>\n            \u003c/li>\n            \u003cli class=\"concern\">\n              \u003ch2>Error handling\u003c/h2>\n              \u003cp>\n                Timeouts, retries with backoff, typed errors and an error boundary. Failures say\n                what happened and what to do next.\n              \u003c/p>\n              \u003cdiv class=\"cta\">\n                \u003cbutton type=\"button\" class=\"btn btn-light btn-sm\" data-try=\"failures\">\n                  Try it\n                \u003c/button>\n                \u003cbutton type=\"button\" class=\"btn btn-outline-light btn-sm\" data-code=\"tsx:retry\">\n                  Read the code\n                \u003c/button>\n              \u003c/div>\n            \u003c/li>\n            \u003cli class=\"concern\">\n              \u003ch2>State management\u003c/h2>\n              \u003cp>\n                One reducer owns the data. Updates show instantly and roll back if the request\n                fails, and the live state is on screen.\n              \u003c/p>\n              \u003cdiv class=\"cta\">\n                \u003cbutton type=\"button\" class=\"btn btn-light btn-sm\" data-try=\"risks\">Try it\u003c/button>\n                \u003cbutton type=\"button\" class=\"btn btn-outline-light btn-sm\" data-code=\"tsx:reducer\">\n                  Read the code\n                \u003c/button>\n              \u003c/div>\n            \u003c/li>\n            \u003cli class=\"concern\">\n              \u003ch2>Responsive UI\u003c/h2>\n              \u003cp>\n                The table responds to its container, not just the screen. Drag its corner and watch\n                it turn into cards.\n              \u003c/p>\n              \u003cdiv class=\"cta\">\n                \u003cbutton type=\"button\" class=\"btn btn-light btn-sm\" data-try=\"risks\">Try it\u003c/button>\n                \u003cbutton\n                  type=\"button\"\n                  class=\"btn btn-outline-light btn-sm\"\n                  data-code=\"css:container\"\n                >\n                  Read the code\n                \u003c/button>\n              \u003c/div>\n            \u003c/li>\n            \u003cli class=\"concern\">\n              \u003ch2>Angular\u003c/h2>\n              \u003cp>\n                A route guard, an HTTP interceptor, a signal store and typed forms, written the\n                Angular way and compiled with the strict Angular compiler.\n              \u003c/p>\n              \u003cdiv class=\"cta\">\n                \u003cbutton\n                  type=\"button\"\n                  class=\"btn btn-outline-light btn-sm\"\n                  data-code=\"ng:interceptor\"\n                >\n                  Read the code\n                \u003c/button>\n              \u003c/div>\n            \u003c/li>\n          \u003c/ul>\n          \u003cp class=\"proof-note\">\n            The demo's server is simulated inside the page, so sign-in, permissions and failures\n            behave like a real API with no network calls. The Angular files pass the strict\n            compiler, but they are source only and do not run on this page.\n          \u003c/p>\n        \u003c/div>\n      \u003c/section>\n\n      \u003csection class=\"wrap lab\" id=\"lab\" aria-labelledby=\"lab-title\">\n        \u003cdiv class=\"lab-intro\">\n          \u003ch2 id=\"lab-title\">Live demo: a small enterprise app\u003c/h2>\n          \u003cp>\n            Start on the Session tab and sign in as the viewer or the admin. Then try the risk log,\n            the forms and the failure scenarios. Every behavior you see is in the code below.\n          \u003c/p>\n        \u003c/div>\n        \u003cdiv id=\"lab-root\">\u003cp class=\"lab-loading\">Loading the demo...\u003c/p>\u003c/div>\n      \u003c/section>\n\n      \u003csection class=\"source\" id=\"source\" aria-labelledby=\"source-title\">\n        \u003cdiv class=\"wrap source-inner\">\n          \u003cdiv>\n            \u003ch2 id=\"source-title\">Every file behind this site\u003c/h2>\n            \u003cp class=\"intro\">\n              Nothing on this page is a screenshot or a list of claims. The explorer below opens the\n              files this page is running right now, and each skill button jumps to the lines that\n              prove it.\n            \u003c/p>\n            \u003cspan class=\"source-status\" id=\"source-status\" role=\"status\"\n              >Loading the source files...\u003c/span\n            >\n          \u003c/div>\n          \u003cdiv class=\"tablist\" role=\"tablist\" aria-label=\"Source language\">\n            \u003cbutton\n              class=\"tab\"\n              role=\"tab\"\n              id=\"tab-html\"\n              aria-controls=\"explorer\"\n              aria-selected=\"false\"\n              tabindex=\"-1\"\n              type=\"button\"\n            >\n              HTML\u003csmall>\u003c/small>\n            \u003c/button>\n            \u003cbutton\n              class=\"tab\"\n              role=\"tab\"\n              id=\"tab-css\"\n              aria-controls=\"explorer\"\n              aria-selected=\"false\"\n              tabindex=\"-1\"\n              type=\"button\"\n            >\n              CSS\u003csmall>\u003c/small>\n            \u003c/button>\n            \u003cbutton\n              class=\"tab\"\n              role=\"tab\"\n              id=\"tab-js\"\n              aria-controls=\"explorer\"\n              aria-selected=\"false\"\n              tabindex=\"-1\"\n              type=\"button\"\n            >\n              JavaScript\u003csmall>\u003c/small>\n            \u003c/button>\n            \u003cbutton\n              class=\"tab\"\n              role=\"tab\"\n              id=\"tab-tsx\"\n              aria-controls=\"explorer\"\n              aria-selected=\"true\"\n              tabindex=\"0\"\n              type=\"button\"\n            >\n              React + TypeScript\u003csmall>\u003c/small>\n            \u003c/button>\n            \u003cbutton\n              class=\"tab\"\n              role=\"tab\"\n              id=\"tab-ng\"\n              aria-controls=\"explorer\"\n              aria-selected=\"false\"\n              tabindex=\"-1\"\n              type=\"button\"\n            >\n              Angular\u003csmall>\u003c/small>\n            \u003c/button>\n          \u003c/div>\n          \u003cp class=\"tab-note\" id=\"tab-note\">\u003c/p>\n          \u003cdiv\n            class=\"skills\"\n            id=\"skills\"\n            role=\"group\"\n            aria-label=\"Skills used in these files\"\n          >\u003c/div>\n          \u003cp class=\"skill-note\" id=\"skill-note\" aria-live=\"polite\">\u003c/p>\n          \u003cdiv class=\"explorer\" id=\"explorer\" role=\"tabpanel\" aria-labelledby=\"tab-tsx\">\n            \u003cdiv class=\"files\" id=\"files\" role=\"group\" aria-label=\"Files\">\u003c/div>\n            \u003cdiv class=\"pane\">\n              \u003cdiv class=\"pane-head\">\n                \u003cp>\n                  \u003ccode class=\"pane-path\" id=\"pane-path\">\u003c/code\n                  >\u003cspan class=\"pane-meta\" id=\"pane-meta\">\u003c/span>\n                \u003c/p>\n                \u003cbutton class=\"copy\" id=\"copy-code\" type=\"button\">Copy file\u003c/button>\n              \u003c/div>\n              \u003cdiv class=\"codebox\" id=\"codebox\" role=\"region\" tabindex=\"0\" aria-label=\"Source code\">\n                \u003cpre>\u003ccode id=\"code\">Loading the source files...\u003c/code>\u003c/pre>\n              \u003c/div>\n            \u003c/div>\n          \u003c/div>\n        \u003c/div>\n      \u003c/section>\n\n      \u003csection class=\"next wrap\" aria-labelledby=\"next-title\">\n        \u003ch2 id=\"next-title\">Where to next?\u003c/h2>\n        \u003cp class=\"next-lede\">\n          You have seen the code run. The projects page shows what I have shipped, and the profile\n          has the rest.\n        \u003c/p>\n        \u003cdiv class=\"next-grid\">\n          \u003ca class=\"next-card\" href=\"projects.html\">\n            \u003cstrong>Projects on GitHub\u003c/strong>\n            \u003cspan>Browse each project's file structure and open the files.\u003c/span>\n            \u003cem>See the projects\u003c/em>\n          \u003c/a>\n          \u003ca class=\"next-card\" href=\"profile.html\">\n            \u003cstrong>Profile\u003c/strong>\n            \u003cspan>Experience, results, skills and certifications.\u003c/span>\n            \u003cem>Read the profile\u003c/em>\n          \u003c/a>\n        \u003c/div>\n      \u003c/section>\n    \u003c/main>\n    \u003cfooter class=\"foot\">\n      \u003cdiv class=\"wrap\">\n        \u003cspan>© \u003cspan data-year>\u003c/span> \u003cspan data-site=\"name\">Sai Kalyandurg\u003c/span>\u003c/span>\n        \u003cspan>\n          Plain HTML, CSS and TypeScript.\n          \u003ca href=\"ui.html#source\">Read the source\u003c/a>\n          \u003cspan data-site-show=\"siteRepo\">\n            \u003cspan class=\"foot-sep\" aria-hidden=\"true\">·\u003c/span>\n            \u003ca href=\"#\" data-site-link=\"siteRepo\">This site on GitHub\u003c/a>\n          \u003c/span>\n        \u003c/span>\n      \u003c/div>\n    \u003c/footer>\n    \u003cscript src=\"data/settings.js\">\u003c/script>\n    \u003cscript src=\"data/source-files.js\">\u003c/script>\n    \u003cscript src=\"data/skills-map.js\">\u003c/script>\n    \u003cscript src=\"https://cdnjs.cloudflare.com/ajax/libs/react/18.3.1/umd/react.production.min.js\">\u003c/script>\n    \u003cscript src=\"https://cdnjs.cloudflare.com/ajax/libs/react-dom/18.3.1/umd/react-dom.production.min.js\">\u003c/script>\n    \u003cscript src=\"https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js\">\u003c/script>\n    \u003cscript src=\"js/common.js\">\u003c/script>\n    \u003cscript src=\"js/viewer.js\">\u003c/script>\n    \u003cscript src=\"js/lab.js\">\u003c/script>\n    \u003cscript src=\"js/ui.js\">\u003c/script>\n  \u003c/body>\n\u003c/html>\n","css/base.css":"/* Shared styles: design tokens, type, buttons, navigation, and the two pieces of \"conversation\" used on every page\n   (the .say message at the top and the .next prompt at the bottom). */\n:root {\n  --bg: #f5f6f8;\n  --surface: #ffffff;\n  --ink: #14181f;\n  --muted: #566070;\n  --rule: #d8dde4;\n  --accent: #1e4e8c;\n  --accent-ink: #ffffff;\n  --focus: #1e4e8c;\n  --ok: #1d6b3a;\n  --err: #a32a2a;\n  --ok-bg: #e3f3e8;\n  --warn-bg: #fff3d1;\n  --warn-ink: #5c4300;\n  --bad-bg: #fbe4e4;\n  --band: #11243d;\n  --band-ink: #f1f5fa;\n  --band-muted: #b4c3d8;\n  --band-line: rgba(255, 255, 255, 0.45);\n  --band-faint: rgba(255, 255, 255, 0.1);\n  --gutter: clamp(1rem, 4vw, 2rem);\n  --serif: \"Source Serif 4\", Georgia, \"Times New Roman\", serif;\n  --sans: \"Public Sans\", system-ui, -apple-system, \"Segoe UI\", Roboto, Arial, sans-serif;\n  --mono: \"Source Code Pro\", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n  --tok-kw: #7a3e9d;\n  --tok-str: #1b6b3a;\n  --tok-com: #5f6b7b;\n  --tok-num: #a64b00;\n  --tok-fn: #1e4e8c;\n  --tok-attr: #8a4a00;\n  --hit: rgba(30, 78, 140, 0.14);\n}\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme=\"light\"]) {\n    --bg: #0f1318;\n    --surface: #161b22;\n    --ink: #e7ebf1;\n    --muted: #9aa5b4;\n    --rule: #29313c;\n    --accent: #8db4ea;\n    --accent-ink: #0f1318;\n    --focus: #8db4ea;\n    --ok: #6cc58b;\n    --err: #f08a8a;\n    --ok-bg: #16301f;\n    --warn-bg: #3a2f12;\n    --warn-ink: #f3d98b;\n    --bad-bg: #3a1a1a;\n    --band: #172c49;\n    --tok-kw: #c6a0f0;\n    --tok-str: #7fd39b;\n    --tok-com: #8794a5;\n    --tok-num: #f0a868;\n    --tok-fn: #8db4ea;\n    --tok-attr: #e8b27a;\n    --hit: rgba(141, 180, 234, 0.2);\n    color-scheme: dark;\n  }\n}\n:root[data-theme=\"dark\"] {\n  --bg: #0f1318;\n  --surface: #161b22;\n  --ink: #e7ebf1;\n  --muted: #9aa5b4;\n  --rule: #29313c;\n  --accent: #8db4ea;\n  --accent-ink: #0f1318;\n  --focus: #8db4ea;\n  --ok: #6cc58b;\n  --err: #f08a8a;\n  --ok-bg: #16301f;\n  --warn-bg: #3a2f12;\n  --warn-ink: #f3d98b;\n  --bad-bg: #3a1a1a;\n  --band: #172c49;\n  --tok-kw: #c6a0f0;\n  --tok-str: #7fd39b;\n  --tok-com: #8794a5;\n  --tok-num: #f0a868;\n  --tok-fn: #8db4ea;\n  --tok-attr: #e8b27a;\n  --hit: rgba(141, 180, 234, 0.2);\n  color-scheme: dark;\n}\n\n*,\n*::before,\n*::after {\n  box-sizing: border-box;\n}\n[hidden] {\n  display: none !important;\n}\nhtml {\n  scroll-padding-top: 4.5rem;\n}\n@media (prefers-reduced-motion: no-preference) {\n  html {\n    scroll-behavior: smooth;\n  }\n  /* Browsers that support it cross-fade between pages instead of flashing white. */\n  @view-transition {\n    navigation: auto;\n  }\n}\nbody {\n  margin: 0;\n  background: var(--bg);\n  color: var(--ink);\n  font: 400 1.0625rem/1.68 var(--sans);\n  font-feature-settings:\n    \"kern\" 1,\n    \"liga\" 1;\n  -webkit-font-smoothing: antialiased;\n  text-rendering: optimizeLegibility;\n}\na {\n  color: var(--accent);\n  text-underline-offset: 3px;\n  text-decoration-thickness: 1px;\n}\na:hover {\n  text-decoration-thickness: 2px;\n}\n:focus-visible {\n  outline: 2px solid var(--focus);\n  outline-offset: 3px;\n  border-radius: 2px;\n}\nh1,\nh2,\nh3,\nh4 {\n  font-family: var(--serif);\n  font-weight: 600;\n  margin: 0;\n  text-wrap: balance;\n  letter-spacing: -0.012em;\n}\np {\n  margin: 0;\n  text-wrap: pretty;\n}\nul,\nol {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n.sr-only {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip-path: inset(50%);\n  white-space: nowrap;\n}\n.num {\n  font-variant-numeric: tabular-nums lining-nums;\n}\n.wrap {\n  max-width: 66rem;\n  margin-inline: auto;\n  padding-inline: var(--gutter);\n}\n\n/* Buttons: one base, a few variants. Used for links and real buttons alike. */\n.btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 0.5rem;\n  font: 600 0.95rem/1.1 var(--sans);\n  letter-spacing: 0.005em;\n  text-decoration: none;\n  cursor: pointer;\n  color: var(--ink);\n  background: var(--surface);\n  border: 1px solid var(--rule);\n  border-radius: 6px;\n  padding: 0.8rem 1.3rem;\n  transition:\n    background-color 0.15s,\n    border-color 0.15s,\n    color 0.15s,\n    transform 0.15s;\n}\n.btn:hover {\n  border-color: var(--ink);\n  text-decoration: none;\n}\n.btn-primary {\n  background: var(--accent);\n  border-color: var(--accent);\n  color: var(--accent-ink);\n}\n.btn-primary:hover {\n  border-color: var(--accent);\n  filter: brightness(1.12);\n}\n.btn-sm {\n  font-size: 0.85rem;\n  padding: 0.5rem 0.9rem;\n}\n.btn-light {\n  background: var(--band-ink);\n  border-color: var(--band-ink);\n  color: #11243d;\n}\n.btn-light:hover {\n  background: #ffffff;\n  border-color: #ffffff;\n}\n.btn-outline-light {\n  background: transparent;\n  border-color: var(--band-line);\n  color: var(--band-ink);\n}\n.btn-outline-light:hover {\n  border-color: var(--band-ink);\n  background: rgba(255, 255, 255, 0.08);\n}\n.btn[aria-expanded=\"true\"] {\n  background: var(--accent);\n  border-color: var(--accent);\n  color: var(--accent-ink);\n}\n.btn[disabled] {\n  opacity: 0.55;\n  cursor: not-allowed;\n}\n.cta {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.75rem;\n}\n\n/* Skip link: invisible until a keyboard user tabs to it. */\n.skip {\n  position: absolute;\n  left: 1rem;\n  top: -4rem;\n  z-index: 20;\n  padding: 0.6rem 1rem;\n  background: var(--ink);\n  color: var(--bg);\n  border-radius: 0 0 6px 6px;\n  font-weight: 600;\n  text-decoration: none;\n}\n.skip:focus {\n  top: 0;\n}\n\n/* Navigation */\n.nav {\n  position: sticky;\n  top: env(safe-area-inset-top, 0px);\n  z-index: 5;\n  background: var(--bg);\n  border-bottom: 1px solid var(--rule);\n}\n.nav .wrap {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 0.5rem 1.5rem;\n  padding-block: 0.7rem;\n}\n.nav .brand {\n  font-family: var(--serif);\n  font-weight: 600;\n  font-size: 1.1rem;\n  color: var(--ink);\n  text-decoration: none;\n}\n.nav ul {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.25rem 1.4rem;\n}\n.nav ul a {\n  color: var(--muted);\n  text-decoration: none;\n  font-size: 0.9rem;\n  font-weight: 500;\n  padding-block: 0.2rem;\n  border-bottom: 2px solid transparent;\n}\n.nav ul a:hover {\n  color: var(--ink);\n}\n.nav ul a[aria-current=\"page\"] {\n  color: var(--ink);\n  border-bottom-color: var(--accent);\n}\n\n/* Section rules stop at the text edge, not at the page gutter. */\n.next,\n.guide,\n.section {\n  background: linear-gradient(var(--rule), var(--rule)) top center / calc(100% - 2 * var(--gutter))\n    1px no-repeat;\n}\n\n/* The \"conversation\": a short message from Sai at the top of a page, and a question at the bottom. */\n.say {\n  display: grid;\n  grid-template-columns: auto minmax(0, 1fr);\n  gap: 0.9rem;\n  align-items: start;\n  max-width: 44rem;\n  padding-block: clamp(1.5rem, 4vw, 2.25rem) 0;\n}\n.say-avatar {\n  display: grid;\n  place-items: center;\n  width: 2.5rem;\n  height: 2.5rem;\n  border-radius: 50%;\n  background: var(--band);\n  color: var(--band-ink);\n  font: 600 0.85rem/1 var(--sans);\n  letter-spacing: 0.04em;\n}\n.say-body {\n  display: grid;\n  gap: 0.85rem;\n  justify-items: start;\n}\n.say-text {\n  font-family: var(--serif);\n  font-size: 1.2rem;\n  line-height: 1.5;\n}\n.say-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.5rem;\n}\n@media (prefers-reduced-motion: no-preference) {\n  .say {\n    animation: rise 0.6s 0.1s both;\n  }\n}\n@keyframes rise {\n  from {\n    opacity: 0;\n    transform: translateY(0.75rem);\n  }\n}\n\n.next {\n  margin-top: clamp(2.5rem, 6vw, 4rem);\n  padding-block: clamp(2.25rem, 5vw, 3.25rem);\n}\n.next h2 {\n  font-size: 1.6rem;\n  font-weight: 500;\n}\n.next-lede {\n  margin-top: 0.4rem;\n  color: var(--muted);\n  max-width: 40rem;\n}\n.next-grid {\n  margin-top: 1.5rem;\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));\n  gap: 1rem;\n}\n.next-card {\n  display: grid;\n  gap: 0.35rem;\n  align-content: start;\n  padding: 1.15rem 1.25rem 1.25rem;\n  background: var(--surface);\n  border: 1px solid var(--rule);\n  border-radius: 8px;\n  color: var(--ink);\n  text-decoration: none;\n  transition:\n    border-color 0.15s,\n    transform 0.15s;\n}\n.next-card:hover {\n  border-color: var(--accent);\n  transform: translateY(-2px);\n  text-decoration: none;\n}\n.next-card strong {\n  font-family: var(--serif);\n  font-size: 1.15rem;\n  font-weight: 600;\n}\n.next-card span {\n  color: var(--muted);\n  font-size: 0.95rem;\n  line-height: 1.5;\n}\n.next-card em {\n  margin-top: 0.4rem;\n  font-style: normal;\n  font-weight: 600;\n  font-size: 0.9rem;\n  color: var(--accent);\n}\n\n.foot {\n  border-top: 1px solid var(--rule);\n  padding-block: 1.75rem 2.5rem;\n  color: var(--muted);\n  font-size: 0.9rem;\n}\n.foot .wrap {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: space-between;\n  gap: 0.5rem 1.5rem;\n}\n\n.tag {\n  display: inline-block;\n  font-family: var(--sans);\n  font-weight: 500;\n  font-size: 0.75rem;\n  line-height: 1.5;\n  color: var(--muted);\n  border: 1px solid var(--rule);\n  border-radius: 3px;\n  padding: 0 0.4rem;\n}\n\n@media (max-width: 800px) {\n  .nav {\n    position: static;\n  }\n}\n","css/entrance.css":"/* Entrance: a navy stage, slow-moving real code behind the text, a typed greeting, then two choices.\n   Every animation ends on the visible state, so the page is complete even if animations never run. */\nbody.entrance {\n  background: var(--band);\n  color: var(--band-ink);\n  min-height: 100vh;\n  min-height: 100dvh;\n  overflow-x: clip;\n}\n.stage {\n  position: relative;\n  display: grid;\n  align-items: center;\n  min-height: 100vh;\n  min-height: 100dvh;\n  padding-block: clamp(2rem, 6vw, 4rem);\n  isolation: isolate;\n}\n\n/* Ambient code. It is decoration, so it is hidden from assistive technology and kept faint. */\n.codefall {\n  position: absolute;\n  inset: 0;\n  z-index: -1;\n  display: flex;\n  justify-content: space-around;\n  gap: 2rem;\n  overflow: hidden;\n  padding-inline: 1rem;\n  color: var(--band-ink);\n  opacity: 0.08;\n  -webkit-mask-image: radial-gradient(ellipse 80% 75% at 40% 50%, transparent 35%, #000 100%);\n  mask-image: radial-gradient(ellipse 80% 75% at 40% 50%, transparent 35%, #000 100%);\n}\n.codefall pre {\n  margin: 0;\n  flex: 0 1 22rem;\n  min-width: 0;\n  font: 400 0.8rem/1.75 var(--mono);\n  white-space: pre;\n  overflow: hidden;\n}\n.codefall pre:nth-child(2) {\n  margin-top: -6rem;\n}\n@media (max-width: 800px) {\n  .codefall pre:nth-child(n + 2) {\n    display: none;\n  }\n}\n@media (prefers-reduced-motion: no-preference) {\n  .codefall pre {\n    animation: drift 90s linear infinite;\n  }\n  .codefall pre:nth-child(2) {\n    animation-duration: 120s;\n  }\n  .codefall pre:nth-child(3) {\n    animation-duration: 105s;\n  }\n}\n@keyframes drift {\n  to {\n    transform: translateY(-50%);\n  }\n}\n\n.intro {\n  width: 100%;\n  display: grid;\n  gap: 1.1rem;\n  justify-items: start;\n}\n.kicker {\n  font: 500 0.82rem/1.4 var(--mono);\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: var(--band-muted);\n}\n.greet {\n  font-family: var(--serif);\n  font-weight: 500;\n  font-size: clamp(2.6rem, 8vw, 5.2rem);\n  line-height: 1.02;\n  letter-spacing: -0.03em;\n  max-width: 16ch;\n  min-height: 2.04em;\n}\n.greet .caret {\n  display: inline-block;\n  width: 0.06em;\n  height: 0.85em;\n  margin-left: 0.06em;\n  vertical-align: -0.06em;\n  background: var(--band-ink);\n}\n.greet .caret.is-done {\n  opacity: 0;\n}\n.lede {\n  max-width: 38rem;\n  color: var(--band-muted);\n  font-size: clamp(1.05rem, 2.2vw, 1.25rem);\n  line-height: 1.6;\n}\n.ask {\n  margin-top: clamp(0.75rem, 3vw, 1.75rem);\n  font-family: var(--serif);\n  font-size: clamp(1.35rem, 3vw, 1.75rem);\n}\n.choices {\n  width: 100%;\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 1.1rem;\n}\n.choice {\n  position: relative;\n  display: grid;\n  gap: 0.6rem;\n  align-content: start;\n  padding: 1.5rem 1.6rem 1.6rem;\n  background: var(--bg);\n  color: var(--ink);\n  border: 1px solid transparent;\n  border-radius: 10px;\n  text-decoration: none;\n  transition:\n    transform 0.2s,\n    border-color 0.2s,\n    box-shadow 0.2s,\n    background-color 0.2s;\n}\n.choice:hover,\n.choice:focus-visible {\n  transform: translateY(-4px);\n  background: var(--surface);\n  box-shadow: 0 14px 34px rgba(0, 0, 0, 0.35);\n  text-decoration: none;\n}\n.choice:focus-visible {\n  outline: 3px solid var(--band-ink);\n  outline-offset: 3px;\n}\n.choice-label {\n  font: 600 0.78rem/1.3 var(--mono);\n  letter-spacing: 0.08em;\n  text-transform: uppercase;\n  color: var(--accent);\n}\n.choice-title {\n  font-family: var(--serif);\n  font-size: clamp(1.4rem, 3vw, 1.8rem);\n  font-weight: 600;\n  line-height: 1.2;\n}\n.choice-text {\n  color: var(--muted);\n  font-size: 1rem;\n  line-height: 1.55;\n}\n.choice-peek {\n  margin: 0.4rem 0 0;\n  padding: 0.7rem 0.9rem;\n  background: var(--bg);\n  border: 1px solid var(--rule);\n  border-radius: 6px;\n  font: 400 0.78rem/1.65 var(--mono);\n  color: var(--ink);\n  white-space: pre;\n  overflow: hidden;\n}\n.choice:hover .choice-peek,\n.choice:focus-visible .choice-peek {\n  background: var(--surface);\n}\n.choice-go {\n  margin-top: 0.4rem;\n  font-weight: 600;\n  font-size: 0.95rem;\n  color: var(--accent);\n}\n.choice-go::after {\n  content: \"\";\n  display: inline-block;\n  width: 0.55em;\n  height: 0.55em;\n  margin-left: 0.5em;\n  border-top: 2px solid currentColor;\n  border-right: 2px solid currentColor;\n  transform: rotate(45deg) translate(-0.1em, 0.1em);\n  transition: margin-left 0.2s;\n}\n.choice:hover .choice-go::after,\n.choice:focus-visible .choice-go::after {\n  margin-left: 0.9em;\n}\n.quick {\n  font-size: 0.95rem;\n  color: var(--band-muted);\n}\n.quick a {\n  color: var(--band-ink);\n}\n\n/* Page load sequence: one orchestrated moment. */\n@media (prefers-reduced-motion: no-preference) {\n  .kicker {\n    animation: rise 0.7s 0.1s both;\n  }\n  .lede {\n    animation: rise 0.8s 1.7s both;\n  }\n  .ask {\n    animation: rise 0.7s 2.3s both;\n  }\n  .choice:nth-child(1) {\n    animation: rise 0.8s 2.55s both;\n  }\n  .choice:nth-child(2) {\n    animation: rise 0.8s 2.75s both;\n  }\n  .quick {\n    animation: rise 0.7s 3.1s both;\n  }\n  .greet .caret {\n    animation: blink 1s steps(1) infinite;\n  }\n}\n@keyframes blink {\n  50% {\n    opacity: 0;\n  }\n}\n\n/* Leaving: the chosen card holds still, the rest fade, and a curtain covers the page. */\n.curtain {\n  position: fixed;\n  inset: 0;\n  z-index: 10;\n  background: var(--bg);\n  opacity: 0;\n  pointer-events: none;\n}\n.stage.is-leaving .choice:not(.is-chosen),\n.stage.is-leaving .intro > :not(.choices) {\n  opacity: 0;\n  transition: opacity 0.3s;\n}\n.stage.is-leaving .choice.is-chosen {\n  transform: scale(1.03);\n  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.4);\n}\n.stage.is-leaving ~ .curtain {\n  opacity: 1;\n  transition: opacity 0.35s 0.2s;\n}\n@media (prefers-reduced-motion: reduce) {\n  .stage.is-leaving ~ .curtain,\n  .stage.is-leaving .choice:not(.is-chosen),\n  .stage.is-leaving .intro > :not(.choices) {\n    transition: none;\n  }\n}\n\n@media (max-width: 800px) {\n  .choices {\n    grid-template-columns: minmax(0, 1fr);\n  }\n  .greet {\n    min-height: 0;\n  }\n}\n","css/profile.css":"/* Profile page: introduction, results, experience, skills, credentials and contact. */\n.hero {\n  display: grid;\n  grid-template-columns: minmax(0, 1.6fr) minmax(0, 1fr);\n  gap: 2.5rem 4.5rem;\n  padding-block: clamp(2rem, 5vw, 3.5rem) clamp(2.5rem, 5vw, 3.5rem);\n  align-items: start;\n}\n.hero h1 {\n  font-size: clamp(3rem, 8.5vw, 5.4rem);\n  font-weight: 500;\n  line-height: 0.98;\n  letter-spacing: -0.035em;\n}\n.hero .title-line {\n  margin-top: 1rem;\n  font-family: var(--serif);\n  font-size: 1.35rem;\n  color: var(--muted);\n}\n.hero .lede {\n  margin-top: 1.5rem;\n  max-width: 36rem;\n  font-family: var(--serif);\n  font-size: clamp(1.18rem, 2.1vw, 1.38rem);\n  line-height: 1.55;\n}\n.hero .cta {\n  margin-top: 2rem;\n}\n.facts {\n  margin: 0;\n  border-left: 1px solid var(--rule);\n  padding-left: 2rem;\n  display: grid;\n  gap: 1.25rem;\n}\n.facts dt {\n  font-size: 0.875rem;\n  color: var(--muted);\n}\n.facts dd {\n  margin: 0.15rem 0 0;\n  font-weight: 500;\n  line-height: 1.45;\n}\n.facts dd small {\n  display: block;\n  margin-top: 0.1rem;\n  font-weight: 400;\n  color: var(--muted);\n  font-size: 0.9rem;\n}\n\n/* Results: four numbers from the resume, set as a quiet row. */\n.results-list {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr));\n  gap: 1.5rem 2rem;\n  padding-block: 1.75rem;\n  border-block: 1px solid var(--rule);\n}\n.result {\n  display: grid;\n  gap: 0.3rem;\n  align-content: start;\n}\n.result strong {\n  font-family: var(--serif);\n  font-size: clamp(1.7rem, 3.4vw, 2.2rem);\n  font-weight: 500;\n  letter-spacing: -0.02em;\n  line-height: 1.1;\n  font-variant-numeric: lining-nums;\n}\n.result span {\n  color: var(--muted);\n  font-size: 0.925rem;\n  line-height: 1.45;\n}\n\n/* Sections */\n.section {\n  display: grid;\n  grid-template-columns: 11.5rem minmax(0, 1fr);\n  gap: 1.25rem 3rem;\n  padding-block: 3.25rem;\n}\n#summary {\n  background: none;\n}\n.section > h2 {\n  font-size: 1.6rem;\n  font-weight: 500;\n  line-height: 1.2;\n}\n.section > div,\n.section > dl {\n  min-width: 0;\n}\n.prose {\n  max-width: 44rem;\n  font-size: 1.1rem;\n}\n\n/* Experience */\n.role + .role {\n  margin-top: 3.25rem;\n}\n.role-head {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: space-between;\n  align-items: baseline;\n  gap: 0.15rem 1.5rem;\n}\n.role-head h3 {\n  font-size: 1.4rem;\n}\n.role-head .when {\n  color: var(--muted);\n  font-size: 0.9rem;\n  font-variant-numeric: tabular-nums;\n}\n.role .where {\n  color: var(--muted);\n  font-size: 0.975rem;\n  margin-top: 0.15rem;\n}\n.bullets {\n  margin-top: 1.1rem;\n  display: grid;\n  gap: 0.7rem;\n  max-width: 44rem;\n}\n.bullets li {\n  position: relative;\n  padding-left: 1.2rem;\n}\n.bullets li::before {\n  content: \"\";\n  position: absolute;\n  left: 0;\n  top: 0.8em;\n  width: 0.5rem;\n  height: 1px;\n  background: var(--muted);\n}\n.more {\n  margin-top: 0.7rem;\n  max-width: 44rem;\n}\n.more summary {\n  display: inline-flex;\n  align-items: center;\n  font-weight: 600;\n  font-size: 0.9rem;\n  color: var(--accent);\n  border: 1px solid var(--rule);\n  border-radius: 6px;\n  padding: 0.45rem 0.85rem;\n  cursor: pointer;\n  list-style: none;\n  background: var(--surface);\n}\n.more summary::-webkit-details-marker {\n  display: none;\n}\n.more summary:hover {\n  border-color: var(--accent);\n}\n.more[open] summary {\n  margin-bottom: 0.9rem;\n}\n.more .when-open,\n.more[open] .when-closed {\n  display: none;\n}\n.more[open] .when-open {\n  display: inline;\n}\n.stack {\n  margin-top: 1.1rem;\n  max-width: 44rem;\n  color: var(--muted);\n  font-size: 0.9rem;\n  line-height: 1.6;\n}\n.stack strong {\n  color: var(--ink);\n  font-weight: 600;\n}\n\n/* Skills and credentials */\n.defs {\n  margin: 0;\n  display: grid;\n  gap: 1.5rem;\n}\n.defs > div {\n  display: grid;\n  grid-template-columns: 12rem minmax(0, 1fr);\n  gap: 0.5rem 2rem;\n  align-items: baseline;\n}\n.defs dt {\n  font-weight: 600;\n}\n.defs dd {\n  margin: 0;\n}\n.chips {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.4rem 0.4rem;\n}\n.chips li {\n  font-size: 0.875rem;\n  line-height: 1.4;\n  padding: 0.2rem 0.6rem;\n  background: var(--surface);\n  border: 1px solid var(--rule);\n  border-radius: 4px;\n}\n.cred-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(18rem, 1fr));\n  gap: 2.25rem 3rem;\n}\n.sub-title {\n  font-size: 1.05rem;\n  margin-bottom: 1rem;\n}\n.cred-list {\n  display: grid;\n  gap: 1rem;\n}\n.cred-list li {\n  display: grid;\n  gap: 0.1rem;\n}\n.cred-list li strong {\n  font-weight: 600;\n}\n.cred-list li span {\n  color: var(--muted);\n  font-size: 0.925rem;\n}\n\n/* Contact */\n.contact-grid {\n  display: grid;\n  grid-template-columns: minmax(0, 1.1fr) minmax(0, 1fr);\n  gap: 2rem 3rem;\n  align-items: start;\n}\n.contact-info {\n  margin: 0;\n  display: grid;\n  gap: 1.25rem;\n}\n.contact-info dt {\n  font-size: 0.875rem;\n  color: var(--muted);\n  margin-bottom: 0.3rem;\n}\n.contact-info dd {\n  margin: 0;\n  font-weight: 500;\n  overflow-wrap: anywhere;\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.5rem 0.75rem;\n}\n.form {\n  display: grid;\n  gap: 1.1rem;\n}\n.field {\n  display: grid;\n  gap: 0.35rem;\n}\n.field label {\n  font-weight: 500;\n  font-size: 0.925rem;\n}\n.field input,\n.field textarea {\n  font: inherit;\n  font-size: 0.975rem;\n  color: var(--ink);\n  background: var(--surface);\n  border: 1px solid var(--rule);\n  border-radius: 5px;\n  padding: 0.65rem 0.8rem;\n  width: 100%;\n  min-width: 0;\n}\n.field textarea {\n  min-height: 9rem;\n  resize: vertical;\n}\n.field input:hover,\n.field textarea:hover {\n  border-color: var(--muted);\n}\n.field input:focus-visible,\n.field textarea:focus-visible {\n  outline: 2px solid var(--focus);\n  outline-offset: 1px;\n  border-color: var(--focus);\n}\n.hp {\n  position: absolute;\n  left: -10000px;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n}\n.actions {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.75rem 1.25rem;\n}\n.status {\n  font-size: 0.925rem;\n  min-height: 1.4em;\n}\n.status.ok {\n  color: var(--ok);\n}\n.status.err {\n  color: var(--err);\n}\n.status.info {\n  color: var(--muted);\n}\n.foot-sep {\n  margin-inline: 0.3rem;\n}\n\n@media (max-width: 800px) {\n  .hero {\n    grid-template-columns: minmax(0, 1fr);\n  }\n  .facts {\n    border-left: 0;\n    border-top: 1px solid var(--rule);\n    padding-left: 0;\n    padding-top: 1.5rem;\n  }\n  .section {\n    grid-template-columns: minmax(0, 1fr);\n    gap: 1.25rem;\n    padding-block: 2.5rem;\n  }\n  .contact-grid,\n  .defs > div {\n    grid-template-columns: minmax(0, 1fr);\n  }\n}\n","css/projects.css":"/* Projects page: GitHub card, project list and the file tree. */\n.page-head {\n  padding-block: clamp(1.75rem, 4vw, 2.75rem) 1.25rem;\n}\n.page-head h1 {\n  font-size: clamp(2.6rem, 7vw, 4.2rem);\n  font-weight: 500;\n  letter-spacing: -0.03em;\n  line-height: 1;\n}\n.page-lede {\n  margin-top: 1rem;\n  max-width: 40rem;\n  color: var(--muted);\n  font-size: 1.1rem;\n}\n\n.github-card {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 1.25rem 2rem;\n  padding: 1.4rem 1.6rem;\n  background: var(--band);\n  color: var(--band-ink);\n  border-radius: 10px;\n}\n.github-card h2 {\n  font-size: 1.15rem;\n  font-weight: 500;\n  color: var(--band-muted);\n}\n.github-card > div {\n  display: grid;\n  gap: 0.2rem;\n  min-width: 0;\n}\n.gh-handle {\n  font-family: var(--serif);\n  font-size: 1.8rem;\n  font-weight: 500;\n  overflow-wrap: anywhere;\n}\n.gh-bio,\n.gh-stats,\n.gh-note {\n  color: var(--band-muted);\n  font-size: 0.95rem;\n}\n.github-card .btn-primary {\n  background: var(--band-ink);\n  border-color: var(--band-ink);\n  color: #11243d;\n}\n\n.projects {\n  padding-block: 1.5rem 0.5rem;\n}\n.list-title {\n  font-size: 1.4rem;\n  font-weight: 500;\n  margin-bottom: 0.5rem;\n}\n.project {\n  display: grid;\n  gap: 1rem;\n  padding-block: 1.6rem;\n  border-bottom: 1px solid var(--rule);\n}\n.project:first-child {\n  border-top: 1px solid var(--rule);\n}\n.project-main {\n  display: grid;\n  gap: 0.45rem;\n  min-width: 0;\n}\n.project h3 {\n  font-size: 1.3rem;\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  gap: 0.25rem 0.75rem;\n}\n.project .desc {\n  max-width: 42rem;\n}\n.project-tags {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.4rem;\n  margin-top: 0.15rem;\n}\n.project-tags li {\n  font: 500 0.78rem/1.5 var(--mono);\n  color: var(--muted);\n  border: 1px solid var(--rule);\n  border-radius: 4px;\n  padding: 0 0.45rem;\n}\n.project-actions {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.5rem;\n}\n.project-files {\n  display: grid;\n  gap: 0.6rem;\n  min-width: 0;\n}\n.files-status {\n  color: var(--muted);\n  font-size: 0.9rem;\n}\n\n/* The tree looks like the output of the `tree` command, with a guide line per level. */\n.tree-box {\n  max-height: 24rem;\n  overflow: auto;\n  background: var(--surface);\n  border: 1px solid var(--rule);\n  border-radius: 6px;\n  padding: 0.9rem 1rem;\n  font: 400 0.85rem/1.65 var(--mono);\n}\n.tree,\n.tree ul {\n  display: grid;\n  gap: 0;\n}\n.tree ul {\n  margin-left: 0.55rem;\n  padding-left: 1.1rem;\n  border-left: 1px solid var(--rule);\n}\n.tree a,\n.tree-file span,\n.tree-name {\n  display: inline-block;\n  padding-block: 0.05rem;\n  overflow-wrap: anywhere;\n}\n.tree a {\n  color: var(--ink);\n  text-decoration: none;\n}\n.tree a:hover {\n  color: var(--accent);\n  text-decoration: underline;\n}\n.tree-dir > details > summary {\n  display: flex;\n  align-items: baseline;\n  gap: 0.6rem;\n  cursor: pointer;\n  list-style: none;\n  font-weight: 500;\n  color: var(--tok-fn);\n}\n.tree-dir > details > summary::-webkit-details-marker {\n  display: none;\n}\n.tree-dir > details > summary::before {\n  content: \"\";\n  flex: none;\n  width: 0.4rem;\n  height: 0.4rem;\n  border-right: 2px solid currentColor;\n  border-bottom: 2px solid currentColor;\n  transform: rotate(-45deg) translateY(-0.1rem);\n  transition: transform 0.15s;\n}\n.tree-dir > details[open] > summary::before {\n  transform: rotate(45deg) translate(-0.1rem, -0.1rem);\n}\n.tree-count {\n  color: var(--muted);\n  font-size: 0.75rem;\n  font-weight: 400;\n}\n\n.guide {\n  margin-top: clamp(2rem, 5vw, 3rem);\n  padding-block: 1.75rem 0;\n}\n.guide h2 {\n  font-size: 1.4rem;\n  font-weight: 500;\n}\n.guide-list {\n  margin-top: 1rem;\n  display: grid;\n  gap: 0.7rem;\n  max-width: 44rem;\n  counter-reset: step;\n}\n.guide-list li {\n  position: relative;\n  padding-left: 2rem;\n  counter-increment: step;\n}\n.guide-list li::before {\n  content: counter(step);\n  position: absolute;\n  left: 0;\n  top: 0.15em;\n  display: grid;\n  place-items: center;\n  width: 1.4rem;\n  height: 1.4rem;\n  border: 1px solid var(--rule);\n  border-radius: 50%;\n  background: var(--surface);\n  font: 600 0.75rem/1 var(--sans);\n  color: var(--muted);\n}\n.guide code {\n  font: 500 0.88em var(--mono);\n  background: var(--surface);\n  border: 1px solid var(--rule);\n  border-radius: 3px;\n  padding: 0.05rem 0.3rem;\n}\n","css/ui.css":"/* UI skills page: the proof band, the live demo frame, and the source explorer. */\n\n/* Proof band: the one loud moment on this page. */\n.proof {\n  background: var(--band);\n  color: var(--band-ink);\n  padding-block: clamp(3rem, 7vw, 5rem);\n  margin-top: clamp(1.5rem, 4vw, 2.5rem);\n}\n.proof h1 {\n  font-size: clamp(2.4rem, 6vw, 4.2rem);\n  font-weight: 500;\n  line-height: 1.04;\n  letter-spacing: -0.03em;\n  max-width: 18ch;\n}\n.proof-lede {\n  margin-top: 1.4rem;\n  max-width: 41rem;\n  color: var(--band-muted);\n  font-size: 1.15rem;\n  line-height: 1.65;\n}\n.proof .cta {\n  margin-top: 2rem;\n}\n.concerns {\n  margin-top: clamp(2.5rem, 6vw, 4rem);\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(15.5rem, 1fr));\n  gap: 2.5rem 2.25rem;\n}\n.concern {\n  display: flex;\n  flex-direction: column;\n  gap: 0.65rem;\n  padding-top: 1.25rem;\n  border-top: 1px solid var(--band-line);\n}\n.concern h2 {\n  font-size: 1.3rem;\n  font-weight: 500;\n}\n.concern p {\n  color: var(--band-muted);\n  font-size: 0.975rem;\n  line-height: 1.6;\n}\n.concern .cta {\n  margin-top: auto;\n  padding-top: 0.5rem;\n  gap: 0.5rem;\n}\n.proof-note {\n  margin-top: 2.75rem;\n  max-width: 46rem;\n  color: var(--band-muted);\n  font-size: 0.9rem;\n}\n\n/* Live demo frame */\n.lab {\n  padding-block: clamp(2.5rem, 6vw, 4rem) 1rem;\n}\n.lab-intro {\n  max-width: 42rem;\n  margin-bottom: 1.5rem;\n}\n.lab-intro h2 {\n  font-size: 1.75rem;\n  font-weight: 500;\n}\n.lab-intro p {\n  margin-top: 0.5rem;\n  color: var(--muted);\n}\n\n/* Source explorer */\n.source {\n  background: var(--surface);\n  border-block: 1px solid var(--rule);\n  margin-top: clamp(2rem, 5vw, 3rem);\n}\n.source-inner {\n  display: grid;\n  gap: 1.1rem;\n  padding-block: 2.5rem 2.75rem;\n}\n.source h2 {\n  font-size: clamp(1.8rem, 4vw, 2.4rem);\n  font-weight: 500;\n  letter-spacing: -0.02em;\n}\n.source .intro {\n  margin-top: 0.6rem;\n  max-width: 46rem;\n  color: var(--muted);\n}\n.source-status {\n  display: inline-block;\n  margin-top: 0.5rem;\n  font: 500 0.8rem/1.5 var(--mono);\n  color: var(--muted);\n}\n.source-status::before {\n  content: \"\";\n  display: inline-block;\n  width: 0.5rem;\n  height: 0.5rem;\n  margin-right: 0.5rem;\n  border-radius: 50%;\n  background: var(--muted);\n}\n.source-status[data-state=\"live\"]::before {\n  background: var(--ok);\n}\n.tablist {\n  display: flex;\n  flex-wrap: wrap;\n  border-bottom: 1px solid var(--rule);\n}\n.tab {\n  font: inherit;\n  font-size: 0.975rem;\n  font-weight: 500;\n  color: var(--muted);\n  background: none;\n  border: 0;\n  border-bottom: 2px solid transparent;\n  margin-bottom: -1px;\n  padding: 0.6rem 0.95rem;\n  cursor: pointer;\n}\n.tab:hover {\n  color: var(--ink);\n}\n.tab[aria-selected=\"true\"] {\n  color: var(--ink);\n  border-bottom-color: var(--accent);\n}\n.tab small {\n  margin-left: 0.5rem;\n  font-weight: 400;\n  font-size: 0.8rem;\n  color: var(--muted);\n  font-variant-numeric: tabular-nums;\n}\n.tab-note {\n  color: var(--muted);\n  font-size: 0.925rem;\n  max-width: 52rem;\n}\n.skills {\n  display: grid;\n  gap: 0.9rem;\n}\n.skill-group {\n  display: grid;\n  grid-template-columns: 9.5rem minmax(0, 1fr);\n  gap: 0.4rem 1.25rem;\n  align-items: baseline;\n}\n.skill-group > p {\n  font-size: 0.85rem;\n  font-weight: 600;\n  color: var(--muted);\n}\n.skill-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.45rem;\n}\n.skill {\n  font: inherit;\n  font-size: 0.875rem;\n  color: var(--ink);\n  background: var(--bg);\n  border: 1px solid var(--rule);\n  border-radius: 5px;\n  padding: 0.3rem 0.7rem;\n  cursor: pointer;\n}\n.skill:hover {\n  border-color: var(--muted);\n}\n.skill small {\n  margin-left: 0.5rem;\n  color: var(--muted);\n  font-size: 0.78rem;\n  font-variant-numeric: tabular-nums;\n}\n.skill[aria-pressed=\"true\"] {\n  border-color: var(--accent);\n  color: var(--accent);\n  background: var(--surface);\n}\n.skill-note {\n  min-height: 3.4em;\n  max-width: 56rem;\n  font-size: 0.95rem;\n}\n.skill-note strong {\n  font-weight: 600;\n}\n\n.explorer {\n  display: grid;\n  grid-template-columns: 15.5rem minmax(0, 1fr);\n  grid-template-rows: min(75vh, 39rem);\n  border: 1px solid var(--rule);\n  border-radius: 8px;\n  overflow: clip;\n  background: var(--bg);\n}\n.files {\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n  overflow: auto;\n  padding: 0.5rem;\n  border-right: 1px solid var(--rule);\n  background: var(--surface);\n}\n.file {\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) auto;\n  gap: 0.1rem 0.5rem;\n  align-items: baseline;\n  width: 100%;\n  text-align: left;\n  font: 500 0.8125rem/1.45 var(--mono);\n  color: var(--ink);\n  background: none;\n  border: 0;\n  border-radius: 4px;\n  padding: 0.35rem 0.55rem;\n  cursor: pointer;\n}\n.file:hover {\n  background: var(--bg);\n}\n.file[aria-current=\"true\"] {\n  background: var(--hit);\n  color: var(--accent);\n}\n.file-dir {\n  grid-column: 1 / -1;\n  color: var(--muted);\n  font-size: 0.72rem;\n  font-weight: 400;\n}\n.file-name {\n  overflow-wrap: anywhere;\n}\n.file small {\n  color: var(--muted);\n  font-size: 0.72rem;\n  font-weight: 400;\n  font-variant-numeric: tabular-nums;\n}\n.pane {\n  display: grid;\n  grid-template-rows: auto minmax(0, 1fr);\n  min-width: 0;\n  min-height: 0;\n}\n.pane-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 0.25rem 1rem;\n  padding: 0.55rem 1rem;\n  border-bottom: 1px solid var(--rule);\n  background: var(--surface);\n}\n.pane-path {\n  font: 500 0.82rem/1.5 var(--mono);\n  overflow-wrap: anywhere;\n}\n.pane-meta {\n  color: var(--muted);\n  font-size: 0.8rem;\n  margin-left: 0.75rem;\n}\n.copy {\n  font: inherit;\n  font-size: 0.85rem;\n  font-weight: 500;\n  color: var(--accent);\n  background: none;\n  border: 0;\n  padding: 0;\n  cursor: pointer;\n  text-decoration: underline;\n  text-underline-offset: 3px;\n}\n.codebox {\n  position: relative;\n  min-height: 0;\n  overflow: auto;\n}\n.codebox pre {\n  margin: 0;\n  padding: 0.9rem 0;\n  font: 400 0.8125rem/1.6 var(--mono);\n  color: var(--ink);\n}\n.codebox code {\n  display: block;\n  min-width: max-content;\n  font: inherit;\n}\n.line {\n  display: block;\n  padding-right: 1rem;\n  white-space: pre;\n  tab-size: 2;\n}\n.line::before {\n  content: attr(data-n);\n  display: inline-block;\n  width: 3.5rem;\n  padding-right: 1rem;\n  text-align: right;\n  color: var(--muted);\n  user-select: none;\n}\n.line.hit {\n  background: var(--hit);\n}\n.codebox .hljs-comment {\n  color: var(--tok-com);\n  font-style: italic;\n}\n.codebox .hljs-keyword,\n.codebox .hljs-literal,\n.codebox .hljs-meta {\n  color: var(--tok-kw);\n}\n.codebox .hljs-string,\n.codebox .hljs-regexp {\n  color: var(--tok-str);\n}\n.codebox .hljs-number {\n  color: var(--tok-num);\n}\n.codebox .hljs-title,\n.codebox .hljs-built_in,\n.codebox .hljs-name,\n.codebox .hljs-tag,\n.codebox .hljs-selector-tag,\n.codebox .hljs-selector-class,\n.codebox .hljs-selector-id {\n  color: var(--tok-fn);\n}\n.codebox .hljs-attr,\n.codebox .hljs-attribute,\n.codebox .hljs-property,\n.codebox .hljs-variable,\n.codebox .hljs-selector-pseudo {\n  color: var(--tok-attr);\n}\n\n@media (max-width: 800px) {\n  .skill-group {\n    grid-template-columns: minmax(0, 1fr);\n  }\n  .explorer {\n    grid-template-columns: minmax(0, 1fr);\n    grid-template-rows: auto min(65vh, 34rem);\n  }\n  .files {\n    flex-direction: row;\n    border-right: 0;\n    border-bottom: 1px solid var(--rule);\n    padding: 0.4rem;\n    gap: 0.25rem;\n  }\n  .file {\n    width: auto;\n    flex: none;\n    grid-template-columns: auto auto;\n  }\n  .file-dir {\n    display: none;\n  }\n}\n","css/lab.css":"/* The live demo: window, tabs, forms, risk table, toasts. The table is a size container, so it becomes\n   cards when its own width is small, whatever the screen size. */\n/* Lab: inputs */\n.lab-field input,\n.lab-field select,\n.lab-field textarea,\n.lab-toolbar input,\n.lab-toolbar select {\n  font: inherit;\n  font-size: 0.975rem;\n  color: var(--ink);\n  background: var(--surface);\n  border: 1px solid var(--rule);\n  border-radius: 5px;\n  padding: 0.65rem 0.8rem;\n  width: 100%;\n  min-width: 0;\n}\n.lab-field label {\n  font-weight: 500;\n  font-size: 0.925rem;\n}\n.lab-field input:hover,\n.lab-field select:hover,\n.lab-field textarea:hover {\n  border-color: var(--muted);\n}\n.lab-field input:focus-visible,\n.lab-field select:focus-visible,\n.lab-field textarea:focus-visible,\n.lab-toolbar input:focus-visible,\n.lab-toolbar select:focus-visible {\n  outline: 2px solid var(--focus);\n  outline-offset: 1px;\n  border-color: var(--focus);\n}\n.lab-field [aria-invalid=\"true\"] {\n  border-color: var(--err);\n}\n.lab-loading {\n  padding: 2rem;\n  color: var(--muted);\n  border: 1px dashed var(--rule);\n  border-radius: 8px;\n}\n\n/* Lab: window, tabs, forms */\n.lab-window {\n  position: relative;\n  background: var(--surface);\n  border: 1px solid var(--rule);\n  border-radius: 8px;\n  overflow: clip;\n}\n.lab-bar-top {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 0.4rem 1rem;\n  padding: 0.7rem 1rem;\n  border-bottom: 1px solid var(--rule);\n  background: var(--bg);\n}\n.lab-bar-top p {\n  margin: 0;\n}\n.lab-pill {\n  font-size: 0.875rem;\n  color: var(--muted);\n}\n.lab-pill.is-on {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.25rem 0.9rem;\n  color: var(--ink);\n  font-weight: 500;\n}\n.lab-link {\n  font: inherit;\n  color: var(--accent);\n  background: none;\n  border: 0;\n  padding: 0;\n  cursor: pointer;\n  text-decoration: underline;\n  text-underline-offset: 3px;\n}\n.lab-warn {\n  margin: 0;\n  padding: 0.65rem 1rem;\n  background: var(--warn-bg);\n  color: var(--warn-ink);\n  border-bottom: 1px solid var(--rule);\n  font-size: 0.925rem;\n}\n.lab-tabs {\n  display: flex;\n  flex-wrap: wrap;\n  padding: 0 0.5rem;\n  border-bottom: 1px solid var(--rule);\n}\n.lab-tabs button {\n  font: inherit;\n  font-size: 0.975rem;\n  font-weight: 500;\n  color: var(--muted);\n  background: none;\n  border: 0;\n  border-bottom: 2px solid transparent;\n  margin-bottom: -1px;\n  padding: 0.7rem 1rem;\n  cursor: pointer;\n}\n.lab-tabs button:hover {\n  color: var(--ink);\n}\n.lab-tabs button[aria-selected=\"true\"] {\n  color: var(--ink);\n  border-bottom-color: var(--accent);\n}\n.lab-panel {\n  padding: 1.5rem 1.25rem 1.75rem;\n}\n.lab-form {\n  display: grid;\n  gap: 1rem;\n  max-width: 30rem;\n}\n.lab-field {\n  display: grid;\n  gap: 0.35rem;\n}\n.lab-hint {\n  color: var(--muted);\n  font-size: 0.875rem;\n  line-height: 1.5;\n}\n.lab-error {\n  color: var(--err);\n  font-size: 0.9rem;\n  min-height: 1.2em;\n}\n.lab-ok {\n  color: var(--ok);\n  font-size: 0.9rem;\n  min-height: 1.2em;\n}\n.lab-note {\n  background: var(--bg);\n  border: 1px solid var(--rule);\n  border-radius: 5px;\n  padding: 0.6rem 0.8rem;\n  font-size: 0.9rem;\n}\n/* Status regions stay in the page so screen readers hear changes. While one is empty it is taken\n   out of the layout the same way .sr-only does it, not with display: none, which would drop it\n   from the accessibility tree. */\n.lab-note:empty,\n.lab-hint:empty,\n.lab-risks > .lab-error:empty,\n.lab-session > .lab-error:empty {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  margin: -1px;\n  padding: 0;\n  border: 0;\n  overflow: hidden;\n  clip-path: inset(50%);\n}\n.lab-desc {\n  display: block;\n  margin-top: 0.15rem;\n  color: var(--muted);\n  font-size: 0.85rem;\n  font-weight: 400;\n  overflow-wrap: anywhere;\n}\n.lab-session:focus {\n  outline: none;\n}\n.lab-actions {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.6rem 0.75rem;\n}\n.lab-btn {\n  font: 600 0.9rem/1.1 var(--sans);\n  color: var(--ink);\n  background: var(--surface);\n  border: 1px solid var(--rule);\n  border-radius: 6px;\n  padding: 0.65rem 1.1rem;\n  cursor: pointer;\n}\n.lab-btn:hover {\n  border-color: var(--ink);\n}\n.lab-btn-primary {\n  background: var(--accent);\n  border-color: var(--accent);\n  color: var(--accent-ink);\n}\n.lab-btn-primary:hover {\n  border-color: var(--accent);\n  filter: brightness(1.12);\n}\n.lab-btn-small {\n  font-size: 0.82rem;\n  padding: 0.4rem 0.75rem;\n}\n.lab-btn[disabled] {\n  opacity: 0.5;\n  cursor: not-allowed;\n}\n.lab-btn[disabled]:hover {\n  border-color: var(--rule);\n}\n/* aria-disabled keeps keyboard focus on the button while a request runs. */\n.lab-btn[aria-disabled=\"true\"] {\n  opacity: 0.5;\n  cursor: progress;\n}\n.lab-empty {\n  display: grid;\n  gap: 1rem;\n  justify-items: start;\n  padding-block: 1rem;\n}\n.lab-dl {\n  margin: 0;\n  display: grid;\n  gap: 0.7rem;\n}\n.lab-dl > div {\n  display: grid;\n  grid-template-columns: 9rem minmax(0, 1fr);\n  gap: 0.2rem 1rem;\n}\n.lab-dl dt {\n  color: var(--muted);\n  font-size: 0.9rem;\n}\n.lab-dl dd {\n  margin: 0;\n  font-weight: 500;\n  overflow-wrap: anywhere;\n}\n.lab-dl code,\n.lab-pre,\n.lab-state pre {\n  font-family: var(--mono);\n  font-size: 0.82rem;\n}\n.lab-session {\n  display: grid;\n  gap: 1.1rem;\n  max-width: 38rem;\n}\n.lab-bar {\n  height: 6px;\n  border-radius: 3px;\n  background: var(--rule);\n  overflow: hidden;\n}\n.lab-bar span {\n  display: block;\n  height: 100%;\n  background: var(--accent);\n  transition: width 0.5s linear;\n}\n.lab-card {\n  border: 1px solid var(--rule);\n  border-radius: 8px;\n  padding: 1.25rem;\n  display: grid;\n  gap: 0.9rem;\n  align-content: start;\n  min-width: 0;\n}\n.lab-card h3 {\n  font-size: 1.1rem;\n}\n.lab-card h4 {\n  font-size: 0.95rem;\n}\n.lab-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(19rem, 1fr));\n  gap: 1.25rem;\n}\n.lab-wide {\n  grid-column: 1 / -1;\n}\n.lab-inline {\n  display: flex;\n  gap: 0.5rem;\n}\n.lab-inline input {\n  flex: 1;\n}\n.lab-forge {\n  display: grid;\n  gap: 0.6rem;\n  justify-items: start;\n  border-top: 1px solid var(--rule);\n  padding-top: 0.9rem;\n}\n.lab-pre {\n  margin: 0;\n  background: var(--bg);\n  border: 1px solid var(--rule);\n  border-radius: 5px;\n  padding: 0.6rem 0.8rem;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n  max-width: 100%;\n}\n.lab-meter {\n  height: 8px;\n  border-radius: 4px;\n  background: var(--rule);\n  overflow: hidden;\n}\n.lab-meter span {\n  display: block;\n  height: 100%;\n  background: var(--err);\n  transition: width 0.2s;\n}\n.lab-meter[data-level=\"fair\"] span {\n  background: #c98a00;\n}\n.lab-meter[data-level=\"strong\"] span {\n  background: var(--ok);\n}\n.lab-rules {\n  display: grid;\n  gap: 0.3rem;\n  font-size: 0.9rem;\n}\n.lab-rules li {\n  position: relative;\n  padding-left: 1.4rem;\n  color: var(--muted);\n}\n.lab-rules li::before {\n  content: \"\";\n  position: absolute;\n  left: 0;\n  top: 0.45em;\n  width: 0.75rem;\n  height: 0.75rem;\n  border-radius: 50%;\n  border: 1.5px solid var(--muted);\n}\n.lab-rules li[data-ok=\"true\"] {\n  color: var(--ink);\n}\n.lab-rules li[data-ok=\"true\"]::before {\n  background: var(--ok);\n  border-color: var(--ok);\n}\n.lab-outputs {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));\n  gap: 1rem;\n}\n.lab-outputs > div {\n  display: grid;\n  gap: 0.4rem;\n  align-content: start;\n  min-width: 0;\n}\n.lab-out {\n  background: var(--bg);\n  border: 1px solid var(--rule);\n  border-radius: 5px;\n  padding: 0.6rem 0.8rem;\n  min-height: 4rem;\n  overflow-wrap: anywhere;\n  font-size: 0.925rem;\n}\n.lab-scenarios {\n  display: grid;\n  gap: 0.75rem;\n}\n.lab-scenarios li {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 0.5rem 1rem;\n  padding-bottom: 0.75rem;\n  border-bottom: 1px solid var(--rule);\n}\n.lab-scenarios li > div {\n  flex: 1 1 18rem;\n  min-width: 0;\n}\n.lab-log {\n  display: grid;\n  gap: 0.3rem;\n  font-family: var(--mono);\n  font-size: 0.82rem;\n  min-height: 1.2em;\n}\n.lab-log li {\n  padding-left: 1rem;\n  position: relative;\n}\n.lab-log li::before {\n  content: \"\";\n  position: absolute;\n  left: 0;\n  top: 0.5em;\n  width: 0.45rem;\n  height: 0.45rem;\n  border-radius: 50%;\n  background: var(--muted);\n}\n.lab-log li[data-outcome=\"ok\"]::before {\n  background: var(--ok);\n}\n.lab-log li[data-outcome=\"failed\"]::before {\n  background: var(--err);\n}\n.lab-crash {\n  background: var(--bad-bg);\n  border: 1px solid var(--err);\n  border-radius: 6px;\n  padding: 0.9rem 1rem;\n  display: grid;\n  gap: 0.5rem;\n  justify-items: start;\n}\n\n/* Lab: risk log */\n.lab-toolbar {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.6rem;\n  margin-bottom: 0.75rem;\n}\n.lab-toolbar input[type=\"search\"] {\n  flex: 1 1 12rem;\n  width: auto;\n}\n.lab-toolbar select {\n  width: auto;\n}\n.lab-check {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.4rem;\n  font-size: 0.9rem;\n  white-space: nowrap;\n}\n.lab-toolbar input[type=\"checkbox\"] {\n  width: auto;\n  min-height: 0;\n  padding: 0;\n  margin: 0;\n}\n.lab-risks > * + * {\n  margin-top: 0.75rem;\n}\n.lab-resize {\n  container-type: inline-size;\n  resize: horizontal;\n  overflow: auto;\n  min-width: 18rem;\n  max-width: 100%;\n  border: 1px solid var(--rule);\n  border-radius: 6px;\n  background: var(--surface);\n}\n.lab-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 0.9rem;\n  font-variant-numeric: tabular-nums;\n}\n.lab-table th,\n.lab-table td {\n  text-align: left;\n  padding: 0.65rem 0.8rem;\n  border-bottom: 1px solid var(--rule);\n  vertical-align: top;\n}\n.lab-table tbody tr:last-child td {\n  border-bottom: 0;\n}\n.lab-table th {\n  background: var(--bg);\n}\n.lab-table th button {\n  font: inherit;\n  font-weight: 600;\n  color: inherit;\n  background: none;\n  border: 0;\n  padding: 0;\n  cursor: pointer;\n}\n.lab-table th[aria-sort=\"ascending\"] button::after {\n  content: \" \\2191\";\n}\n.lab-table th[aria-sort=\"descending\"] button::after {\n  content: \" \\2193\";\n}\n.lab-table tr.is-pending {\n  opacity: 0.6;\n}\n.lab-none {\n  color: var(--muted);\n}\n.lab-badge {\n  display: inline-block;\n  font-size: 0.78rem;\n  font-weight: 600;\n  padding: 0.1rem 0.5rem;\n  border-radius: 4px;\n  background: var(--bg);\n  border: 1px solid var(--rule);\n}\n.lab-badge.sev-high {\n  background: var(--bad-bg);\n  color: var(--err);\n  border-color: transparent;\n}\n.lab-badge.sev-medium {\n  background: var(--warn-bg);\n  color: var(--warn-ink);\n  border-color: transparent;\n}\n.lab-badge.sev-low,\n.lab-badge.st-resolved {\n  background: var(--ok-bg);\n  color: var(--ok);\n  border-color: transparent;\n}\n.lab-state {\n  font-size: 0.9rem;\n}\n.lab-state summary {\n  cursor: pointer;\n  color: var(--accent);\n  font-weight: 500;\n}\n.lab-state pre {\n  margin: 0.6rem 0 0;\n  background: var(--bg);\n  border: 1px solid var(--rule);\n  border-radius: 5px;\n  padding: 0.7rem 0.9rem;\n  overflow: auto;\n}\n@container (max-width: 40rem) {\n  .lab-table thead {\n    position: absolute;\n    width: 1px;\n    height: 1px;\n    overflow: hidden;\n    clip-path: inset(50%);\n  }\n  .lab-table,\n  .lab-table tbody,\n  .lab-table tr,\n  .lab-table td {\n    display: block;\n    width: 100%;\n  }\n  .lab-table tr {\n    padding: 0.8rem;\n    border-bottom: 1px solid var(--rule);\n  }\n  .lab-table td {\n    display: grid;\n    grid-template-columns: 6rem minmax(0, 1fr);\n    gap: 0.5rem;\n    padding: 0.25rem 0;\n    border: 0;\n  }\n  .lab-table td::before {\n    content: attr(data-label);\n    color: var(--muted);\n    font-weight: 500;\n  }\n}\n\n/* Lab: toasts */\n.lab-toasts {\n  position: sticky;\n  bottom: 0.75rem;\n  display: grid;\n  gap: 0.5rem;\n  padding: 0 1rem 1rem;\n  pointer-events: none;\n}\n.lab-toasts:empty {\n  display: none;\n}\n.lab-toast {\n  pointer-events: auto;\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 0.5rem 0.75rem;\n  padding: 0.65rem 0.9rem;\n  border-radius: 6px;\n  border: 1px solid var(--rule);\n  background: var(--surface);\n  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.14);\n  font-size: 0.9rem;\n}\n.lab-toast span {\n  flex: 1 1 14rem;\n}\n.lab-toast.is-success {\n  border-color: var(--ok);\n}\n.lab-toast.is-error {\n  border-color: var(--err);\n}\n\n@media (max-width: 800px) {\n  .lab-dl > div {\n    grid-template-columns: minmax(0, 1fr);\n  }\n  .lab-panel {\n    padding-inline: 1rem;\n  }\n}\n","js/common.js":"/* Shared helpers for every page. Plain JavaScript, no build step. */\n(function () {\n  \"use strict\";\n  var S = window.SITE || {};\n\n  /* Build DOM nodes without innerHTML, so text from the data files can never become markup. */\n  function h(tag, props, children) {\n    var node = document.createElement(tag);\n    Object.keys(props || {}).forEach(function (key) {\n      var value = props[key];\n      if (value === undefined || value === null || value === false) return;\n      if (key === \"class\") node.className = value;\n      else if (key === \"text\") node.textContent = value;\n      else if (key.slice(0, 2) === \"on\") node.addEventListener(key.slice(2), value);\n      else node.setAttribute(key, value === true ? \"\" : String(value));\n    });\n    [].concat(children || []).forEach(function (child) {\n      if (child === undefined || child === null || child === false) return;\n      node.appendChild(typeof child === \"string\" ? document.createTextNode(child) : child);\n    });\n    return node;\n  }\n\n  /* An external link that cannot reach back into this page. */\n  function external(text, href, cls) {\n    return h(\"a\", {\n      href: href,\n      class: cls || \"\",\n      target: \"_blank\",\n      rel: \"noopener noreferrer\",\n      text: text,\n    });\n  }\n\n  /* Copy text. Clipboard access can be refused, so fall back to selecting it. */\n  function copyText(button, text, node, idle) {\n    function done(message) {\n      button.textContent = message;\n      window.setTimeout(function () {\n        button.textContent = idle;\n      }, 1800);\n    }\n    function fallback() {\n      if (!node) return done(\"Press Ctrl+C\");\n      var range = document.createRange();\n      range.selectNodeContents(node);\n      var selection = window.getSelection();\n      selection.removeAllRanges();\n      selection.addRange(range);\n      done(\"Selected\");\n    }\n    if (navigator.clipboard && navigator.clipboard.writeText) {\n      navigator.clipboard.writeText(text).then(function () {\n        done(\"Copied\");\n      }, fallback);\n    } else {\n      fallback();\n    }\n  }\n\n  /* Fill the places marked in the HTML from data/settings.js, and hide links that have no value yet. */\n  var LINKS = {\n    email: function (v) {\n      return \"mailto:\" + v;\n    },\n    linkedin: function (v) {\n      return v;\n    },\n    github: function (v) {\n      return \"https://github.com/\" + v;\n    },\n    siteRepo: function (v) {\n      return \"https://github.com/\" + v;\n    },\n    resumeUrl: function (v) {\n      return v;\n    },\n  };\n  document.querySelectorAll(\"[data-site]\").forEach(function (node) {\n    node.textContent = S[node.getAttribute(\"data-site\")] || \"\";\n  });\n  document.querySelectorAll(\"[data-site-link]\").forEach(function (node) {\n    var key = node.getAttribute(\"data-site-link\");\n    var value = S[key];\n    if (!value) {\n      node.hidden = true;\n      return;\n    }\n    node.href = LINKS[key](value);\n    if (key !== \"email\") {\n      node.target = \"_blank\";\n      node.rel = \"noopener noreferrer\";\n    }\n  });\n  document.querySelectorAll(\"[data-site-show]\").forEach(function (node) {\n    node.hidden = !S[node.getAttribute(\"data-site-show\")];\n  });\n  document.querySelectorAll(\"[data-year]\").forEach(function (node) {\n    node.textContent = String(new Date().getFullYear());\n  });\n\n  window.SiteUtil = { h: h, external: external, copyText: copyText };\n})();\n","js/entrance.js":"/* Entrance page: typed greeting, endless code drift, and the hand-off to the chosen page. */\n(function () {\n  \"use strict\";\n  var reduce = window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\n  var stage = document.getElementById(\"stage\");\n\n  /* Each code column holds one copy of its text. Doubling it lets the drift loop without a visible jump. */\n  document.querySelectorAll(\".codefall pre\").forEach(function (pre) {\n    pre.textContent = pre.textContent + \"\\n\\n\" + pre.textContent;\n  });\n\n  /* Typed greeting. The full sentence stays available to screen readers through aria-label. */\n  var greet = document.getElementById(\"greet\");\n  var full = greet.textContent.trim();\n  if (!reduce) {\n    var typed = document.createElement(\"span\");\n    var caret = document.createElement(\"span\");\n    caret.className = \"caret\";\n    typed.setAttribute(\"aria-hidden\", \"true\");\n    caret.setAttribute(\"aria-hidden\", \"true\");\n    greet.setAttribute(\"aria-label\", full);\n    greet.textContent = \"\";\n    greet.appendChild(typed);\n    greet.appendChild(caret);\n    var count = 0;\n    var tick = function () {\n      count += 1;\n      typed.textContent = full.slice(0, count);\n      if (count \u003c full.length) {\n        window.setTimeout(tick, 34 + Math.random() * 36);\n      } else {\n        window.setTimeout(function () {\n          caret.className = \"caret is-done\";\n        }, 700);\n      }\n    };\n    window.setTimeout(tick, 450);\n  }\n\n  /* Choosing a card plays a short exit, then opens the page. Modified clicks (new tab) are left alone. */\n  document.querySelectorAll(\".choice\").forEach(function (card) {\n    card.addEventListener(\"click\", function (event) {\n      if (\n        event.defaultPrevented ||\n        event.button !== 0 ||\n        event.metaKey ||\n        event.ctrlKey ||\n        event.shiftKey ||\n        event.altKey\n      )\n        return;\n      event.preventDefault();\n      card.classList.add(\"is-chosen\");\n      stage.classList.add(\"is-leaving\");\n      window.setTimeout(\n        function () {\n          window.location.href = card.href;\n        },\n        reduce ? 0 : 520,\n      );\n    });\n  });\n\n  /* Coming back with the Back button restores the page from memory, so undo the exit. */\n  window.addEventListener(\"pageshow\", function (event) {\n    if (!event.persisted) return;\n    stage.classList.remove(\"is-leaving\");\n    document.querySelectorAll(\".choice\").forEach(function (card) {\n      card.classList.remove(\"is-chosen\");\n    });\n  });\n})();\n","js/profile.js":"/* Profile page: renders everything from data/profile.js and runs the contact form. */\n(function () {\n  \"use strict\";\n  var h = window.SiteUtil.h;\n  var P = window.PROFILE;\n  var S = window.SITE;\n  var $ = function (id) {\n    return document.getElementById(id);\n  };\n\n  /* ---------- Content from data/profile.js ---------- */\n\n  $(\"lead\").textContent = P.lead;\n  $(\"summary-text\").textContent = P.summary;\n\n  P.facts.forEach(function (fact) {\n    $(\"facts\").appendChild(\n      h(\"div\", {}, [\n        h(\"dt\", { text: fact.label }),\n        h(\"dd\", {}, [fact.value, fact.note ? h(\"small\", { text: fact.note }) : null]),\n      ]),\n    );\n  });\n\n  P.results.forEach(function (item) {\n    $(\"results\").appendChild(\n      h(\"li\", { class: \"result\" }, [\n        h(\"strong\", { class: \"num\", text: item.value }),\n        h(\"span\", { text: item.label }),\n      ]),\n    );\n  });\n\n  P.experience.forEach(function (job) {\n    var visible = job.bullets.slice(0, job.visible);\n    var rest = job.bullets.slice(job.visible);\n    var article = h(\"article\", { class: \"role\" }, [\n      h(\"div\", { class: \"role-head\" }, [\n        h(\"h3\", { text: job.company }),\n        h(\"p\", { class: \"when\", text: job.start + \" to \" + job.end }),\n      ]),\n      h(\"p\", { class: \"where\", text: job.role + \", \" + job.location }),\n      h(\n        \"ul\",\n        { class: \"bullets\" },\n        visible.map(function (text) {\n          return h(\"li\", { text: text });\n        }),\n      ),\n    ]);\n    if (rest.length) {\n      article.appendChild(\n        h(\"details\", { class: \"more\" }, [\n          h(\"summary\", {}, [\n            h(\"span\", {\n              class: \"when-closed\",\n              text: \"Show \" + rest.length + \" more responsibilities\",\n            }),\n            h(\"span\", { class: \"when-open\", text: \"Show fewer\" }),\n          ]),\n          h(\n            \"ul\",\n            { class: \"bullets\" },\n            rest.map(function (text) {\n              return h(\"li\", { text: text });\n            }),\n          ),\n        ]),\n      );\n    }\n    article.appendChild(\n      h(\"p\", { class: \"stack\" }, [h(\"strong\", { text: \"Environment: \" }), job.environment]),\n    );\n    $(\"experience-list\").appendChild(article);\n  });\n\n  P.skills.forEach(function (group) {\n    $(\"skills-list\").appendChild(\n      h(\"div\", {}, [\n        h(\"dt\", { text: group.group }),\n        h(\"dd\", {}, [\n          h(\n            \"ul\",\n            { class: \"chips\" },\n            group.items.map(function (item) {\n              return h(\"li\", { text: item });\n            }),\n          ),\n        ]),\n      ]),\n    );\n  });\n\n  P.certifications.forEach(function (cert) {\n    $(\"cert-list\").appendChild(\n      h(\"li\", {}, [h(\"strong\", { text: cert.name }), h(\"span\", { text: cert.issuer })]),\n    );\n  });\n  P.education.forEach(function (edu) {\n    $(\"edu-list\").appendChild(\n      h(\"li\", {}, [\n        h(\"strong\", { text: edu.school }),\n        h(\"span\", { text: edu.degree + \" | \" + edu.detail }),\n        h(\"span\", { text: edu.date + \", \" + edu.location }),\n      ]),\n    );\n  });\n\n  /* ---------- Contact details ---------- */\n\n  var emailLink = $(\"c-email\");\n  emailLink.textContent = S.email;\n  emailLink.href = \"mailto:\" + S.email;\n  var copyButton = $(\"copy-email\");\n  copyButton.addEventListener(\"click\", function () {\n    window.SiteUtil.copyText(copyButton, S.email, emailLink, \"Copy\");\n  });\n\n  /* ---------- Contact form ---------- */\n\n  var form = $(\"contact-form\");\n  var status = $(\"f-status\");\n  var send = $(\"f-send\");\n  var EMAIL = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;\n\n  function say(message, kind) {\n    status.textContent = message;\n    status.className = \"status \" + (kind || \"\");\n  }\n\n  form.addEventListener(\"submit\", function (event) {\n    event.preventDefault();\n    var name = $(\"f-name\").value.trim();\n    var email = $(\"f-email\").value.trim();\n    var message = $(\"f-message\").value.trim();\n\n    if (!name || !email || !message) {\n      say(\"Fill in your name, email and a message.\", \"err\");\n      (!name ? $(\"f-name\") : !email ? $(\"f-email\") : $(\"f-message\")).focus();\n      return;\n    }\n    if (!EMAIL.test(email)) {\n      say(\"Enter a valid email address so I can reply.\", \"err\");\n      $(\"f-email\").focus();\n      return;\n    }\n    if ($(\"f-botcheck\").value) {\n      // A person never sees this field. Pretend it worked and send nothing.\n      say(\"Message sent.\", \"ok\");\n      form.reset();\n      return;\n    }\n\n    if (S.web3formsKey) {\n      send.disabled = true;\n      say(\"Sending...\", \"info\");\n      var controller = new AbortController();\n      var timer = window.setTimeout(function () {\n        controller.abort();\n      }, 15000);\n      fetch(\"https://api.web3forms.com/submit\", {\n        method: \"POST\",\n        signal: controller.signal,\n        headers: { \"Content-Type\": \"application/json\", Accept: \"application/json\" },\n        body: JSON.stringify({\n          access_key: S.web3formsKey,\n          subject: \"Website message from \" + name,\n          from_name: name,\n          name: name,\n          email: email,\n          message: message,\n          botcheck: \"\",\n        }),\n      })\n        .then(function (response) {\n          return response\n            .json()\n            .catch(function () {\n              return {};\n            })\n            .then(function (json) {\n              return { ok: response.ok && json.success !== false, json: json };\n            });\n        })\n        .then(function (result) {\n          if (!result.ok) throw new Error((result.json && result.json.message) || \"Request failed\");\n          say(\"Message sent. I will reply to \" + email + \".\", \"ok\");\n          form.reset();\n        })\n        .catch(function () {\n          say(\"The message did not send. Email \" + S.email + \" directly.\", \"err\");\n        })\n        .then(function () {\n          window.clearTimeout(timer);\n          send.disabled = false;\n        });\n    } else {\n      var subject = \"Website message from \" + name;\n      var body = message + \"\\n\\n\" + name + \"\\n\" + email;\n      say(\"Opening your email app. If nothing opens, write to \" + S.email + \".\", \"info\");\n      window.location.href =\n        \"mailto:\" +\n        S.email +\n        \"?subject=\" +\n        encodeURIComponent(subject) +\n        \"&body=\" +\n        encodeURIComponent(body);\n    }\n  });\n})();\n","js/github.js":"/* A small GitHub client for public data. It needs no key. Visitors share GitHub's anonymous rate limit,\n   so every answer is kept for ten minutes in sessionStorage. Names are validated before they go into a URL. */\n(function () {\n  \"use strict\";\n  var API = \"https://api.github.com\";\n  var TTL_MS = 10 * 60 * 1000;\n  var USER = /^[A-Za-z0-9](?:[A-Za-z0-9-]{0,38})$/;\n  // \".\" and \"..\" are not valid repository names, and they would change the request path.\n  var REPO = /^[A-Za-z0-9](?:[A-Za-z0-9-]{0,38})\\/(?!\\.{1,2}$)[A-Za-z0-9._-]{1,100}$/;\n\n  function remembered(key) {\n    try {\n      var raw = window.sessionStorage.getItem(key);\n      var entry = raw ? JSON.parse(raw) : null;\n      return entry && Date.now() - entry.at \u003c TTL_MS ? entry.data : null;\n    } catch {\n      return null;\n    }\n  }\n  function remember(key, data) {\n    try {\n      window.sessionStorage.setItem(key, JSON.stringify({ at: Date.now(), data: data }));\n    } catch {\n      /* Storage can be blocked or full. The page works without it. */\n    }\n  }\n\n  function request(path) {\n    var key = \"gh:\" + path;\n    var hit = remembered(key);\n    if (hit) return Promise.resolve(hit);\n    var controller = new AbortController();\n    var timer = window.setTimeout(function () {\n      controller.abort();\n    }, 8000);\n    return fetch(API + path, {\n      headers: { Accept: \"application/vnd.github+json\" },\n      signal: controller.signal,\n    })\n      .then(function (response) {\n        if (!response.ok) {\n          var error = new Error(\"GitHub answered \" + response.status);\n          error.status = response.status;\n          throw error;\n        }\n        return response.json();\n      })\n      .then(function (data) {\n        remember(key, data);\n        return data;\n      })\n      .finally(function () {\n        window.clearTimeout(timer);\n      });\n  }\n\n  /* A rejected name is a mistake in the data files, so the message points the owner there. */\n  function invalid(message) {\n    var error = new Error(message);\n    error.invalid = true;\n    return Promise.reject(error);\n  }\n\n  /* A short sentence a visitor can act on. */\n  function explain(error) {\n    if (error && error.invalid)\n      return \"The GitHub name in the site's data files looks wrong. Check it for typos.\";\n    if (error && error.status === 409) return \"That repository is empty.\";\n    if (error && (error.status === 403 || error.status === 429))\n      return \"GitHub's limit for anonymous visitors was reached. Try again in a few minutes.\";\n    if (error && error.status === 404) return \"GitHub could not find that repository.\";\n    if (error && error.name === \"AbortError\") return \"GitHub took too long to answer.\";\n    return \"GitHub could not be reached from this page.\";\n  }\n\n  function enc(path) {\n    return path.split(\"/\").map(encodeURIComponent).join(\"/\");\n  }\n\n  function profile(user) {\n    if (!USER.test(user)) return invalid(\"Invalid GitHub username\");\n    return request(\"/users/\" + encodeURIComponent(user));\n  }\n\n  function repos(user) {\n    if (!USER.test(user)) return invalid(\"Invalid GitHub username\");\n    return request(\n      \"/users/\" + encodeURIComponent(user) + \"/repos?sort=pushed&per_page=30&type=owner\",\n    ).then(function (list) {\n      return list\n        .filter(function (r) {\n          return !r.fork && !r.archived;\n        })\n        .slice(0, 6);\n    });\n  }\n\n  /* The files of a repository: look up the default branch, then read its whole tree in one request. */\n  function tree(fullName) {\n    if (!REPO.test(fullName)) return invalid(\"Invalid repository name\");\n    return request(\"/repos/\" + enc(fullName)).then(function (info) {\n      return request(\n        \"/repos/\" +\n          enc(fullName) +\n          \"/git/trees/\" +\n          encodeURIComponent(info.default_branch) +\n          \"?recursive=1\",\n      ).then(function (result) {\n        return {\n          branch: info.default_branch,\n          truncated: Boolean(result.truncated),\n          files: result.tree\n            .filter(function (item) {\n              return item.type === \"blob\";\n            })\n            .map(function (item) {\n              return item.path;\n            }),\n        };\n      });\n    });\n  }\n\n  /* A github.com address for a repository, or for one file in it. Returns \"\" for an invalid name. */\n  function link(fullName, branch, path) {\n    if (!REPO.test(fullName)) return \"\";\n    var base = \"https://github.com/\" + fullName;\n    if (!path) return base;\n    return base + \"/blob/\" + encodeURIComponent(branch || \"HEAD\") + \"/\" + enc(path);\n  }\n\n  window.GH = { profile: profile, repos: repos, tree: tree, link: link, explain: explain };\n})();\n","js/projects.js":"/* Projects page: project cards, a browsable file tree for each repository, and the GitHub profile card. */\n(function () {\n  \"use strict\";\n  var h = window.SiteUtil.h;\n  var S = window.SITE;\n  var GH = window.GH;\n  var $ = function (id) {\n    return document.getElementById(id);\n  };\n  var MAX_ENTRIES = 300;\n\n  /* Links come from data files and from GitHub, so only web addresses are allowed.\n     This keeps a javascript: or data: value out of an href. */\n  function webUrl(value) {\n    try {\n      var url = new URL(String(value));\n      return url.protocol === \"https:\" || url.protocol === \"http:\" ? url.href : \"\";\n    } catch {\n      return \"\";\n    }\n  }\n\n  /* ---------- File tree ---------- */\n\n  /* Turn a flat list of paths into nested folders and files. */\n  function nest(paths) {\n    var root = { dirs: {}, files: [] };\n    paths.forEach(function (path) {\n      var parts = path.split(\"/\");\n      var node = root;\n      parts.slice(0, -1).forEach(function (part) {\n        node.dirs[part] = node.dirs[part] || { dirs: {}, files: [] };\n        node = node.dirs[part];\n      });\n      node.files.push(parts[parts.length - 1]);\n    });\n    return root;\n  }\n\n  function countFiles(node) {\n    return Object.keys(node.dirs).reduce(function (sum, name) {\n      return sum + countFiles(node.dirs[name]);\n    }, node.files.length);\n  }\n\n  /* Folders first, then files, each in alphabetical order.\n     `urlFor` returns a GitHub link, or \"\" when there is none. */\n  function branch(node, prefix, depth, urlFor, openAll) {\n    var list = h(\"ul\", { class: \"tree\" });\n    Object.keys(node.dirs)\n      .sort()\n      .forEach(function (name) {\n        var path = prefix + name;\n        var child = node.dirs[name];\n        var summary = h(\"summary\", {}, [\n          h(\"span\", { class: \"tree-name\", text: name + \"/\" }),\n          h(\"span\", { class: \"tree-count\", text: String(countFiles(child)) }),\n        ]);\n        var details = h(\"details\", { open: openAll || (depth === 0 && name === \"src\") }, [\n          summary,\n          branch(child, path + \"/\", depth + 1, urlFor, openAll),\n        ]);\n        list.appendChild(h(\"li\", { class: \"tree-dir\" }, [details]));\n      });\n    node.files.sort().forEach(function (name) {\n      var url = urlFor(prefix + name);\n      list.appendChild(\n        h(\"li\", { class: \"tree-file\" }, [\n          url ? window.SiteUtil.external(name, url) : h(\"span\", { text: name }),\n        ]),\n      );\n    });\n    return list;\n  }\n\n  function renderTree(paths, urlFor) {\n    var shown = paths.slice(0, MAX_ENTRIES);\n    var root = nest(shown);\n    var wrap = h(\n      \"div\",\n      { class: \"tree-box\", role: \"region\", \"aria-label\": \"Repository files\", tabindex: \"0\" },\n      [branch(root, \"\", 0, urlFor, shown.length \u003c= 24)],\n    );\n    return { node: wrap, clipped: paths.length - shown.length };\n  }\n\n  /* ---------- Project cards ---------- */\n\n  function projectCard(project) {\n    var panel = h(\"div\", { class: \"project-files\", hidden: true });\n    var status = h(\"p\", { class: \"files-status\", role: \"status\" });\n    var holder = h(\"div\", {});\n    panel.appendChild(status);\n    panel.appendChild(holder);\n\n    var loaded = false;\n    function show(paths, branchName, note, live) {\n      holder.textContent = \"\";\n      var urlFor =\n        project.repo && live\n          ? function (path) {\n              return GH.link(project.repo, branchName, path);\n            }\n          : function () {\n              return \"\";\n            };\n      var built = renderTree(paths, urlFor);\n      holder.appendChild(built.node);\n      var more =\n        built.clipped > 0\n          ? \" Showing the first \" + MAX_ENTRIES + \" files; open the repository for the rest.\"\n          : \"\";\n      status.textContent = note + more;\n    }\n    function showSaved(reason) {\n      var paths = project.structure || [];\n      if (!paths.length) {\n        holder.textContent = \"\";\n        status.textContent = reason;\n        return;\n      }\n      var note = project.repo\n        ? reason + \" Showing the saved structure.\"\n        : \"Example structure. The real files appear here once the repository is linked.\";\n      show(paths, \"\", note, false);\n    }\n    function load() {\n      if (loaded) return;\n      loaded = true;\n      if (!project.repo) {\n        showSaved(\"\");\n        return;\n      }\n      status.textContent = \"Loading the file tree from GitHub...\";\n      GH.tree(project.repo)\n        .then(function (result) {\n          show(\n            result.files,\n            result.branch,\n            \"Live from GitHub: \" +\n              project.repo +\n              \", branch \" +\n              result.branch +\n              \", \" +\n              result.files.length +\n              \" files.\",\n            true,\n          );\n        })\n        .catch(function (error) {\n          showSaved(GH.explain(error));\n        });\n    }\n\n    var toggle = h(\"button\", {\n      type: \"button\",\n      class: \"btn btn-sm\",\n      \"aria-expanded\": \"false\",\n      onclick: function () {\n        var open = toggle.getAttribute(\"aria-expanded\") !== \"true\";\n        toggle.setAttribute(\"aria-expanded\", String(open));\n        toggle.textContent = open ? \"Hide file structure\" : \"Browse file structure\";\n        panel.hidden = !open;\n        if (open) load();\n      },\n      text: \"Browse file structure\",\n    });\n\n    var repoUrl = project.repo ? GH.link(project.repo) : \"\";\n    var demoUrl = project.demo ? webUrl(project.demo) : \"\";\n    var actions = h(\"div\", { class: \"project-actions\" }, [\n      repoUrl\n        ? window.SiteUtil.external(\"Open on GitHub\", repoUrl, \"btn btn-sm btn-primary\")\n        : null,\n      demoUrl ? window.SiteUtil.external(\"Live demo\", demoUrl, \"btn btn-sm\") : null,\n      toggle,\n    ]);\n\n    return h(\"li\", { class: \"project\" }, [\n      h(\"div\", { class: \"project-main\" }, [\n        h(\"h3\", {}, [\n          project.name,\n          project.placeholder ? h(\"span\", { class: \"tag\", text: \"Placeholder\" }) : null,\n        ]),\n        h(\"p\", { class: \"desc\", text: project.summary || \"\" }),\n        project.tags && project.tags.length\n          ? h(\n              \"ul\",\n              { class: \"project-tags\", \"aria-label\": \"Technologies\" },\n              project.tags.map(function (tag) {\n                return h(\"li\", { text: tag });\n              }),\n            )\n          : null,\n      ]),\n      actions,\n      panel,\n    ]);\n  }\n\n  window.PROJECTS.forEach(function (project) {\n    $(\"project-list\").appendChild(projectCard(project));\n  });\n\n  /* ---------- GitHub profile and recent repositories ---------- */\n\n  if (S.github) {\n    var section = $(\"github\");\n    section.hidden = false;\n    $(\"gh-handle\").textContent = \"@\" + S.github;\n    var openProfile = $(\"gh-open\");\n    openProfile.href = \"https://github.com/\" + encodeURIComponent(S.github);\n\n    GH.profile(S.github)\n      .then(function (user) {\n        var parts = [user.public_repos + \" public repositories\", user.followers + \" followers\"];\n        $(\"gh-stats\").textContent = parts.join(\" · \");\n        if (user.bio) $(\"gh-bio\").textContent = user.bio;\n      })\n      .catch(function () {\n        $(\"gh-stats\").textContent = \"\";\n      });\n\n    GH.repos(S.github)\n      .then(function (list) {\n        var known = {};\n        window.PROJECTS.forEach(function (p) {\n          if (p.repo) known[p.repo.toLowerCase()] = true;\n        });\n        var fresh = list.filter(function (r) {\n          return !known[r.full_name.toLowerCase()];\n        });\n        if (!fresh.length) return;\n        $(\"recent\").hidden = false;\n        fresh.forEach(function (repo) {\n          $(\"recent-list\").appendChild(\n            projectCard({\n              name: repo.name,\n              summary: repo.description || \"No description yet.\",\n              tags: repo.language ? [repo.language] : [],\n              repo: repo.full_name,\n              demo: repo.homepage || \"\",\n            }),\n          );\n        });\n      })\n      .catch(function (error) {\n        $(\"gh-note\").textContent = GH.explain(error);\n      });\n  }\n})();\n","js/ui.js":"/* UI skills page: connects the \"Try it\" and \"Read the code\" buttons\n   to the demo and to the source explorer. */\n(function () {\n  \"use strict\";\n  var $ = function (id) {\n    return document.getElementById(id);\n  };\n\n  /* The demo needs React from the CDN. If it did not load, say so instead of leaving a blank box. */\n  if (!window.React || !window.ReactDOM) {\n    var root = $(\"lab-root\");\n    root.textContent = \"\";\n    var message = document.createElement(\"p\");\n    message.className = \"lab-loading\";\n    message.textContent =\n      \"The live demo needs React from cdnjs.cloudflare.com, and it did not load. Reload the page, or try a network that can reach that host.\";\n    root.appendChild(message);\n  }\n\n  /* \"Try it\" opens a demo tab, scrolls to the demo and puts focus on the tab. */\n  document.querySelectorAll(\"[data-try]\").forEach(function (button) {\n    button.addEventListener(\"click\", function () {\n      var name = button.dataset.try;\n      window.dispatchEvent(new CustomEvent(\"lab:open\", { detail: name }));\n      $(\"lab\").scrollIntoView();\n      var tab = document.getElementById(\"lab-tab-\" + name);\n      if (tab) tab.focus({ preventScroll: true });\n    });\n  });\n\n  /* \"Read the code\" opens the explorer on one skill. The value looks like \"tsx:session\". */\n  document.querySelectorAll(\"[data-code]\").forEach(function (button) {\n    button.addEventListener(\"click\", function () {\n      var parts = button.dataset.code.split(\":\");\n      window.SourceViewer.open(parts[0], parts[1]);\n    });\n  });\n})();\n","js/viewer.js":"/* Source explorer. It reads this site's own files while the page runs and shows them with line numbers\n   and syntax colors. Skill buttons jump to the lines that use a skill,\n   and a button only appears when its code is found. */\n(function () {\n  \"use strict\";\n  var h = window.SiteUtil.h;\n  var FILES = window.SOURCE_FILES;\n  var SKILLS = window.SKILL_MAP;\n  var $ = function (id) {\n    return document.getElementById(id);\n  };\n  var reduceMotion = window.matchMedia(\"(prefers-reduced-motion: reduce)\");\n\n  var TABS = [\n    {\n      id: \"html\",\n      label: \"HTML\",\n      lang: \"xml\",\n      note: \"The four pages. Landmarks, forms, ARIA and the Content Security Policy are all in the markup.\",\n    },\n    {\n      id: \"css\",\n      label: \"CSS\",\n      lang: \"css\",\n      note: \"Design tokens, light and dark themes, grid, container queries and motion preferences. No framework.\",\n    },\n    {\n      id: \"js\",\n      label: \"JavaScript\",\n      lang: \"javascript\",\n      note: \"Plain JavaScript with no build step: rendering from data files, the GitHub client, the contact form and this viewer.\",\n    },\n    {\n      id: \"tsx\",\n      label: \"React + TypeScript\",\n      lang: \"typescript\",\n      note: \"Strict TypeScript and React, split into modules. The demo above runs the compiled output of exactly these files.\",\n    },\n    {\n      id: \"ng\",\n      label: \"Angular\",\n      lang: \"typescript\",\n      note: \"The same patterns the Angular way. These files pass the strict Angular compiler, but they are source only and do not run on this page.\",\n    },\n  ];\n  var texts = {};\n  var rendered = {};\n  var current = { tab: \"tsx\", file: \"\" };\n  var lastFile = {};\n  var located = {};\n  var chipById = {};\n  var loading = null;\n\n  /* ---------- Loading ---------- */\n\n  function setStatus(state) {\n    var node = $(\"source-status\");\n    node.dataset.state = state;\n    node.textContent =\n      state === \"live\"\n        ? \"Read live from this site's files, just now.\"\n        : \"Showing a bundled copy of the files, because they could not be read live. This happens when the page is opened from disk.\";\n  }\n\n  function fetchText(path) {\n    return fetch(path, { cache: \"no-cache\" }).then(function (response) {\n      if (!response.ok) throw new Error(path + \" answered \" + response.status);\n      return response.text();\n    });\n  }\n\n  /* Opened from disk, browsers refuse fetch(). A generated snapshot of the same files fills the gap. */\n  function loadSnapshot() {\n    return new Promise(function (resolve) {\n      var script = document.createElement(\"script\");\n      script.src = \"js/source-snapshot.js\";\n      script.onload = function () {\n        resolve(window.SOURCE_SNAPSHOT || {});\n      };\n      script.onerror = function () {\n        resolve({});\n      };\n      document.head.appendChild(script);\n    });\n  }\n\n  function loadSources() {\n    if (loading) return loading;\n    var all = [];\n    TABS.forEach(function (tab) {\n      all = all.concat(FILES[tab.id]);\n    });\n    // Browsers refuse fetch() on file: pages, so skip the attempt there and go straight to the bundled copy.\n    var attempt = window.location.protocol === \"file:\" ? [] : all;\n    loading = Promise.all(\n      attempt.map(function (path) {\n        return fetchText(path).then(\n          function (text) {\n            texts[path] = text.replace(/\\s+$/, \"\");\n          },\n          function () {\n            /* handled below */\n          },\n        );\n      }),\n    ).then(function () {\n      var missing = all.filter(function (path) {\n        return texts[path] === undefined;\n      });\n      if (!missing.length) {\n        setStatus(\"live\");\n        return;\n      }\n      return loadSnapshot().then(function (snapshot) {\n        missing.forEach(function (path) {\n          if (typeof snapshot[path] === \"string\") texts[path] = snapshot[path].replace(/\\s+$/, \"\");\n        });\n        setStatus(\"copy\");\n      });\n    });\n    return loading;\n  }\n\n  /* ---------- Highlighting ---------- */\n\n  function escapeHtml(text) {\n    return text.replace(/&/g, \"&amp;\").replace(/\u003c/g, \"&lt;\").replace(/>/g, \"&gt;\");\n  }\n\n  /* A highlighted span can run across a line break. Close open spans at the end of each line and reopen them\n     on the next, so every line stands on its own and can be numbered and highlighted. */\n  function splitLines(html) {\n    var open = [];\n    return html.split(\"\\n\").map(function (line) {\n      var prefix = open.join(\"\");\n      var tags = /\u003c(\\/?)span([^>]*)>/g;\n      var match;\n      while ((match = tags.exec(line))) {\n        if (match[1]) open.pop();\n        else open.push(\"\u003cspan\" + match[2] + \">\");\n      }\n      return prefix + line + new Array(open.length + 1).join(\"\u003c/span>\");\n    });\n  }\n\n  function tabOf(id) {\n    return TABS.filter(function (tab) {\n      return tab.id === id;\n    })[0];\n  }\n  function tabForFile(path) {\n    return TABS.filter(function (tab) {\n      return FILES[tab.id].indexOf(path) !== -1;\n    })[0];\n  }\n\n  function render(path) {\n    if (rendered[path]) return rendered[path];\n    var source = texts[path] || \"\";\n    var lang = tabForFile(path).lang;\n    var html;\n    try {\n      // highlight.js escapes the source. If the library did not load, escape it here.\n      html = window.hljs\n        ? window.hljs.highlight(source, { language: lang }).value\n        : escapeHtml(source);\n    } catch {\n      html = escapeHtml(source);\n    }\n    rendered[path] = splitLines(html)\n      .map(function (line, index) {\n        return '\u003cspan class=\"line\" data-n=\"' + (index + 1) + '\">' + line + \"\u003c/span>\";\n      })\n      .join(\"\");\n    return rendered[path];\n  }\n\n  /* ---------- Finding where a skill lives ---------- */\n\n  function indent(line) {\n    return line.length - line.replace(/^\\s+/, \"\").length;\n  }\n\n  /* A block runs from its first line to the first line indented no deeper,\n     and includes that line when it only closes the block. */\n  function blockEnd(lines, start) {\n    var base = indent(lines[start]);\n    var end;\n    for (end = start + 1; end \u003c lines.length; end++) {\n      if (!lines[end].trim()) continue;\n      var depth = indent(lines[end]);\n      if (depth > base) continue;\n      if (depth === base && /^\\s*(\\}|\\)|\\]|\u003c\\/)/.test(lines[end])) return end;\n      break;\n    }\n    while (end > start + 1 && !lines[end - 1].trim()) end--;\n    return end - 1;\n  }\n\n  /* Only list a skill if its code is really in the file it names. */\n  function locate(tab) {\n    return (SKILLS[tab] || [])\n      .map(function (skill) {\n        var text = texts[skill.file];\n        if (typeof text !== \"string\") return null;\n        var lines = text.split(\"\\n\");\n        for (var i = 0; i \u003c lines.length; i++) {\n          if (lines[i].indexOf(skill.find) !== -1) {\n            var end = skill.n ? i + skill.n - 1 : blockEnd(lines, i);\n            return {\n              skill: skill,\n              file: skill.file,\n              line: i + 1,\n              last: Math.min(lines.length, i + 70, end + 1),\n            };\n          }\n        }\n        return null;\n      })\n      .filter(Boolean);\n  }\n\n  /* ---------- Drawing ---------- */\n\n  function showNote(entry) {\n    var note = $(\"skill-note\");\n    note.textContent = \"\";\n    if (!entry) {\n      note.textContent = \"Pick a skill to jump to the code that uses it.\";\n      return;\n    }\n    var range =\n      entry.last > entry.line ? \"lines \" + entry.line + \" to \" + entry.last : \"line \" + entry.line;\n    note.appendChild(h(\"strong\", { text: entry.skill.name }));\n    note.appendChild(\n      document.createTextNode(\" \" + entry.skill.desc + \" (\" + entry.file + \", \" + range + \")\"),\n    );\n  }\n\n  function commonDir(paths) {\n    var parts = paths.map(function (p) {\n      return p.split(\"/\").slice(0, -1);\n    });\n    var prefix = parts[0] || [];\n    parts.forEach(function (list) {\n      var i = 0;\n      while (i \u003c prefix.length && prefix[i] === list[i]) i++;\n      prefix = prefix.slice(0, i);\n    });\n    return prefix.length ? prefix.join(\"/\") + \"/\" : \"\";\n  }\n\n  function drawFiles(tab) {\n    var list = $(\"files\");\n    list.textContent = \"\";\n    var paths = FILES[tab];\n    var trim = commonDir(paths);\n    paths.forEach(function (path) {\n      var relative = path.slice(trim.length);\n      var slash = relative.lastIndexOf(\"/\");\n      var dir = slash === -1 ? \"\" : relative.slice(0, slash + 1);\n      var lines = (texts[path] || \"\").split(\"\\n\").length;\n      list.appendChild(\n        h(\n          \"button\",\n          {\n            type: \"button\",\n            class: \"file\",\n            \"data-path\": path,\n            \"aria-current\": String(path === current.file),\n            onclick: function () {\n              selectFile(path);\n            },\n          },\n          [\n            dir ? h(\"span\", { class: \"file-dir\", text: dir }) : null,\n            h(\"span\", {\n              class: \"file-name\",\n              text: slash === -1 ? relative : relative.slice(slash + 1),\n            }),\n            h(\"small\", { text: String(lines) }),\n          ],\n        ),\n      );\n    });\n  }\n\n  function selectFile(path) {\n    current.file = path;\n    lastFile[current.tab] = path;\n    document.querySelectorAll(\"#files .file\").forEach(function (button) {\n      button.setAttribute(\"aria-current\", String(button.dataset.path === path));\n    });\n    var lines = (texts[path] || \"\").split(\"\\n\").length;\n    $(\"pane-path\").textContent = path;\n    $(\"pane-meta\").textContent = lines + \" lines\";\n    $(\"code\").innerHTML = render(path); // built from highlight.js output or escaped text, never raw source\n    var box = $(\"codebox\");\n    box.scrollTop = 0;\n    box.scrollLeft = 0;\n    box.setAttribute(\"aria-label\", \"Source of \" + path);\n  }\n\n  function selectTab(id, focus) {\n    current.tab = id;\n    TABS.forEach(function (tab) {\n      var button = $(\"tab-\" + tab.id);\n      var on = tab.id === id;\n      button.setAttribute(\"aria-selected\", String(on));\n      button.tabIndex = on ? 0 : -1;\n      button.querySelector(\"small\").textContent =\n        FILES[tab.id].length + (FILES[tab.id].length === 1 ? \" file\" : \" files\");\n    });\n    $(\"explorer\").setAttribute(\"aria-labelledby\", \"tab-\" + id);\n    if (focus) $(\"tab-\" + id).focus();\n    $(\"tab-note\").textContent = tabOf(id).note;\n\n    located[id] = located[id] || locate(id);\n    var holder = $(\"skills\");\n    holder.textContent = \"\";\n    chipById = {};\n    var groups = new Map();\n    located[id].forEach(function (entry) {\n      if (!groups.has(entry.skill.group)) groups.set(entry.skill.group, []);\n      groups.get(entry.skill.group).push(entry);\n    });\n    groups.forEach(function (entries, name) {\n      var row = h(\"div\", { class: \"skill-row\" });\n      entries.forEach(function (entry) {\n        var button = h(\n          \"button\",\n          {\n            type: \"button\",\n            class: \"skill\",\n            \"aria-pressed\": \"false\",\n            onclick: function () {\n              jump(entry, button);\n            },\n          },\n          [entry.skill.name, h(\"small\", { text: entry.file.split(\"/\").pop() + \":\" + entry.line })],\n        );\n        if (entry.skill.id) chipById[entry.skill.id] = button;\n        row.appendChild(button);\n      });\n      holder.appendChild(h(\"div\", { class: \"skill-group\" }, [h(\"p\", { text: name }), row]));\n    });\n\n    var first = located[id][0];\n    var path = lastFile[id] || (first ? first.file : FILES[id][0]);\n    drawFiles(id);\n    selectFile(path);\n    showNote(null);\n  }\n\n  function jump(entry, button) {\n    if (entry.file !== current.file) selectFile(entry.file);\n    var box = $(\"codebox\");\n    box.querySelectorAll(\".hit\").forEach(function (node) {\n      node.classList.remove(\"hit\");\n    });\n    var first = null;\n    for (var n = entry.line; n \u003c= entry.last; n++) {\n      var node = box.querySelector('.line[data-n=\"' + n + '\"]');\n      if (node) {\n        node.classList.add(\"hit\");\n        if (!first) first = node;\n      }\n    }\n    document.querySelectorAll(\"#skills .skill\").forEach(function (chip) {\n      chip.setAttribute(\"aria-pressed\", String(chip === button));\n    });\n    showNote(entry);\n    if (first)\n      box.scrollTo({\n        top: Math.max(0, first.offsetTop - box.clientHeight / 3),\n        behavior: reduceMotion.matches ? \"auto\" : \"smooth\",\n      });\n    $(\"explorer\").scrollIntoView({ block: \"nearest\" });\n  }\n\n  /* ---------- Wiring ---------- */\n\n  TABS.forEach(function (tab, index) {\n    var button = $(\"tab-\" + tab.id);\n    button.addEventListener(\"click\", function () {\n      selectTab(tab.id);\n    });\n    button.addEventListener(\"keydown\", function (event) {\n      var target = { ArrowRight: index + 1, ArrowLeft: index - 1, Home: 0, End: TABS.length - 1 }[\n        event.key\n      ];\n      if (target === undefined) return;\n      event.preventDefault();\n      selectTab(TABS[(target + TABS.length) % TABS.length].id, true);\n    });\n  });\n  $(\"copy-code\").addEventListener(\"click\", function (event) {\n    window.SiteUtil.copyText(\n      event.currentTarget,\n      texts[current.file] || \"\",\n      $(\"code\"),\n      \"Copy file\",\n    );\n  });\n\n  /* Other parts of the page open the explorer on a named skill, for example \"tsx:session\". */\n  function open(tab, id) {\n    return loadSources().then(function () {\n      selectTab(tab);\n      if (chipById[id]) chipById[id].click();\n    });\n  }\n\n  loadSources().then(function () {\n    selectTab(current.tab);\n  });\n  window.SourceViewer = { open: open };\n})();\n","src/lab/main.tsx":"/* Entry point. Providers wrap the shell, and an error boundary sits outside all of them. */\nimport type { ReactNode } from \"react\";\nimport { AuthProvider } from \"./auth\";\nimport { StoreProvider } from \"./store\";\nimport { ErrorBoundary } from \"./components/ErrorBoundary\";\nimport { LabShell } from \"./components/LabShell\";\n\ndeclare const ReactDOM: { createRoot(el: Element): { render(node: ReactNode): void } };\n\nfunction App() {\n  return (\n    \u003cErrorBoundary label=\"The lab\">\n      \u003cAuthProvider>\n        \u003cStoreProvider>\n          \u003cLabShell />\n        \u003c/StoreProvider>\n      \u003c/AuthProvider>\n    \u003c/ErrorBoundary>\n  );\n}\n\nconst mount = document.getElementById(\"lab-root\");\nif (mount) ReactDOM.createRoot(mount).render(\u003cApp />);\n","src/lab/types.ts":"/* Domain types and the small type guards that narrow untrusted values to them. */\n\nexport type Role = \"viewer\" | \"admin\";\nexport type Severity = \"low\" | \"medium\" | \"high\";\nexport type RiskStatus = \"open\" | \"mitigating\" | \"resolved\";\nexport type Fields = Record\u003cstring, string>;\n\nexport interface Risk {\n  readonly id: string;\n  title: string;\n  owner: string;\n  severity: Severity;\n  status: RiskStatus;\n  reference?: string;\n  description?: string;\n}\nexport interface Session {\n  readonly token: string;\n  readonly user: string;\n  readonly role: Role;\n  readonly expiresAt: number;\n}\nexport interface NewRisk {\n  title: string;\n  owner: string;\n  severity: Severity;\n  reference?: string;\n  description: string;\n}\nexport type Parsed\u003cT> = { ok: true; value: T } | { ok: false; errors: Fields };\n\nexport const SEVERITIES: readonly Severity[] = [\"low\", \"medium\", \"high\"];\nexport const STATUSES: readonly RiskStatus[] = [\"open\", \"mitigating\", \"resolved\"];\nexport const isSeverity = (v: unknown): v is Severity => SEVERITIES.some((s) => s === v);\nexport const isStatus = (v: unknown): v is RiskStatus => STATUSES.some((s) => s === v);\n","src/lab/permissions.ts":"/* One role-to-permission table. The screen and the API both ask it, so they cannot disagree. */\nimport type { Role } from \"./types\";\n\nexport type Permission = \"risk:read\" | \"risk:update\" | \"risk:create\";\nexport const PERMISSIONS: Readonly\u003cRecord\u003cRole, readonly Permission[]>> = {\n  viewer: [\"risk:read\"],\n  admin: [\"risk:read\", \"risk:update\", \"risk:create\"],\n};\nexport const can = (role: Role | undefined, permission: Permission): boolean =>\n  role !== undefined && PERMISSIONS[role].includes(permission);\n","src/lab/validation.ts":"/* Validation shared by the form and the server. The server never trusts the client's own checks. */\nimport type { Fields, NewRisk, Parsed } from \"./types\";\nimport { isSeverity } from \"./types\";\n\n// name@host.tld: no spaces, no empty parts between dots, and a top-level domain of 2+ characters.\nconst EMAIL = /^[^\\s@]{1,64}@[^\\s@.]+(?:\\.[^\\s@.]+)*\\.[^\\s@.]{2,}$/;\nconst MAX_LINK_LENGTH = 200;\n\nexport function isHttpsUrl(value: string): boolean {\n  // The prefix check rejects \"https:example.com\", which the URL parser accepts but a browser\n  // would resolve as a link on the current site.\n  if (!/^https:\\/\\//i.test(value)) return false;\n  try {\n    const url = new URL(value);\n    // Allow-list the scheme. \"javascript:\" and \"data:\" links never pass.\n    return !url.username && !url.password;\n  } catch {\n    return false;\n  }\n}\n\n/** Turns untrusted input into a NewRisk, or says exactly which fields are wrong. */\nexport function parseNewRisk(input: unknown): Parsed\u003cNewRisk> {\n  const o: Record\u003cstring, unknown> =\n    typeof input === \"object\" && input !== null ? (input as Record\u003cstring, unknown>) : {};\n  const text = (key: string): string =>\n    typeof o[key] === \"string\" ? (o[key] as string).trim() : \"\";\n  const errors: Fields = {};\n\n  const title = text(\"title\");\n  if (title.length \u003c 3) errors.title = \"Enter at least 3 characters.\";\n  else if (title.length > 80) errors.title = \"Use 80 characters or fewer.\";\n\n  const owner = text(\"owner\");\n  if (owner.length > 254 || !EMAIL.test(owner))\n    errors.owner = \"Enter a valid email address, like name@company.com.\";\n\n  const severity = text(\"severity\");\n  if (!isSeverity(severity)) errors.severity = \"Choose low, medium or high.\";\n\n  const reference = text(\"reference\");\n  if (reference.length > MAX_LINK_LENGTH)\n    errors.reference = `Use ${MAX_LINK_LENGTH} characters or fewer.`;\n  else if (reference && !isHttpsUrl(reference))\n    errors.reference = \"Use a full https:// link with no username or password.\";\n\n  const description = typeof o.description === \"string\" ? o.description : \"\";\n  if (description.length > 280) errors.description = \"Use 280 characters or fewer.\";\n\n  if (Object.keys(errors).length > 0 || !isSeverity(severity)) return { ok: false, errors };\n  return {\n    ok: true,\n    value: {\n      title,\n      owner: owner.toLowerCase(),\n      severity,\n      description,\n      ...(reference ? { reference } : {}),\n    },\n  };\n}\n\nconst COMMON_PASSWORDS = new Set([\n  \"password\",\n  \"password1\",\n  \"123456789012\",\n  \"qwertyuiopas\",\n  \"letmein12345\",\n]);\nexport function passwordChecks(pw: string): ReadonlyArray\u003c{ label: string; ok: boolean }> {\n  return [\n    { label: \"12 or more characters\", ok: pw.length >= 12 },\n    { label: \"Upper and lower case letters\", ok: /[a-z]/.test(pw) && /[A-Z]/.test(pw) },\n    { label: \"A number\", ok: /\\d/.test(pw) },\n    { label: \"A symbol\", ok: /[^A-Za-z0-9]/.test(pw) },\n    {\n      label: \"Not a common password\",\n      ok: pw.length > 0 && !COMMON_PASSWORDS.has(pw.toLowerCase()),\n    },\n  ];\n}\n","src/lab/sanitize.ts":"/* Allow-list sanitizer for untrusted markup. */\nimport { isHttpsUrl } from \"./validation\";\n\nconst ALLOWED_TAGS = new Set([\"B\", \"I\", \"EM\", \"STRONG\", \"A\", \"BR\", \"CODE\"]);\nconst DROP_WITH_CONTENT = new Set([\n  \"SCRIPT\",\n  \"STYLE\",\n  \"IFRAME\",\n  \"OBJECT\",\n  \"EMBED\",\n  \"TEMPLATE\",\n  \"NOSCRIPT\",\n  \"SVG\",\n  \"MATH\",\n]);\n\n/** Attributes that run code or inject styling. They are never copied, and the report names them. */\nconst isRiskyAttribute = (name: string): boolean =>\n  name.startsWith(\"on\") || name === \"style\" || name === \"srcdoc\";\n\n/** Allow-list sanitizer. It parses into an inert document, then rebuilds only safe nodes with createElement. */\nexport function sanitize(html: string): { fragment: DocumentFragment; blocked: string[] } {\n  // Nothing in this document runs or loads. Under a strict CSP the browser may still log\n  // \"Refused to apply inline style\" when pasted markup has a style attribute. That is the policy\n  // working, and the attribute is never copied.\n  const doc = new DOMParser().parseFromString(html, \"text/html\");\n  const fragment = document.createDocumentFragment();\n  const blocked: string[] = [];\n\n  const copy = (from: Node, into: Node): void => {\n    from.childNodes.forEach((node) => {\n      if (node.nodeType === Node.TEXT_NODE) {\n        into.appendChild(document.createTextNode(node.textContent ?? \"\"));\n        return;\n      }\n      if (!(node instanceof Element)) return;\n      const tag = node.tagName.toUpperCase();\n      node\n        .getAttributeNames()\n        .filter(isRiskyAttribute)\n        .forEach((n) => blocked.push(`${n} attribute`));\n      if (DROP_WITH_CONTENT.has(tag)) {\n        blocked.push(`\u003c${tag.toLowerCase()}> element`);\n        return;\n      }\n      if (!ALLOWED_TAGS.has(tag)) {\n        blocked.push(`\u003c${tag.toLowerCase()}> tag`);\n        copy(node, into); // keep the text, drop the wrapper\n        return;\n      }\n      const clean = document.createElement(tag.toLowerCase());\n      if (tag === \"A\") {\n        const href = node.getAttribute(\"href\");\n        if (href !== null && isHttpsUrl(href)) {\n          clean.setAttribute(\"href\", href);\n          clean.setAttribute(\"rel\", \"noopener noreferrer\");\n          clean.setAttribute(\"target\", \"_blank\");\n        } else if (href !== null) {\n          blocked.push(\"unsafe link address\");\n        }\n      }\n      copy(node, clean);\n      into.appendChild(clean);\n    });\n  };\n  // The parser moves a leading \u003cscript> or \u003cstyle> into \u003chead>. Nothing in \u003chead> is copied,\n  // but the report should still say it was there.\n  Array.from(doc.head.children).forEach((el) =>\n    blocked.push(`\u003c${el.tagName.toLowerCase()}> element`),\n  );\n  copy(doc.body, fragment);\n  return { fragment, blocked: Array.from(new Set(blocked)) };\n}\n","src/lab/errors.ts":"/* Errors the app understands, and the plain-language message each one maps to. */\nimport type { Fields } from \"./types\";\n\nexport class HttpError extends Error {\n  constructor(\n    readonly status: number,\n    message: string,\n    readonly fields: Fields = {},\n    readonly retryAfterMs = 0,\n  ) {\n    super(message);\n    this.name = \"HttpError\";\n  }\n}\nexport class NetworkError extends Error {\n  constructor() {\n    super(\"Network unreachable\");\n    this.name = \"NetworkError\";\n  }\n}\nexport class TimeoutError extends Error {\n  constructor(readonly ms: number) {\n    super(`No response after ${ms} ms`);\n    this.name = \"TimeoutError\";\n  }\n}\n\n/** What the person sees. Never a stack trace, never a raw server message. */\nexport function userMessage(error: unknown): string {\n  if (error instanceof TimeoutError) return \"The server took too long to answer. Try again.\";\n  if (error instanceof NetworkError)\n    return \"You appear to be offline. Check your connection and try again.\";\n  if (error instanceof HttpError) {\n    switch (error.status) {\n      case 401:\n        return \"Your session has ended. Sign in again.\";\n      case 403:\n        return \"Your role does not allow this action.\";\n      case 422:\n        return \"Some fields need attention.\";\n      case 429:\n        return `Too many attempts. Try again in ${Math.ceil(error.retryAfterMs / 1000)} s.`;\n      default:\n        return error.status >= 500\n          ? \"The server hit a problem. Nothing was changed.\"\n          : \"The request could not be completed.\";\n    }\n  }\n  return \"Something unexpected went wrong.\";\n}\n","src/lab/util.ts":"/* Small framework-free helpers. */\n\nexport function sleep(ms: number, signal?: AbortSignal): Promise\u003cvoid> {\n  return new Promise((resolve, reject) => {\n    if (signal?.aborted) {\n      reject(new DOMException(\"Aborted\", \"AbortError\"));\n      return;\n    }\n    const onAbort = (): void => {\n      window.clearTimeout(timer);\n      reject(new DOMException(\"Aborted\", \"AbortError\"));\n    };\n    const timer = window.setTimeout(() => {\n      signal?.removeEventListener(\"abort\", onAbort);\n      resolve();\n    }, ms);\n    signal?.addEventListener(\"abort\", onAbort, { once: true });\n  });\n}\n\nexport function randomToken(bytes = 16): string {\n  const buf = new Uint8Array(bytes);\n  crypto.getRandomValues(buf);\n  return Array.from(buf, (b) => b.toString(16).padStart(2, \"0\")).join(\"\");\n}\n\n/** Compares without exiting at the first difference, so timing does not leak how close a guess was. */\nexport function constantTimeEqual(a: string, b: string): boolean {\n  let diff = a.length ^ b.length;\n  const n = Math.max(a.length, b.length);\n  for (let i = 0; i \u003c n; i++) diff |= (a.charCodeAt(i) || 0) ^ (b.charCodeAt(i) || 0);\n  return diff === 0;\n}\n\nexport const clock = (seconds: number): string =>\n  `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, \"0\")}`;\n","src/lab/config.ts":"/* Settings. The session length can be changed in data/settings.js. */\n\ninterface SiteSettings {\n  lab?: { sessionSeconds?: number };\n}\n\nconst site = (window as unknown as { SITE?: SiteSettings }).SITE;\n\nexport const SESSION_SECONDS: number = site?.lab?.sessionSeconds ?? 90;\nexport const LOCKOUT_MS = 15_000;\nexport const MAX_ATTEMPTS = 3;\n","src/lab/react.ts":"/* React comes from a CDN as a global, so every module takes it from here.\n   With a bundler and npm you would write `import { useState } from \"react\"` instead. */\nexport const {\n  Component,\n  createContext,\n  memo,\n  useCallback,\n  useContext,\n  useEffect,\n  useId,\n  useMemo,\n  useReducer,\n  useRef,\n  useState,\n} = React;\n","src/lab/server.ts":"/* A simulated server. It stands in for the network, so the sign-in, permission, validation, retry and\n   rollback logic around it is real application code with no real requests behind it. */\nimport { SESSION_SECONDS, LOCKOUT_MS, MAX_ATTEMPTS } from \"./config\";\nimport { HttpError, NetworkError } from \"./errors\";\nimport { can } from \"./permissions\";\nimport type { Permission } from \"./permissions\";\nimport type { Risk, RiskStatus, Role, Session, Severity } from \"./types\";\nimport { isStatus } from \"./types\";\nimport { constantTimeEqual, randomToken, sleep } from \"./util\";\nimport { parseNewRisk } from \"./validation\";\n\nexport type HttpMethod = \"GET\" | \"POST\" | \"PATCH\" | \"DELETE\";\ntype Chaos = \"none\" | \"flaky\" | \"slow\" | \"down\";\ninterface ApiRequest {\n  method: HttpMethod;\n  path: string;\n  body?: unknown;\n  token?: string;\n  simulateFailure?: boolean;\n}\n\nconst USERS: Readonly\u003cRecord\u003cstring, { password: string; role: Role }>> = {\n  analyst: { password: \"Analyst#2026\", role: \"viewer\" },\n  lead: { password: \"Lead#2026\", role: \"admin\" },\n};\n\nfunction seedRisks(): Risk[] {\n  const rows: ReadonlyArray\u003creadonly [string, Severity, RiskStatus, string]> = [\n    [\"Legacy platform cutover window slips\", \"high\", \"open\", \"alex.rivera\"],\n    [\"Month-end journal reconciliation breaks\", \"high\", \"mitigating\", \"sam.okafor\"],\n    [\"UAT sign-off delayed by SME availability\", \"medium\", \"open\", \"priya.nair\"],\n    [\"Vendor change request backlog grows\", \"medium\", \"mitigating\", \"jordan.lee\"],\n    [\"Migrated balances not yet verified\", \"high\", \"open\", \"alex.rivera\"],\n    [\"Hypercare staffing gap after go-live\", \"low\", \"open\", \"taylor.kim\"],\n    [\"Report mapping differs from source\", \"medium\", \"resolved\", \"sam.okafor\"],\n    [\"Access review not scheduled before audit\", \"low\", \"resolved\", \"priya.nair\"],\n  ];\n  return rows.map(([title, severity, status, who], i) => ({\n    id: `R-${101 + i}`,\n    title,\n    severity,\n    status,\n    owner: `${who}@example.com`,\n  }));\n}\n\nexport const server = (() => {\n  const sessions = new Map\u003cstring, Session>();\n  const attempts = new Map\u003cstring, { count: number; lockedUntil: number }>();\n  const risks: Risk[] = seedRisks();\n  let nextId = 109;\n  const chaos = { mode: \"none\" as Chaos, flakyLeft: 0, slowLeft: 0 };\n\n  function authenticate(token: string | undefined): Session {\n    const session = token ? sessions.get(token) : undefined;\n    if (!session || session.expiresAt \u003c= Date.now()) {\n      if (token) sessions.delete(token);\n      throw new HttpError(401, \"Not signed in\");\n    }\n    return session;\n  }\n  function require(session: Session, permission: Permission): void {\n    if (!can(session.role, permission)) throw new HttpError(403, \"Forbidden\"); // enforced here, not only in the UI\n  }\n\n  function login(body: unknown): Session {\n    const o = typeof body === \"object\" && body !== null ? (body as Record\u003cstring, unknown>) : {};\n    const username =\n      typeof o.username === \"string\" ? o.username.trim().toLowerCase().slice(0, 40) : \"\";\n    const password = typeof o.password === \"string\" ? o.password.slice(0, 200) : \"\";\n    const now = Date.now();\n    let record = attempts.get(username) ?? { count: 0, lockedUntil: 0 };\n    if (record.lockedUntil > now)\n      throw new HttpError(429, \"Too many attempts\", {}, record.lockedUntil - now);\n    if (record.lockedUntil !== 0) record = { count: 0, lockedUntil: 0 };\n\n    // Object.hasOwn stops names like \"constructor\" from matching inherited properties.\n    const user = Object.hasOwn(USERS, username) ? USERS[username] : undefined;\n    // A real server stores a salted hash (argon2 or bcrypt).\n    // Compare even for unknown users, so timing does not reveal which names exist.\n    const matches = constantTimeEqual(password, user?.password ?? \"x\".repeat(12));\n    if (!user || !matches) {\n      const count = record.count + 1;\n      const lockedUntil = count >= MAX_ATTEMPTS ? now + LOCKOUT_MS : 0;\n      attempts.set(username, { count, lockedUntil });\n      if (lockedUntil) throw new HttpError(429, \"Too many attempts\", {}, LOCKOUT_MS);\n      throw new HttpError(401, \"Invalid credentials\"); // same answer for a wrong name and a wrong password\n    }\n    attempts.delete(username);\n    const session: Session = {\n      token: randomToken(),\n      user: username,\n      role: user.role,\n      expiresAt: now + SESSION_SECONDS * 1000,\n    };\n    sessions.set(session.token, session);\n    return { ...session };\n  }\n\n  async function status(signal: AbortSignal): Promise\u003cunknown> {\n    switch (chaos.mode) {\n      case \"down\":\n        throw new NetworkError();\n      case \"flaky\":\n        if (chaos.flakyLeft > 0) {\n          chaos.flakyLeft--;\n          throw new HttpError(503, \"Service unavailable\");\n        }\n        break;\n      case \"slow\":\n        if (chaos.slowLeft > 0) {\n          chaos.slowLeft--;\n          await sleep(6000, signal);\n        }\n        break;\n      case \"none\":\n        break;\n    }\n    return { ok: true, servedAt: new Date().toISOString() };\n  }\n\n  async function handle(req: ApiRequest, signal: AbortSignal): Promise\u003cunknown> {\n    await sleep(200 + Math.random() * 250, signal); // simulated latency\n    const { method, path } = req;\n    if (method === \"GET\" && path === \"/status\") return status(signal);\n    if (method === \"POST\" && path === \"/session\") return login(req.body);\n\n    const session = authenticate(req.token); // everything below needs a live session\n    if (method === \"DELETE\" && path === \"/session\") {\n      sessions.delete(session.token);\n      return { ok: true };\n    }\n    if (method === \"POST\" && path === \"/session/refresh\") {\n      const renewed: Session = { ...session, expiresAt: Date.now() + SESSION_SECONDS * 1000 };\n      sessions.set(renewed.token, renewed);\n      return { ...renewed };\n    }\n    if (method === \"GET\" && path === \"/risks\") {\n      require(session, \"risk:read\");\n      return risks.map((r) => ({ ...r }));\n    }\n    if (method === \"POST\" && path === \"/risks\") {\n      require(session, \"risk:create\");\n      const parsed = parseNewRisk(req.body); // never trust the client's own validation\n      if (!parsed.ok) throw new HttpError(422, \"Validation failed\", parsed.errors);\n      const { title, owner, severity, reference, description } = parsed.value;\n      const risk: Risk = {\n        id: `R-${nextId++}`,\n        title,\n        owner,\n        severity,\n        status: \"open\",\n        ...(reference ? { reference } : {}),\n        ...(description ? { description } : {}),\n      };\n      risks.push(risk);\n      return { ...risk };\n    }\n    const match = /^\\/risks\\/(R-\\d+)$/.exec(path);\n    if (method === \"PATCH\" && match?.[1]) {\n      require(session, \"risk:update\");\n      const body =\n        typeof req.body === \"object\" && req.body !== null\n          ? (req.body as Record\u003cstring, unknown>)\n          : {};\n      if (!isStatus(body.status))\n        throw new HttpError(422, \"Validation failed\", {\n          status: \"Choose open, mitigating or resolved.\",\n        });\n      if (req.simulateFailure) throw new HttpError(500, \"Update failed\");\n      const target = risks.find((r) => r.id === match[1]);\n      if (!target) throw new HttpError(404, \"Not found\");\n      target.status = body.status;\n      return { ...target };\n    }\n    throw new HttpError(404, \"Not found\");\n  }\n\n  return {\n    handle,\n    arm(mode: Chaos): void {\n      chaos.mode = mode;\n      chaos.flakyLeft = mode === \"flaky\" ? 2 : 0;\n      chaos.slowLeft = mode === \"slow\" ? 1 : 0;\n    },\n    revokeSessions(): void {\n      sessions.clear();\n    },\n  };\n})();\n","src/lab/api.ts":"/* API client: timeout, retry with backoff, and typed errors. */\nimport { HttpError, NetworkError, TimeoutError } from \"./errors\";\nimport { server } from \"./server\";\nimport type { HttpMethod } from \"./server\";\nimport { sleep } from \"./util\";\n\nexport interface AttemptLog {\n  n: number;\n  outcome: \"ok\" | \"failed\" | \"retrying\";\n  detail: string;\n}\nexport interface RequestOptions {\n  body?: unknown;\n  token?: string;\n  retries?: number;\n  timeoutMs?: number;\n  simulateFailure?: boolean;\n  onAttempt?: (attempt: AttemptLog) => void;\n}\n\n/** Only a failure that says nothing about the request itself is worth another try. */\nconst retryable = (e: unknown): boolean =>\n  e instanceof NetworkError ||\n  e instanceof TimeoutError ||\n  (e instanceof HttpError && e.status >= 500);\nconst backoff = (attempt: number): number => 300 * 2 ** attempt + Math.round(Math.random() * 100);\nconst describe = (e: unknown): string =>\n  e instanceof HttpError\n    ? `HTTP ${e.status}`\n    : e instanceof TimeoutError\n      ? `timed out after ${e.ms} ms`\n      : e instanceof NetworkError\n        ? \"network unreachable\"\n        : \"unexpected error\";\n\nexport async function api\u003cT>(\n  method: HttpMethod,\n  path: string,\n  opts: RequestOptions = {},\n): Promise\u003cT> {\n  const { retries = 0, timeoutMs = 4000, onAttempt, ...rest } = opts;\n  // Only reads are repeated. Repeating a POST or PATCH could write the same change twice.\n  const maxRetries = method === \"GET\" ? retries : 0;\n  for (let attempt = 0; ; attempt++) {\n    const controller = new AbortController();\n    let timedOut = false;\n    const timer = window.setTimeout(() => {\n      timedOut = true;\n      controller.abort();\n    }, timeoutMs);\n    try {\n      const result = (await server.handle({ method, path, ...rest }, controller.signal)) as T;\n      onAttempt?.({ n: attempt + 1, outcome: \"ok\", detail: \"succeeded\" });\n      return result;\n    } catch (err) {\n      const error: unknown =\n        timedOut && err instanceof DOMException ? new TimeoutError(timeoutMs) : err;\n      if (attempt >= maxRetries || !retryable(error)) {\n        onAttempt?.({ n: attempt + 1, outcome: \"failed\", detail: `${describe(error)}, giving up` });\n        throw error;\n      }\n      const wait = backoff(attempt);\n      onAttempt?.({\n        n: attempt + 1,\n        outcome: \"retrying\",\n        detail: `${describe(error)}, retrying in ${wait} ms`,\n      });\n      await sleep(wait);\n    } finally {\n      window.clearTimeout(timer);\n    }\n  }\n}\n\n/** Test controls for the Failures tab. They are not part of the API a real client would have. */\nexport const testControls = { arm: server.arm, revokeSessions: server.revokeSessions };\n","src/lab/auth.tsx":"/* Authentication context: session state, expiry, and one place that handles a 401. */\nimport type { ReactNode } from \"react\";\nimport {\n  createContext,\n  useCallback,\n  useContext,\n  useEffect,\n  useMemo,\n  useRef,\n  useState,\n} from \"./react\";\nimport { api } from \"./api\";\nimport type { RequestOptions } from \"./api\";\nimport { HttpError } from \"./errors\";\nimport type { HttpMethod } from \"./server\";\nimport { useNow } from \"./hooks/useNow\";\nimport type { Session } from \"./types\";\n\ninterface AuthApi {\n  session: Session | null;\n  notice: string | null;\n  secondsLeft: number;\n  signIn(username: string, password: string): Promise\u003cvoid>;\n  signOut(): Promise\u003cvoid>;\n  extend(): Promise\u003cvoid>;\n  request\u003cT>(method: HttpMethod, path: string, opts?: RequestOptions): Promise\u003cT>;\n}\nconst AuthContext = createContext\u003cAuthApi | null>(null);\n\nexport function useAuth(): AuthApi {\n  const ctx = useContext(AuthContext);\n  if (!ctx) throw new Error(\"useAuth must be used inside \u003cAuthProvider>\");\n  return ctx;\n}\n\nexport function AuthProvider({ children }: { children: ReactNode }) {\n  // The token lives in memory only. Nothing goes to localStorage,\n  // so a script injected later cannot read it back.\n  const [session, setSession] = useState\u003cSession | null>(null);\n  const [notice, setNotice] = useState\u003cstring | null>(null);\n  const sessionRef = useRef\u003cSession | null>(null);\n  sessionRef.current = session;\n  const now = useNow(session ? 500 : null);\n  const secondsLeft = session ? Math.max(0, Math.ceil((session.expiresAt - now) / 1000)) : 0;\n\n  const endSession = useCallback((message: string | null) => {\n    setSession(null);\n    setNotice(message);\n  }, []);\n\n  useEffect(() => {\n    if (session && now >= session.expiresAt) endSession(\"Your session expired. Sign in again.\");\n  }, [now, session, endSession]);\n\n  const request = useCallback(\n    async \u003cT,>(method: HttpMethod, path: string, opts: RequestOptions = {}): Promise\u003cT> => {\n      try {\n        return await api\u003cT>(method, path, {\n          ...opts,\n          ...(sessionRef.current ? { token: sessionRef.current.token } : {}),\n        });\n      } catch (err) {\n        // One place decides what a 401 means for the whole app.\n        if (err instanceof HttpError && err.status === 401 && sessionRef.current)\n          endSession(\"Your session ended. Sign in again.\");\n        throw err;\n      }\n    },\n    [endSession],\n  );\n\n  const value = useMemo\u003cAuthApi>(\n    () => ({\n      session,\n      notice,\n      secondsLeft,\n      async signIn(username, password) {\n        const next = await api\u003cSession>(\"POST\", \"/session\", { body: { username, password } });\n        setNotice(null);\n        setSession(next);\n      },\n      async signOut() {\n        const token = sessionRef.current?.token;\n        endSession(\"You signed out.\");\n        if (token) await api(\"DELETE\", \"/session\", { token }).catch(() => undefined);\n      },\n      async extend() {\n        const renewed = await request\u003cSession>(\"POST\", \"/session/refresh\");\n        // If the person signed out while this was in flight, do not bring the session back.\n        if (sessionRef.current?.token === renewed.token) setSession(renewed);\n      },\n      request,\n    }),\n    [session, notice, secondsLeft, request, endSession],\n  );\n  return \u003cAuthContext.Provider value={value}>{children}\u003c/AuthContext.Provider>;\n}\n","src/lab/state.ts":"/* Risk store state: types, a pure reducer and selectors. */\nimport type { Risk, RiskStatus, Severity } from \"./types\";\n\nexport type SortKey = \"id\" | \"title\" | \"owner\" | \"severity\" | \"status\";\nexport interface Toast {\n  id: number;\n  kind: \"success\" | \"error\";\n  text: string;\n  retry?: () => void;\n}\nexport interface State {\n  items: readonly Risk[];\n  load: \"idle\" | \"loading\" | \"ready\" | \"error\";\n  error: string | null;\n  query: string;\n  status: RiskStatus | \"all\";\n  sort: { key: SortKey; dir: \"asc\" | \"desc\" };\n  pending: readonly string[];\n  failUpdates: boolean;\n  toasts: readonly Toast[];\n}\nexport type Action =\n  | { type: \"load/start\" }\n  | { type: \"load/ok\"; items: readonly Risk[] }\n  | { type: \"load/fail\"; message: string }\n  | { type: \"query\"; value: string }\n  | { type: \"filter\"; value: State[\"status\"] }\n  | { type: \"sort\"; key: SortKey }\n  | { type: \"update/optimistic\"; id: string; status: RiskStatus }\n  | { type: \"update/settled\"; id: string }\n  | { type: \"update/rollback\"; previous: Risk }\n  | { type: \"add\"; risk: Risk }\n  | { type: \"chaos/updates\"; on: boolean }\n  | { type: \"toast/push\"; toast: Toast }\n  | { type: \"toast/dismiss\"; id: number }\n  | { type: \"reset\" };\n\nexport const initialState: State = {\n  items: [],\n  load: \"idle\",\n  error: null,\n  query: \"\",\n  status: \"all\",\n  sort: { key: \"id\", dir: \"asc\" },\n  pending: [],\n  failUpdates: false,\n  toasts: [],\n};\n\nfunction assertNever(x: never): never {\n  throw new Error(`Unhandled action: ${JSON.stringify(x)}`); // the compiler flags any action the reducer forgets\n}\n\nexport function reducer(state: State, action: Action): State {\n  switch (action.type) {\n    case \"load/start\":\n      return { ...state, load: \"loading\", error: null };\n    case \"load/ok\":\n      return { ...state, load: \"ready\", items: action.items, error: null };\n    case \"load/fail\":\n      return { ...state, load: \"error\", error: action.message };\n    case \"query\":\n      return { ...state, query: action.value };\n    case \"filter\":\n      return { ...state, status: action.value };\n    case \"sort\":\n      return {\n        ...state,\n        sort:\n          state.sort.key === action.key\n            ? { key: action.key, dir: state.sort.dir === \"asc\" ? \"desc\" : \"asc\" }\n            : { key: action.key, dir: \"asc\" },\n      };\n    case \"update/optimistic\":\n      return {\n        ...state,\n        items: state.items.map((r) => (r.id === action.id ? { ...r, status: action.status } : r)),\n        pending: [...state.pending, action.id],\n      };\n    case \"update/settled\":\n      return { ...state, pending: state.pending.filter((id) => id !== action.id) };\n    case \"update/rollback\":\n      return {\n        ...state,\n        items: state.items.map((r) => (r.id === action.previous.id ? action.previous : r)),\n        pending: state.pending.filter((id) => id !== action.previous.id),\n      };\n    case \"add\":\n      return { ...state, items: [...state.items, action.risk] };\n    case \"chaos/updates\":\n      return { ...state, failUpdates: action.on };\n    case \"toast/push\":\n      return { ...state, toasts: [...state.toasts, action.toast] };\n    case \"toast/dismiss\":\n      return { ...state, toasts: state.toasts.filter((t) => t.id !== action.id) };\n    case \"reset\":\n      return initialState;\n    default:\n      return assertNever(action);\n  }\n}\n\nconst SEVERITY_RANK: Record\u003cSeverity, number> = { low: 1, medium: 2, high: 3 };\nconst STATUS_RANK: Record\u003cRiskStatus, number> = { open: 1, mitigating: 2, resolved: 3 };\n\nfunction compare(a: Risk, b: Risk, key: SortKey): number {\n  if (key === \"severity\") return SEVERITY_RANK[a.severity] - SEVERITY_RANK[b.severity];\n  if (key === \"status\") return STATUS_RANK[a.status] - STATUS_RANK[b.status];\n  return a[key].localeCompare(b[key], undefined, { numeric: true });\n}\nexport function selectVisible(state: State): Risk[] {\n  const q = state.query.trim().toLowerCase();\n  const rows = state.items.filter(\n    (r) =>\n      (state.status === \"all\" || r.status === state.status) &&\n      (q === \"\" || `${r.id} ${r.title} ${r.owner}`.toLowerCase().includes(q)),\n  );\n  const dir = state.sort.dir === \"asc\" ? 1 : -1;\n  return rows.sort((a, b) => dir * compare(a, b, state.sort.key));\n}\n","src/lab/store.tsx":"/* Store provider: one reducer owns the data, and every write goes through these actions. */\nimport type { ReactNode } from \"react\";\nimport { createContext, useContext, useEffect, useMemo, useReducer, useRef } from \"./react\";\nimport { useAuth } from \"./auth\";\nimport { HttpError, userMessage } from \"./errors\";\nimport { initialState, reducer } from \"./state\";\nimport type { Action, State, Toast } from \"./state\";\nimport type { NewRisk, Risk, RiskStatus } from \"./types\";\n\ninterface StoreApi {\n  state: State;\n  dispatch: (action: Action) => void;\n  reload(): Promise\u003cvoid>;\n  setStatus(id: string, status: RiskStatus): Promise\u003cvoid>;\n  create(input: NewRisk): Promise\u003cRisk>;\n}\nconst StoreContext = createContext\u003cStoreApi | null>(null);\nexport function useStore(): StoreApi {\n  const ctx = useContext(StoreContext);\n  if (!ctx) throw new Error(\"useStore must be used inside \u003cStoreProvider>\");\n  return ctx;\n}\n\nlet toastSeq = 0;\n\nexport function StoreProvider({ children }: { children: ReactNode }) {\n  const { session, request } = useAuth();\n  const [state, dispatch] = useReducer(reducer, initialState);\n  const stateRef = useRef(state);\n  stateRef.current = state;\n  // Bumped on every sign-out. An answer that arrives for an older number is ignored.\n  const epoch = useRef(0);\n\n  const actions = useMemo(() => {\n    const toast = (kind: Toast[\"kind\"], text: string, retry?: () => void): void =>\n      dispatch({\n        type: \"toast/push\",\n        toast: { id: ++toastSeq, kind, text, ...(retry ? { retry } : {}) },\n      });\n\n    async function reload(): Promise\u003cvoid> {\n      const mine = epoch.current;\n      dispatch({ type: \"load/start\" });\n      try {\n        const items = await request\u003cRisk[]>(\"GET\", \"/risks\", { retries: 2 });\n        if (mine === epoch.current) dispatch({ type: \"load/ok\", items });\n      } catch (err) {\n        if (mine !== epoch.current) return;\n        if (err instanceof HttpError && err.status === 401) return; // the auth layer already ended the session\n        dispatch({ type: \"load/fail\", message: userMessage(err) });\n      }\n    }\n\n    async function setStatus(id: string, status: RiskStatus): Promise\u003cvoid> {\n      const previous = stateRef.current.items.find((r) => r.id === id);\n      if (!previous || previous.status === status || stateRef.current.pending.includes(id)) return;\n      const mine = epoch.current;\n      dispatch({ type: \"update/optimistic\", id, status }); // show the change at once\n      try {\n        await request\u003cRisk>(\"PATCH\", `/risks/${id}`, {\n          body: { status },\n          simulateFailure: stateRef.current.failUpdates,\n        });\n        if (mine !== epoch.current) return;\n        dispatch({ type: \"update/settled\", id });\n        toast(\"success\", `${id} is now ${status}.`);\n      } catch (err) {\n        if (mine !== epoch.current) return;\n        dispatch({ type: \"update/rollback\", previous }); // put the old row back\n        toast(\"error\", `${userMessage(err)} ${id} was restored.`, () => void setStatus(id, status));\n      }\n    }\n\n    async function create(input: NewRisk): Promise\u003cRisk> {\n      const mine = epoch.current;\n      const risk = await request\u003cRisk>(\"POST\", \"/risks\", { body: input });\n      if (mine === epoch.current) dispatch({ type: \"add\", risk });\n      return risk;\n    }\n    return { reload, setStatus, create };\n  }, [request]);\n\n  const token = session?.token ?? null;\n  useEffect(() => {\n    if (token === null) {\n      epoch.current += 1;\n      dispatch({ type: \"reset\" });\n    } else if (stateRef.current.load === \"idle\") void actions.reload();\n  }, [token, actions]);\n\n  const value = useMemo\u003cStoreApi>(() => ({ state, dispatch, ...actions }), [state, actions]);\n  return \u003cStoreContext.Provider value={value}>{children}\u003c/StoreContext.Provider>;\n}\n","src/lab/hooks/useNow.ts":"/* A clock that re-renders on an interval and stops when the component goes away. */\nimport { useEffect, useState } from \"../react\";\n\nexport function useNow(intervalMs: number | null): number {\n  const [, setTick] = useState(0);\n  useEffect(() => {\n    if (intervalMs === null) return undefined;\n    const timer = window.setInterval(() => setTick((n) => n + 1), intervalMs);\n    return () => window.clearInterval(timer);\n  }, [intervalMs]);\n  // Read at render time, so the first render after the clock starts is already correct.\n  return Date.now();\n}\n","src/lab/components/LabShell.tsx":"/* The demo window: tabs, session status, and the panels. */\nimport type { KeyboardEvent } from \"react\";\nimport { useEffect, useState } from \"../react\";\nimport { useAuth } from \"../auth\";\nimport { userMessage } from \"../errors\";\nimport { clock } from \"../util\";\nimport { ErrorBoundary } from \"./ErrorBoundary\";\nimport { FailuresPanel } from \"./FailuresPanel\";\nimport { RiskLog } from \"./RiskLog\";\nimport { SessionPanel } from \"./SessionPanel\";\nimport { Toasts } from \"./Toasts\";\nimport { ValidationPanel } from \"./ValidationPanel\";\n\ntype TabId = \"session\" | \"risks\" | \"validation\" | \"failures\";\nconst TAB_LIST: ReadonlyArray\u003c{ id: TabId; label: string }> = [\n  { id: \"session\", label: \"Session\" },\n  { id: \"risks\", label: \"Risk log\" },\n  { id: \"validation\", label: \"Validation\" },\n  { id: \"failures\", label: \"Failures\" },\n];\n\nexport function LabShell() {\n  const { session, secondsLeft, extend, signOut } = useAuth();\n  const [tab, setTab] = useState\u003cTabId>(\"session\");\n  const [extendError, setExtendError] = useState\u003cstring | null>(null);\n\n  const onExtend = (): void => {\n    setExtendError(null);\n    extend().catch((err: unknown) => setExtendError(userMessage(err)));\n  };\n\n  useEffect(() => {\n    const onOpen = (e: Event): void => {\n      const id = (e as CustomEvent\u003cstring>).detail;\n      const found = TAB_LIST.find((t) => t.id === id);\n      if (found) setTab(found.id);\n    };\n    window.addEventListener(\"lab:open\", onOpen);\n    return () => window.removeEventListener(\"lab:open\", onOpen);\n  }, []);\n\n  const onKey = (e: KeyboardEvent\u003cHTMLButtonElement>, i: number): void => {\n    const to = (\n      { ArrowRight: i + 1, ArrowLeft: i - 1, Home: 0, End: TAB_LIST.length - 1 } as Record\u003c\n        string,\n        number | undefined\n      >\n    )[e.key];\n    if (to === undefined) return;\n    e.preventDefault();\n    const next = TAB_LIST[(to + TAB_LIST.length) % TAB_LIST.length];\n    if (next) {\n      setTab(next.id);\n      document.getElementById(`lab-tab-${next.id}`)?.focus();\n    }\n  };\n\n  return (\n    \u003cdiv className=\"lab-window\">\n      \u003cdiv className=\"lab-bar-top\">\n        \u003cp className=\"lab-hint\">Simulated server. No real requests are made.\u003c/p>\n        {session ? (\n          \u003cp className=\"lab-pill is-on\">\n            \u003cspan>\n              {session.user}, {session.role} role\n            \u003c/span>{\" \"}\n            \u003cspan className=\"num\">{clock(secondsLeft)}\u003c/span>{\" \"}\n            \u003cbutton type=\"button\" className=\"lab-link\" onClick={() => void signOut()}>\n              Sign out\n            \u003c/button>\n          \u003c/p>\n        ) : (\n          \u003cp className=\"lab-pill\">Signed out\u003c/p>\n        )}\n      \u003c/div>\n      {session && secondsLeft \u003c= 15 && (\n        \u003cp className=\"lab-warn\" role=\"alert\">\n          {/* The alert text stays fixed. The changing number is hidden from screen readers,\n              so they hear the warning once, not every second. */}\n          \u003cspan className=\"sr-only\">Your session is about to end.\u003c/span>\n          \u003cspan aria-hidden=\"true\">Your session ends in {secondsLeft} s.\u003c/span>{\" \"}\n          \u003cbutton type=\"button\" className=\"lab-link\" onClick={onExtend}>\n            Extend it\n          \u003c/button>{\" \"}\n          to stay signed in. {extendError}\n        \u003c/p>\n      )}\n      \u003cdiv role=\"tablist\" aria-label=\"Lab sections\" className=\"lab-tabs\">\n        {TAB_LIST.map((t, i) => (\n          \u003cbutton\n            key={t.id}\n            id={`lab-tab-${t.id}`}\n            role=\"tab\"\n            type=\"button\"\n            aria-selected={tab === t.id}\n            aria-controls={`lab-panel-${t.id}`}\n            tabIndex={tab === t.id ? 0 : -1}\n            onClick={() => setTab(t.id)}\n            onKeyDown={(e) => onKey(e, i)}\n          >\n            {t.label}\n          \u003c/button>\n        ))}\n      \u003c/div>\n      {TAB_LIST.map((t) => (\n        \u003cdiv\n          key={t.id}\n          id={`lab-panel-${t.id}`}\n          role=\"tabpanel\"\n          aria-labelledby={`lab-tab-${t.id}`}\n          hidden={tab !== t.id}\n          className=\"lab-panel\"\n        >\n          \u003cErrorBoundary label={t.label}>\n            {t.id === \"session\" && \u003cSessionPanel />}\n            {t.id === \"risks\" && \u003cRiskLog goToSession={() => setTab(\"session\")} />}\n            {t.id === \"validation\" && \u003cValidationPanel />}\n            {t.id === \"failures\" && \u003cFailuresPanel />}\n          \u003c/ErrorBoundary>\n        \u003c/div>\n      ))}\n      \u003cToasts />\n    \u003c/div>\n  );\n}\n","src/lab/components/SignInForm.tsx":"/* Sign-in form: validation, lockout countdown, and generic error messages. */\nimport type { FormEvent } from \"react\";\nimport { useEffect, useRef, useState } from \"../react\";\nimport { useAuth } from \"../auth\";\nimport { HttpError, userMessage } from \"../errors\";\nimport { useNow } from \"../hooks/useNow\";\nimport { Field } from \"./Field\";\n\nexport function SignInForm() {\n  const { signIn, notice } = useAuth();\n  const [username, setUsername] = useState(\"\");\n  const [password, setPassword] = useState(\"\");\n  const [pending, setPending] = useState(false);\n  const [error, setError] = useState\u003cstring | null>(null);\n  const [lockedUntil, setLockedUntil] = useState(0);\n  const userRef = useRef\u003cHTMLInputElement>(null);\n  const passRef = useRef\u003cHTMLInputElement>(null);\n  const now = useNow(lockedUntil > Date.now() ? 250 : null);\n  const lockLeft = Math.max(0, Math.ceil((lockedUntil - now) / 1000));\n\n  // After a sign-out or an expiry this form replaces the signed-in view, so put focus on the first field.\n  useEffect(() => {\n    if (notice) userRef.current?.focus();\n  }, []); // on mount only, so typing never pulls focus back\n\n  async function onSubmit(e: FormEvent\u003cHTMLFormElement>): Promise\u003cvoid> {\n    e.preventDefault();\n    if (!username.trim() || !password) {\n      setError(\"Enter your username and password.\");\n      (username.trim() ? passRef : userRef).current?.focus();\n      return;\n    }\n    setPending(true);\n    setError(null);\n    try {\n      await signIn(username.trim(), password);\n    } catch (err) {\n      setPassword(\"\"); // never leave a rejected password sitting in the field\n      if (err instanceof HttpError && err.status === 429)\n        setLockedUntil(Date.now() + err.retryAfterMs);\n      setError(\n        err instanceof HttpError && err.status === 401\n          ? \"Invalid username or password.\"\n          : userMessage(err),\n      );\n      passRef.current?.focus();\n    } finally {\n      setPending(false);\n    }\n  }\n\n  return (\n    \u003cform className=\"lab-form\" onSubmit={(e) => void onSubmit(e)} noValidate>\n      \u003cp className=\"lab-note\" role=\"status\">\n        {notice}\n      \u003c/p>\n      \u003cField label=\"Username\" error={undefined}>\n        {(a) => (\n          \u003cinput\n            id={a.id}\n            ref={userRef}\n            value={username}\n            onChange={(e) => setUsername(e.target.value)}\n            autoComplete=\"username\"\n            autoCapitalize=\"none\"\n            spellCheck={false}\n            maxLength={40}\n          />\n        )}\n      \u003c/Field>\n      \u003cField label=\"Password\" error={undefined}>\n        {(a) => (\n          \u003cinput\n            id={a.id}\n            ref={passRef}\n            type=\"password\"\n            value={password}\n            onChange={(e) => setPassword(e.target.value)}\n            autoComplete=\"current-password\"\n            maxLength={200}\n          />\n        )}\n      \u003c/Field>\n      \u003cdiv className=\"lab-actions\">\n        \u003cbutton\n          type=\"submit\"\n          className=\"lab-btn lab-btn-primary\"\n          disabled={pending || lockLeft > 0}\n        >\n          {pending ? \"Signing in...\" : lockLeft > 0 ? `Locked for ${lockLeft} s` : \"Sign in\"}\n        \u003c/button>\n        \u003cspan className=\"lab-hint\">Demo accounts, made up for this page:\u003c/span>\n        \u003cbutton\n          type=\"button\"\n          className=\"lab-btn lab-btn-small\"\n          onClick={() => {\n            setUsername(\"analyst\");\n            setPassword(\"Analyst#2026\");\n          }}\n        >\n          Use the viewer account\n        \u003c/button>\n        \u003cbutton\n          type=\"button\"\n          className=\"lab-btn lab-btn-small\"\n          onClick={() => {\n            setUsername(\"lead\");\n            setPassword(\"Lead#2026\");\n          }}\n        >\n          Use the admin account\n        \u003c/button>\n      \u003c/div>\n      \u003cp className=\"lab-error\" role=\"alert\">\n        {error}\n      \u003c/p>\n      \u003cp className=\"lab-hint\">\n        Try a wrong password three times to see the lockout. The server gives the same answer for a\n        wrong name and a wrong password.\n      \u003c/p>\n    \u003c/form>\n  );\n}\n","src/lab/components/SessionPanel.tsx":"/* Signed-in view: who you are, what you may do, and how long the session has left. */\nimport { useEffect, useRef, useState } from \"../react\";\nimport { useAuth } from \"../auth\";\nimport { SESSION_SECONDS } from \"../config\";\nimport { userMessage } from \"../errors\";\nimport { PERMISSIONS } from \"../permissions\";\nimport { clock } from \"../util\";\nimport { SignInForm } from \"./SignInForm\";\n\nexport function SessionPanel() {\n  const { session, secondsLeft, signOut, extend } = useAuth();\n  const [busy, setBusy] = useState(false);\n  const [extendError, setExtendError] = useState\u003cstring | null>(null);\n  const panel = useRef\u003cHTMLDivElement>(null);\n  const signedIn = session !== null;\n\n  // Signing in replaces the form that had focus, so move focus to the new content.\n  useEffect(() => {\n    if (signedIn) panel.current?.focus();\n  }, [signedIn]);\n\n  if (!session) return \u003cSignInForm />;\n  const pct = Math.min(100, (secondsLeft / SESSION_SECONDS) * 100);\n\n  function onExtend(): void {\n    setBusy(true);\n    setExtendError(null);\n    extend()\n      .catch((err: unknown) => setExtendError(userMessage(err)))\n      .finally(() => setBusy(false));\n  }\n\n  return (\n    \u003cdiv className=\"lab-session\" ref={panel} tabIndex={-1} aria-label=\"Session details\">\n      \u003cdl className=\"lab-dl\">\n        \u003cdiv>\n          \u003cdt>Signed in as\u003c/dt>\n          \u003cdd>{session.user}\u003c/dd>\n        \u003c/div>\n        \u003cdiv>\n          \u003cdt>Role\u003c/dt>\n          \u003cdd>{session.role}\u003c/dd>\n        \u003c/div>\n        \u003cdiv>\n          \u003cdt>Permissions\u003c/dt>\n          \u003cdd>{PERMISSIONS[session.role].join(\", \")}\u003c/dd>\n        \u003c/div>\n        \u003cdiv>\n          \u003cdt>Session token\u003c/dt>\n          \u003cdd>\n            \u003ccode>\n              {session.token.slice(0, 6)}...{session.token.slice(-4)}\n            \u003c/code>{\" \"}\n            \u003cspan className=\"lab-hint\">kept in memory only, gone on reload\u003c/span>\n          \u003c/dd>\n        \u003c/div>\n        \u003cdiv>\n          \u003cdt>Expires in\u003c/dt>\n          \u003cdd className=\"num\">{clock(secondsLeft)}\u003c/dd>\n        \u003c/div>\n      \u003c/dl>\n      \u003cdiv className=\"lab-bar\" role=\"presentation\">\n        \u003cspan style={{ width: `${pct}%` }} />\n      \u003c/div>\n      \u003cdiv className=\"lab-actions\">\n        \u003cbutton\n          type=\"button\"\n          className=\"lab-btn lab-btn-primary\"\n          disabled={busy}\n          onClick={onExtend}\n        >\n          Extend session\n        \u003c/button>\n        \u003cbutton type=\"button\" className=\"lab-btn\" onClick={() => void signOut()}>\n          Sign out\n        \u003c/button>\n      \u003c/div>\n      \u003cp className=\"lab-error\" role=\"alert\">\n        {extendError}\n      \u003c/p>\n    \u003c/div>\n  );\n}\n","src/lab/components/RiskLog.tsx":"/* Risk log: state, permissions and a table that becomes cards in a narrow container. */\nimport { useCallback, useMemo, useState } from \"../react\";\nimport { useAuth } from \"../auth\";\nimport { HttpError, userMessage } from \"../errors\";\nimport { can } from \"../permissions\";\nimport { selectVisible } from \"../state\";\nimport type { SortKey, State } from \"../state\";\nimport { useStore } from \"../store\";\nimport { STATUSES } from \"../types\";\nimport type { RiskStatus } from \"../types\";\nimport { RiskRow } from \"./RiskRow\";\n\nconst COLUMNS: ReadonlyArray\u003c{ key: SortKey; label: string }> = [\n  { key: \"id\", label: \"ID\" },\n  { key: \"title\", label: \"Risk\" },\n  { key: \"owner\", label: \"Owner\" },\n  { key: \"severity\", label: \"Severity\" },\n  { key: \"status\", label: \"Status\" },\n];\n\nexport function RiskLog({ goToSession }: { goToSession: () => void }) {\n  const { session, request } = useAuth();\n  const { state, dispatch, reload, setStatus } = useStore();\n  const visible = useMemo(() => selectVisible(state), [state]);\n  const onStatus = useCallback(\n    (id: string, status: RiskStatus) => void setStatus(id, status),\n    [setStatus],\n  );\n  const [bypass, setBypass] = useState\u003cstring | null>(null);\n\n  if (!session) {\n    return (\n      \u003cdiv className=\"lab-empty\">\n        \u003cp>The risk log needs a session. Sign in first, then come back.\u003c/p>\n        \u003cbutton type=\"button\" className=\"lab-btn lab-btn-primary\" onClick={goToSession}>\n          Go to sign in\n        \u003c/button>\n      \u003c/div>\n    );\n  }\n  const canUpdate = can(session.role, \"risk:update\");\n\n  async function sendAnyway(): Promise\u003cvoid> {\n    try {\n      await request(\"PATCH\", \"/risks/R-101\", { body: { status: \"resolved\" } });\n      setBypass(\"The server accepted it.\");\n    } catch (err) {\n      setBypass(\n        `Server answered ${err instanceof HttpError ? err.status : \"an error\"}: ${userMessage(err)}`,\n      );\n    }\n  }\n\n  return (\n    \u003cdiv className=\"lab-risks\">\n      \u003cdiv className=\"lab-toolbar\">\n        \u003cinput\n          type=\"search\"\n          aria-label=\"Search risks\"\n          placeholder=\"Search risks\"\n          value={state.query}\n          onChange={(e) => dispatch({ type: \"query\", value: e.target.value })}\n        />\n        \u003cselect\n          aria-label=\"Filter by status\"\n          value={state.status}\n          onChange={(e) => dispatch({ type: \"filter\", value: e.target.value as State[\"status\"] })}\n        >\n          \u003coption value=\"all\">All statuses\u003c/option>\n          {STATUSES.map((s) => (\n            \u003coption key={s} value={s}>\n              {s}\n            \u003c/option>\n          ))}\n        \u003c/select>\n        \u003cbutton\n          type=\"button\"\n          className=\"lab-btn lab-btn-small\"\n          onClick={() => void reload()}\n          disabled={state.load === \"loading\"}\n        >\n          Reload\n        \u003c/button>\n        {canUpdate ? (\n          \u003clabel className=\"lab-check\">\n            \u003cinput\n              type=\"checkbox\"\n              checked={state.failUpdates}\n              onChange={(e) => dispatch({ type: \"chaos/updates\", on: e.target.checked })}\n            />\n            Make updates fail\n          \u003c/label>\n        ) : (\n          \u003cbutton type=\"button\" className=\"lab-btn lab-btn-small\" onClick={() => void sendAnyway()}>\n            Send an update anyway\n          \u003c/button>\n        )}\n      \u003c/div>\n      {!canUpdate && (\n        \u003cp className=\"lab-note\" role=\"status\">\n          You are signed in as a viewer, so the buttons are off.{\" \"}\n          {bypass ?? \"Press the button above to skip the UI and ask the server directly.\"}\n        \u003c/p>\n      )}\n      \u003cp className=\"lab-hint\" role=\"status\">\n        {state.load === \"loading\" ? \"Loading risks...\" : \"\"}\n      \u003c/p>\n      \u003cp className=\"lab-error\" role=\"alert\">\n        {state.load === \"error\" && (\n          \u003c>\n            {state.error}{\" \"}\n            \u003cbutton type=\"button\" className=\"lab-btn lab-btn-small\" onClick={() => void reload()}>\n              Retry\n            \u003c/button>\n          \u003c/>\n        )}\n      \u003c/p>\n      \u003cp className=\"lab-hint\">\n        Drag the bottom-right corner of the table to resize it. Below 40rem it turns into cards.\n      \u003c/p>\n      \u003cdiv className=\"lab-resize\">\n        \u003ctable className=\"lab-table\">\n          \u003ccaption className=\"sr-only\">Program risks\u003c/caption>\n          \u003cthead>\n            \u003ctr>\n              {COLUMNS.map((c) => (\n                \u003cth\n                  key={c.key}\n                  scope=\"col\"\n                  aria-sort={\n                    state.sort.key === c.key\n                      ? state.sort.dir === \"asc\"\n                        ? \"ascending\"\n                        : \"descending\"\n                      : \"none\"\n                  }\n                >\n                  \u003cbutton type=\"button\" onClick={() => dispatch({ type: \"sort\", key: c.key })}>\n                    {c.label}\n                  \u003c/button>\n                \u003c/th>\n              ))}\n              \u003cth scope=\"col\">\n                \u003cspan className=\"sr-only\">Action\u003c/span>\n              \u003c/th>\n            \u003c/tr>\n          \u003c/thead>\n          \u003ctbody>\n            {visible.map((risk) => (\n              \u003cRiskRow\n                key={risk.id}\n                risk={risk}\n                canUpdate={canUpdate}\n                pending={state.pending.includes(risk.id)}\n                onStatus={onStatus}\n              />\n            ))}\n            {visible.length === 0 && state.load === \"ready\" && (\n              \u003ctr>\n                \u003ctd colSpan={6} className=\"lab-none\">\n                  No risks match. Clear the search or change the filter.\n                \u003c/td>\n              \u003c/tr>\n            )}\n          \u003c/tbody>\n        \u003c/table>\n      \u003c/div>\n      \u003cdetails className=\"lab-state\">\n        \u003csummary>Live state\u003c/summary>\n        \u003cpre>\n          {JSON.stringify(\n            {\n              load: state.load,\n              query: state.query,\n              status: state.status,\n              sort: state.sort,\n              pending: state.pending,\n              failUpdates: state.failUpdates,\n              rows: `${visible.length} of ${state.items.length}`,\n            },\n            null,\n            2,\n          )}\n        \u003c/pre>\n      \u003c/details>\n    \u003c/div>\n  );\n}\n","src/lab/components/RiskRow.tsx":"/* One table row. Memoized, so the list does not re-render rows whose data has not changed. */\nimport { memo } from \"../react\";\nimport { isHttpsUrl } from \"../validation\";\nimport type { Risk, RiskStatus } from \"../types\";\n\ninterface RowProps {\n  risk: Risk;\n  canUpdate: boolean;\n  pending: boolean;\n  onStatus: (id: string, status: RiskStatus) => void;\n}\nexport const RiskRow = memo(function RiskRow({ risk, canUpdate, pending, onStatus }: RowProps) {\n  const next: RiskStatus = risk.status === \"resolved\" ? \"open\" : \"resolved\";\n  const action = risk.status === \"resolved\" ? \"Reopen\" : \"Resolve\";\n  return (\n    \u003ctr className={pending ? \"is-pending\" : undefined} aria-busy={pending}>\n      \u003ctd data-label=\"ID\">{risk.id}\u003c/td>\n      \u003ctd data-label=\"Risk\">\n        {risk.title}\n        {/* Checked again on the way out, not only on the way in. */}\n        {risk.reference && isHttpsUrl(risk.reference) && (\n          \u003c>\n            {\" \"}\n            \u003ca href={risk.reference} target=\"_blank\" rel=\"noopener noreferrer\">\n              Reference\n            \u003c/a>\n          \u003c/>\n        )}\n        {/* React escapes this text, so a description can never become markup. */}\n        {risk.description && \u003cspan className=\"lab-desc\">{risk.description}\u003c/span>}\n      \u003c/td>\n      \u003ctd data-label=\"Owner\">{risk.owner}\u003c/td>\n      \u003ctd data-label=\"Severity\">\n        \u003cspan className={`lab-badge sev-${risk.severity}`}>{risk.severity}\u003c/span>\n      \u003c/td>\n      \u003ctd data-label=\"Status\">\n        \u003cspan className={`lab-badge st-${risk.status}`}>{risk.status}\u003c/span>\n      \u003c/td>\n      \u003ctd data-label=\"Action\">\n        \u003cbutton\n          type=\"button\"\n          className=\"lab-btn lab-btn-small\"\n          disabled={!canUpdate}\n          aria-disabled={pending || undefined}\n          aria-label={`${action} ${risk.id}`}\n          onClick={() => {\n            if (!pending) onStatus(risk.id, next); // aria-disabled keeps focus on the button, so the click is ignored here\n          }}\n        >\n          {action}\n        \u003c/button>\n      \u003c/td>\n    \u003c/tr>\n  );\n});\n","src/lab/components/NewRiskForm.tsx":"/* New risk form: validates on blur and on submit, focuses the first problem,\n   and shows server errors on the fields. */\nimport type { ChangeEvent, FormEvent } from \"react\";\nimport { useEffect, useMemo, useRef, useState } from \"../react\";\nimport { useAuth } from \"../auth\";\nimport { HttpError, userMessage } from \"../errors\";\nimport { useStore } from \"../store\";\nimport { SEVERITIES } from \"../types\";\nimport type { Fields } from \"../types\";\nimport { parseNewRisk } from \"../validation\";\nimport { Field } from \"./Field\";\n\ninterface FormValues {\n  title: string;\n  owner: string;\n  severity: string;\n  reference: string;\n  description: string;\n}\ntype FieldName = keyof FormValues;\nconst EMPTY: FormValues = {\n  title: \"\",\n  owner: \"\",\n  severity: \"medium\",\n  reference: \"\",\n  description: \"\",\n};\nconst FIELD_ORDER: readonly FieldName[] = [\n  \"title\",\n  \"owner\",\n  \"severity\",\n  \"reference\",\n  \"description\",\n];\n\nexport function NewRiskForm() {\n  const { session, request } = useAuth();\n  const { create } = useStore();\n  const [values, setValues] = useState\u003cFormValues>(EMPTY);\n  const [touched, setTouched] = useState\u003cPartial\u003cRecord\u003cFieldName, boolean>>>({});\n  const [submitted, setSubmitted] = useState(false);\n  const [serverErrors, setServerErrors] = useState\u003cFields>({});\n  const [banner, setBanner] = useState\u003c{ kind: \"ok\" | \"err\"; text: string } | null>(null);\n  const [pending, setPending] = useState(false);\n  const [forged, setForged] = useState\u003cstring | null>(null);\n  const [focusField, setFocusField] = useState\u003cFieldName | null>(null);\n  const refs = useRef\u003cPartial\u003cRecord\u003cFieldName, HTMLElement | null>>>({});\n\n  const parsed = useMemo(() => parseNewRisk(values), [values]);\n  const clientErrors: Fields = parsed.ok ? {} : parsed.errors;\n  const errorFor = (f: FieldName): string | undefined =>\n    (touched[f] || submitted ? clientErrors[f] : undefined) ?? serverErrors[f];\n\n  const change =\n    (f: FieldName) =>\n    (e: ChangeEvent\u003cHTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>): void => {\n      setValues((v) => ({ ...v, [f]: e.target.value }));\n      setServerErrors((s) => {\n        const { [f]: _gone, ...rest } = s;\n        return rest;\n      });\n    };\n  const blur = (f: FieldName) => (): void => setTouched((t) => ({ ...t, [f]: true }));\n  // Focus moves in an effect, after React has drawn aria-invalid and the error text,\n  // so a screen reader reads the problem as it lands on the field.\n  useEffect(() => {\n    if (focusField === null) return;\n    refs.current[focusField]?.focus();\n    setFocusField(null);\n  }, [focusField]);\n  const focusFirst = (errors: Fields): void => {\n    setFocusField(FIELD_ORDER.find((f) => errors[f]) ?? null); // send people straight to the problem\n  };\n\n  async function onSubmit(e: FormEvent\u003cHTMLFormElement>): Promise\u003cvoid> {\n    e.preventDefault();\n    setSubmitted(true);\n    setBanner(null);\n    if (!parsed.ok) {\n      focusFirst(parsed.errors);\n      const count = Object.keys(parsed.errors).length;\n      setBanner({\n        kind: \"err\",\n        text: `Fix ${count} ${count === 1 ? \"field\" : \"fields\"} and try again.`,\n      });\n      return;\n    }\n    if (!session) {\n      setBanner({\n        kind: \"err\",\n        text: \"Sign in first. The server rejects requests that have no session.\",\n      });\n      return;\n    }\n    setPending(true);\n    try {\n      const risk = await create(parsed.value);\n      setValues(EMPTY);\n      setTouched({});\n      setSubmitted(false);\n      setBanner({ kind: \"ok\", text: `${risk.id} created. It is now in the Risk log.` });\n    } catch (err) {\n      if (err instanceof HttpError && err.status === 422) {\n        setServerErrors(err.fields);\n        focusFirst(err.fields);\n      }\n      setBanner({ kind: \"err\", text: userMessage(err) });\n    } finally {\n      setPending(false);\n    }\n  }\n\n  async function forge(): Promise\u003cvoid> {\n    try {\n      await request(\"POST\", \"/risks\", {\n        body: {\n          title: \"x\",\n          owner: \"not-an-email\",\n          severity: \"critical\",\n          reference: \"javascript:alert(1)\",\n        },\n      });\n      setForged(\"The server accepted it.\");\n    } catch (err) {\n      setForged(\n        err instanceof HttpError && err.status === 422\n          ? `HTTP 422\\n${Object.entries(err.fields)\n              .map(([k, v]) => `${k}: ${v}`)\n              .join(\"\\n\")}`\n          : userMessage(err),\n      );\n    }\n  }\n\n  return (\n    \u003cdiv className=\"lab-card\">\n      \u003ch3>New risk\u003c/h3>\n      \u003cform className=\"lab-form\" onSubmit={(e) => void onSubmit(e)} noValidate>\n        {/* maxLength is looser than the 80-character rule on purpose, so the rule's message can be seen. */}\n        \u003cField label=\"Title\" error={errorFor(\"title\")}>\n          {(a) => (\n            \u003cinput\n              id={a.id}\n              ref={(el) => {\n                refs.current.title = el;\n              }}\n              value={values.title}\n              onChange={change(\"title\")}\n              onBlur={blur(\"title\")}\n              aria-invalid={a.invalid}\n              aria-describedby={a.describedBy}\n              maxLength={120}\n              autoComplete=\"off\"\n            />\n          )}\n        \u003c/Field>\n        \u003cField label=\"Owner email\" error={errorFor(\"owner\")}>\n          {(a) => (\n            \u003cinput\n              id={a.id}\n              ref={(el) => {\n                refs.current.owner = el;\n              }}\n              type=\"email\"\n              value={values.owner}\n              onChange={change(\"owner\")}\n              onBlur={blur(\"owner\")}\n              aria-invalid={a.invalid}\n              aria-describedby={a.describedBy}\n              autoComplete=\"off\"\n            />\n          )}\n        \u003c/Field>\n        \u003cField label=\"Severity\" error={errorFor(\"severity\")}>\n          {(a) => (\n            \u003cselect\n              id={a.id}\n              ref={(el) => {\n                refs.current.severity = el;\n              }}\n              value={values.severity}\n              onChange={change(\"severity\")}\n              onBlur={blur(\"severity\")}\n              aria-invalid={a.invalid}\n              aria-describedby={a.describedBy}\n            >\n              {SEVERITIES.map((s) => (\n                \u003coption key={s} value={s}>\n                  {s}\n                \u003c/option>\n              ))}\n            \u003c/select>\n          )}\n        \u003c/Field>\n        \u003cField\n          label=\"Reference link (optional)\"\n          hint=\"https only. Links starting with javascript: or data: are refused.\"\n          error={errorFor(\"reference\")}\n        >\n          {(a) => (\n            \u003cinput\n              id={a.id}\n              ref={(el) => {\n                refs.current.reference = el;\n              }}\n              value={values.reference}\n              onChange={change(\"reference\")}\n              onBlur={blur(\"reference\")}\n              aria-invalid={a.invalid}\n              aria-describedby={a.describedBy}\n              inputMode=\"url\"\n              autoComplete=\"off\"\n            />\n          )}\n        \u003c/Field>\n        \u003cField\n          label=\"Description (optional)\"\n          hint={`${values.description.length} of 280 characters`}\n          error={errorFor(\"description\")}\n        >\n          {(a) => (\n            \u003ctextarea\n              id={a.id}\n              ref={(el) => {\n                refs.current.description = el;\n              }}\n              value={values.description}\n              onChange={change(\"description\")}\n              onBlur={blur(\"description\")}\n              aria-invalid={a.invalid}\n              aria-describedby={a.describedBy}\n              rows={3}\n            />\n          )}\n        \u003c/Field>\n        \u003cdiv className=\"lab-actions\">\n          \u003cbutton type=\"submit\" className=\"lab-btn lab-btn-primary\" disabled={pending}>\n            {pending ? \"Creating...\" : \"Create risk\"}\n          \u003c/button>\n        \u003c/div>\n        \u003cp className={banner?.kind === \"ok\" ? \"lab-ok\" : \"lab-error\"} role=\"alert\">\n          {banner?.text}\n        \u003c/p>\n      \u003c/form>\n      \u003cdiv className=\"lab-forge\">\n        \u003cp className=\"lab-hint\">\n          Client checks are for convenience. The server checks everything again, so skip the form\n          and send bad data straight to it:\n        \u003c/p>\n        \u003cbutton type=\"button\" className=\"lab-btn lab-btn-small\" onClick={() => void forge()}>\n          Send a forged request\n        \u003c/button>\n        \u003cdiv aria-live=\"polite\">{forged && \u003cpre className=\"lab-pre\">{forged}\u003c/pre>}\u003c/div>\n      \u003c/div>\n    \u003c/div>\n  );\n}\n","src/lab/components/PasswordMeter.tsx":"/* Password strength: the checklist, the meter and the label all come from one list of rules. */\nimport { useId, useState } from \"../react\";\nimport { passwordChecks } from \"../validation\";\n\nexport function PasswordMeter() {\n  const [pw, setPw] = useState(\"\");\n  const [show, setShow] = useState(false);\n  const id = useId();\n  const checks = passwordChecks(pw);\n  const score = checks.filter((c) => c.ok).length;\n  const label = pw === \"\" ? \"Not entered\" : score \u003c= 2 ? \"Weak\" : score \u003c 5 ? \"Fair\" : \"Strong\";\n  return (\n    \u003cdiv className=\"lab-card\">\n      \u003ch3>Password strength\u003c/h3>\n      \u003cdiv className=\"lab-field\">\n        \u003clabel htmlFor={id}>New password\u003c/label>\n        \u003cdiv className=\"lab-inline\">\n          \u003cinput\n            id={id}\n            type={show ? \"text\" : \"password\"}\n            value={pw}\n            onChange={(e) => setPw(e.target.value)}\n            autoComplete=\"new-password\"\n            maxLength={200}\n            aria-describedby={`${id}-rules`}\n          />\n          \u003cbutton\n            type=\"button\"\n            className=\"lab-btn lab-btn-small\"\n            onClick={() => setShow((s) => !s)}\n          >\n            {show ? \"Hide\" : \"Show\"}\n          \u003c/button>\n        \u003c/div>\n      \u003c/div>\n      \u003cdiv\n        className=\"lab-meter\"\n        role=\"meter\"\n        aria-label=\"Password strength\"\n        aria-valuemin={0}\n        aria-valuemax={5}\n        aria-valuenow={score}\n        aria-valuetext={label}\n        data-level={label.toLowerCase().replace(\" \", \"-\")}\n      >\n        \u003cspan style={{ width: `${(score / 5) * 100}%` }} />\n      \u003c/div>\n      \u003cp className=\"lab-hint\" aria-live=\"polite\">\n        Strength: {label}\n      \u003c/p>\n      \u003cul id={`${id}-rules`} className=\"lab-rules\">\n        {checks.map((c) => (\n          \u003cli key={c.label} data-ok={c.ok}>\n            \u003cspan className=\"sr-only\">{c.ok ? \"Met: \" : \"Not met: \"}\u003c/span>\n            {c.label}\n          \u003c/li>\n        ))}\n      \u003c/ul>\n    \u003c/div>\n  );\n}\n","src/lab/components/SanitizerDemo.tsx":"/* Untrusted text: the same input shown escaped, sanitized, and as sanitized HTML. */\nimport { useEffect, useId, useMemo, useRef, useState } from \"../react\";\nimport { sanitize } from \"../sanitize\";\n\nconst SAMPLE =\n  'Quarterly note: \u003cb>on track\u003c/b>. \u003cimg src=x onerror=\"alert(1)\"> \u003cscript>alert(1)\u003c/script> \u003ca href=\"javascript:alert(1)\">bad link\u003c/a> and \u003ca href=\"https://example.com/report\">a safe link\u003c/a>.';\n\nexport function SanitizerDemo() {\n  const [text, setText] = useState(SAMPLE);\n  const preview = useRef\u003cHTMLDivElement>(null);\n  const id = useId();\n  const clean = useMemo(() => sanitize(text), [text]);\n  const source = useMemo(() => {\n    const holder = document.createElement(\"div\");\n    holder.appendChild(clean.fragment.cloneNode(true));\n    return holder.innerHTML; // only serializes; shown as text below\n  }, [clean]);\n  useEffect(() => {\n    preview.current?.replaceChildren(clean.fragment.cloneNode(true));\n  }, [clean]);\n  return (\n    \u003cdiv className=\"lab-card lab-wide\">\n      \u003ch3>Untrusted text\u003c/h3>\n      \u003cdiv className=\"lab-field\">\n        \u003clabel htmlFor={id}>Paste anything, including markup\u003c/label>\n        \u003ctextarea\n          id={id}\n          rows={3}\n          maxLength={2000}\n          value={text}\n          onChange={(e) => setText(e.target.value)}\n        />\n      \u003c/div>\n      \u003cdiv className=\"lab-outputs\">\n        \u003cdiv>\n          \u003ch4>As plain text\u003c/h4>\n          \u003cp className=\"lab-out\">{text}\u003c/p>\n          \u003cp className=\"lab-hint\">React escapes this by default.\u003c/p>\n        \u003c/div>\n        \u003cdiv>\n          \u003ch4>After the sanitizer\u003c/h4>\n          \u003cdiv className=\"lab-out\" ref={preview} />\n          \u003cp className=\"lab-hint\">\n            {clean.blocked.length\n              ? `Blocked: ${clean.blocked.join(\", \")}.`\n              : \"Nothing needed blocking.\"}\n          \u003c/p>\n        \u003c/div>\n        \u003cdiv>\n          \u003ch4>Sanitized HTML\u003c/h4>\n          \u003cpre className=\"lab-pre\">{source}\u003c/pre>\n        \u003c/div>\n      \u003c/div>\n    \u003c/div>\n  );\n}\n","src/lab/components/ValidationPanel.tsx":"/* The Validation tab: the form, the password meter and the sanitizer side by side. */\nimport { NewRiskForm } from \"./NewRiskForm\";\nimport { PasswordMeter } from \"./PasswordMeter\";\nimport { SanitizerDemo } from \"./SanitizerDemo\";\n\nexport function ValidationPanel() {\n  return (\n    \u003cdiv className=\"lab-grid\">\n      \u003cNewRiskForm />\n      \u003cPasswordMeter />\n      \u003cSanitizerDemo />\n    \u003c/div>\n  );\n}\n","src/lab/components/FailuresPanel.tsx":"/* Failure modes: break the network on purpose and watch the client recover. */\nimport { useState } from \"../react\";\nimport { useAuth } from \"../auth\";\nimport { testControls } from \"../api\";\nimport type { AttemptLog } from \"../api\";\nimport { userMessage } from \"../errors\";\nimport { CrashDemo } from \"./CrashDemo\";\n\ntype ScenarioId = \"flaky\" | \"slow\" | \"down\" | \"expired\";\nconst SCENARIOS: ReadonlyArray\u003c{ id: ScenarioId; title: string; detail: string }> = [\n  {\n    id: \"flaky\",\n    title: \"Server errors, then recovery\",\n    detail:\n      \"The first two attempts return 503. The client waits, retries, and the third attempt succeeds.\",\n  },\n  {\n    id: \"slow\",\n    title: \"Timeout, then recovery\",\n    detail: \"The first attempt stalls past the 1.5 s limit. The client aborts it and tries again.\",\n  },\n  {\n    id: \"down\",\n    title: \"Network down\",\n    detail: \"Every attempt fails. The client stops after three tries and shows one plain message.\",\n  },\n  {\n    id: \"expired\",\n    title: \"Session revoked\",\n    detail:\n      \"The server forgets your session. The next request returns 401 and the app signs you out cleanly.\",\n  },\n];\n\nexport function FailuresPanel() {\n  const { session, request } = useAuth();\n  const [running, setRunning] = useState\u003cScenarioId | null>(null);\n  const [log, setLog] = useState\u003creadonly AttemptLog[]>([]);\n  const [outcome, setOutcome] = useState\u003c{ kind: \"ok\" | \"err\" | \"info\"; text: string } | null>(\n    null,\n  );\n\n  async function run(id: ScenarioId): Promise\u003cvoid> {\n    setRunning(id);\n    setLog([]);\n    setOutcome(null);\n    const onAttempt = (a: AttemptLog): void => setLog((l) => [...l, a]);\n    try {\n      if (id === \"expired\") {\n        if (!session) {\n          setOutcome({\n            kind: \"info\",\n            text: \"Sign in on the Session tab first, so there is a session to revoke.\",\n          });\n          return;\n        }\n        testControls.revokeSessions();\n        await request(\"GET\", \"/risks\", { onAttempt });\n      } else {\n        testControls.arm(id);\n        await request(\"GET\", \"/status\", { retries: 2, timeoutMs: 1500, onAttempt });\n        setOutcome({ kind: \"ok\", text: \"Recovered. The request succeeded after retrying.\" });\n      }\n    } catch (err) {\n      setOutcome({ kind: \"err\", text: userMessage(err) });\n    } finally {\n      testControls.arm(\"none\");\n      setRunning(null);\n    }\n  }\n\n  return (\n    \u003cdiv className=\"lab-grid\">\n      \u003cdiv className=\"lab-card lab-wide\">\n        \u003ch3>Break the network\u003c/h3>\n        \u003cul className=\"lab-scenarios\">\n          {SCENARIOS.map((s) => (\n            \u003cli key={s.id}>\n              \u003cdiv>\n                \u003cstrong>{s.title}\u003c/strong>\n                \u003cp className=\"lab-hint\">{s.detail}\u003c/p>\n              \u003c/div>\n              \u003cbutton\n                type=\"button\"\n                className=\"lab-btn lab-btn-small\"\n                disabled={running !== null}\n                onClick={() => void run(s.id)}\n              >\n                {running === s.id ? \"Running...\" : \"Run\"}\n              \u003c/button>\n            \u003c/li>\n          ))}\n        \u003c/ul>\n        \u003col className=\"lab-log\" aria-live=\"polite\">\n          {log.map((a) => (\n            \u003cli key={a.n} data-outcome={a.outcome}>\n              Attempt {a.n}: {a.detail}\n            \u003c/li>\n          ))}\n        \u003c/ol>\n        \u003cp\n          className={\n            outcome?.kind === \"ok\" ? \"lab-ok\" : outcome?.kind === \"err\" ? \"lab-error\" : \"lab-note\"\n          }\n          role=\"status\"\n        >\n          {outcome?.text}\n        \u003c/p>\n        \u003cp className=\"lab-hint\">\n          Only reads (GET requests) are retried automatically. Writes are not, so a click never\n          writes twice.\n        \u003c/p>\n      \u003c/div>\n      \u003cdiv className=\"lab-card\">\n        \u003ch3>Contain a crash\u003c/h3>\n        \u003cp className=\"lab-hint\">\n          An error boundary isolates a component that throws while rendering.\n        \u003c/p>\n        \u003cCrashDemo />\n      \u003c/div>\n    \u003c/div>\n  );\n}\n","src/lab/components/CrashDemo.tsx":"/* A component that throws on demand, to show the error boundary containing it. */\nimport { useState } from \"../react\";\nimport { ErrorBoundary } from \"./ErrorBoundary\";\n\nfunction Bomb({ armed }: { armed: boolean }) {\n  if (armed) throw new Error(\"Rendering failed on purpose\");\n  return \u003cp>This component is healthy.\u003c/p>;\n}\nexport function CrashDemo() {\n  const [armed, setArmed] = useState(false);\n  return (\n    \u003cErrorBoundary label=\"This component\" onReset={() => setArmed(false)}>\n      \u003cBomb armed={armed} />\n      \u003cbutton type=\"button\" className=\"lab-btn lab-btn-small\" onClick={() => setArmed(true)}>\n        Crash this component\n      \u003c/button>\n    \u003c/ErrorBoundary>\n  );\n}\n","src/lab/components/Toasts.tsx":"/* Toasts: success messages clear themselves, errors stay until dismissed. */\nimport { useEffect, useRef } from \"../react\";\nimport { useStore } from \"../store\";\n\nconst SUCCESS_MS = 4000;\n\nexport function Toasts() {\n  const { state, dispatch } = useStore();\n  const timers = useRef(new Map\u003cnumber, number>());\n\n  useEffect(() => {\n    const live = new Set(state.toasts.map((t) => t.id));\n    state.toasts.forEach((t) => {\n      if (t.kind === \"error\" || timers.current.has(t.id)) return;\n      const timer = window.setTimeout(\n        () => dispatch({ type: \"toast/dismiss\", id: t.id }),\n        SUCCESS_MS,\n      );\n      timers.current.set(t.id, timer);\n    });\n    timers.current.forEach((timer, id) => {\n      if (live.has(id)) return;\n      window.clearTimeout(timer); // the toast is gone, so its timer is not needed\n      timers.current.delete(id);\n    });\n  }, [state.toasts, dispatch]);\n\n  // Stop every pending timer when the component goes away.\n  useEffect(() => {\n    const pending = timers.current;\n    return () => {\n      pending.forEach((timer) => window.clearTimeout(timer));\n      pending.clear();\n    };\n  }, []);\n\n  return (\n    \u003cdiv className=\"lab-toasts\" role=\"status\" aria-live=\"polite\">\n      {state.toasts.map((t) => (\n        \u003cdiv key={t.id} className={`lab-toast is-${t.kind}`}>\n          \u003cspan>{t.text}\u003c/span>\n          {t.retry && (\n            \u003cbutton\n              type=\"button\"\n              className=\"lab-btn lab-btn-small\"\n              onClick={() => {\n                t.retry?.();\n                dispatch({ type: \"toast/dismiss\", id: t.id });\n              }}\n            >\n              Retry\n            \u003c/button>\n          )}\n          \u003cbutton\n            type=\"button\"\n            className=\"lab-btn lab-btn-small\"\n            onClick={() => dispatch({ type: \"toast/dismiss\", id: t.id })}\n          >\n            Dismiss\n          \u003c/button>\n        \u003c/div>\n      ))}\n    \u003c/div>\n  );\n}\n","src/lab/components/ErrorBoundary.tsx":"/* Error boundary: a render crash stays inside its panel. */\nimport type { ErrorInfo, ReactNode } from \"react\";\nimport { Component } from \"../react\";\n\ninterface BoundaryProps {\n  label: string;\n  children: ReactNode;\n  onReset?: () => void;\n}\nexport class ErrorBoundary extends Component\u003cBoundaryProps, { error: Error | null }> {\n  override state = { error: null as Error | null };\n  static getDerivedStateFromError(error: Error): { error: Error } {\n    return { error };\n  }\n  override componentDidCatch(error: Error, info: ErrorInfo): void {\n    console.error(`[${this.props.label}]`, error.message, info.componentStack); // a real app reports this to monitoring\n  }\n  override render(): ReactNode {\n    if (this.state.error) {\n      return (\n        \u003cdiv className=\"lab-crash\" role=\"alert\">\n          \u003cp>\n            \u003cstrong>{this.props.label} hit an error.\u003c/strong> It was contained here, and the rest of\n            the app is still running.\n          \u003c/p>\n          \u003cp className=\"lab-hint\">{this.state.error.name}\u003c/p>\n          \u003cbutton\n            type=\"button\"\n            className=\"lab-btn\"\n            onClick={() => {\n              this.props.onReset?.();\n              this.setState({ error: null });\n            }}\n          >\n            Try again\n          \u003c/button>\n        \u003c/div>\n      );\n    }\n    return this.props.children;\n  }\n}\n","src/lab/components/Field.tsx":"/* A form field that wires its label, hint and error together for assistive technology. */\nimport type { ReactNode } from \"react\";\nimport { useId } from \"../react\";\n\ninterface FieldProps {\n  label: string;\n  hint?: string;\n  error: string | undefined;\n  children: (a: { id: string; invalid: boolean; describedBy: string | undefined }) => ReactNode;\n}\nexport function Field({ label, hint, error, children }: FieldProps) {\n  const id = useId();\n  const describedBy =\n    [hint ? `${id}-hint` : \"\", error ? `${id}-err` : \"\"].filter(Boolean).join(\" \") || undefined;\n  return (\n    \u003cdiv className=\"lab-field\">\n      \u003clabel htmlFor={id}>{label}\u003c/label>\n      {children({ id, invalid: Boolean(error), describedBy })}\n      {hint && (\n        \u003cp id={`${id}-hint`} className=\"lab-hint\">\n          {hint}\n        \u003c/p>\n      )}\n      {error && (\n        \u003cp id={`${id}-err`} className=\"lab-error\">\n          {error}\n        \u003c/p>\n      )}\n    \u003c/div>\n  );\n}\n","src/angular/main.ts":"import { bootstrapApplication } from \"@angular/platform-browser\";\nimport { AppComponent } from \"./app.component\";\nimport { appConfig } from \"./app.config\";\n\nbootstrapApplication(AppComponent, appConfig).catch((error: unknown) => console.error(error));\n","src/angular/app.component.ts":"import { ChangeDetectionStrategy, Component, inject } from \"@angular/core\";\nimport { RouterLink, RouterOutlet } from \"@angular/router\";\nimport { AuthService } from \"./auth.service\";\n\n/** The shell: a header whose links follow the signed-in role, and the outlet for each route. */\n@Component({\n  selector: \"app-root\",\n  imports: [RouterLink, RouterOutlet],\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    \u003cheader>\n      \u003ca routerLink=\"/risks\">Risk log\u003c/a>\n      @if (auth.session(); as session) {\n        @if (auth.can(\"risk:create\")) {\n          \u003ca routerLink=\"/risks/new\">New risk\u003c/a>\n        }\n        \u003cspan>{{ session.user }}, {{ session.role }} role\u003c/span>\n        \u003cbutton type=\"button\" (click)=\"auth.signOut()\">Sign out\u003c/button>\n      }\n    \u003c/header>\n    \u003cmain>\n      \u003crouter-outlet />\n    \u003c/main>\n  `,\n})\nexport class AppComponent {\n  protected readonly auth = inject(AuthService);\n}\n","src/angular/app.config.ts":"import { provideHttpClient, withInterceptors } from \"@angular/common/http\";\nimport {\n  ApplicationConfig,\n  ErrorHandler,\n  Injectable,\n  provideZonelessChangeDetection,\n} from \"@angular/core\";\nimport { provideRouter, Routes } from \"@angular/router\";\nimport { authGuard } from \"./auth.guard\";\nimport { authInterceptor } from \"./auth.interceptor\";\n\n/** One place for uncaught errors: report them quietly and keep the app running. */\n@Injectable()\nexport class AppErrorHandler implements ErrorHandler {\n  handleError(error: unknown): void {\n    console.error(\"Unhandled error\", error); // a real app sends this to monitoring\n  }\n}\n\nexport const routes: Routes = [\n  {\n    path: \"sign-in\",\n    loadComponent: () => import(\"./sign-in.component\").then((m) => m.SignInComponent),\n  },\n  {\n    path: \"risks\",\n    canActivate: [authGuard],\n    loadComponent: () => import(\"./risks.component\").then((m) => m.RisksComponent),\n  },\n  {\n    path: \"forbidden\",\n    loadComponent: () => import(\"./forbidden.component\").then((m) => m.ForbiddenComponent),\n  },\n  {\n    path: \"risks/new\",\n    canActivate: [authGuard],\n    data: { role: \"admin\" },\n    loadComponent: () => import(\"./risk-form.component\").then((m) => m.RiskFormComponent),\n  },\n  { path: \"**\", redirectTo: \"risks\" },\n];\n\nexport const appConfig: ApplicationConfig = {\n  providers: [\n    provideZonelessChangeDetection(),\n    provideRouter(routes),\n    provideHttpClient(withInterceptors([authInterceptor])),\n    { provide: ErrorHandler, useClass: AppErrorHandler },\n  ],\n};\n","src/angular/auth.service.ts":"import { HttpClient } from \"@angular/common/http\";\nimport { Injectable, computed, inject, signal } from \"@angular/core\";\nimport { Router } from \"@angular/router\";\nimport { Observable, finalize, tap } from \"rxjs\";\nimport { safeReturnUrl } from \"./validators\";\n\nexport type Role = \"viewer\" | \"admin\";\nexport type Permission = \"risk:read\" | \"risk:update\" | \"risk:create\";\nexport interface Session {\n  readonly token: string;\n  readonly user: string;\n  readonly role: Role;\n  readonly expiresAt: number;\n}\n\nconst PERMISSIONS: Readonly\u003cRecord\u003cRole, readonly Permission[]>> = {\n  viewer: [\"risk:read\"],\n  admin: [\"risk:read\", \"risk:update\", \"risk:create\"],\n};\n\n@Injectable({ providedIn: \"root\" })\nexport class AuthService {\n  private readonly http = inject(HttpClient);\n  private readonly router = inject(Router);\n  // In memory only. Nothing goes to localStorage, so injected script cannot read the token back.\n  private readonly state = signal\u003cSession | null>(null);\n\n  readonly session = this.state.asReadonly();\n  readonly isSignedIn = computed(() => this.state() !== null);\n  readonly role = computed(() => this.state()?.role ?? null);\n\n  signIn(username: string, password: string): Observable\u003cSession> {\n    return this.http\n      .post\u003cSession>(\"/api/session\", { username, password })\n      .pipe(tap((session) => this.state.set(session)));\n  }\n\n  signOut(): void {\n    this.http\n      .delete(\"/api/session\")\n      .pipe(\n        finalize(() => {\n          this.state.set(null); // clear locally even if the server cannot be reached\n          void this.router.navigateByUrl(\"/sign-in\");\n        }),\n      )\n      .subscribe({ error: () => undefined });\n  }\n\n  /** Called by the interceptor when the server says the session is gone. */\n  expire(): void {\n    this.state.set(null);\n    // Send the person to sign in, and bring them back to this page afterwards.\n    void this.router.navigate([\"/sign-in\"], {\n      queryParams: { returnUrl: safeReturnUrl(this.router.url) },\n    });\n  }\n\n  can(permission: Permission): boolean {\n    const role = this.role();\n    return role !== null && PERMISSIONS[role].includes(permission);\n  }\n}\n","src/angular/auth.guard.ts":"import { inject } from \"@angular/core\";\nimport { CanActivateFn, Router } from \"@angular/router\";\nimport { AuthService, Role } from \"./auth.service\";\nimport { safeReturnUrl } from \"./validators\";\n\n/** Functional route guard: sign-in first, then the role the route asks for. */\nexport const authGuard: CanActivateFn = (route, state) => {\n  const auth = inject(AuthService);\n  const router = inject(Router);\n\n  if (!auth.isSignedIn()) {\n    return router.createUrlTree([\"/sign-in\"], {\n      queryParams: { returnUrl: safeReturnUrl(state.url) },\n    });\n  }\n  const required = route.data[\"role\"] as Role | undefined;\n  return required && auth.role() !== required ? router.createUrlTree([\"/forbidden\"]) : true;\n};\n","src/angular/forbidden.component.ts":"import { ChangeDetectionStrategy, Component } from \"@angular/core\";\nimport { RouterLink } from \"@angular/router\";\n\n/** Where the role guard sends a signed-in person whose role does not allow the page. */\n@Component({\n  selector: \"app-forbidden\",\n  imports: [RouterLink],\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    \u003ch1>Your role does not allow this page\u003c/h1>\n    \u003cp>Ask an administrator for access, or go back to the risk log.\u003c/p>\n    \u003ca routerLink=\"/risks\">Back to the risk log\u003c/a>\n  `,\n})\nexport class ForbiddenComponent {}\n","src/angular/auth.interceptor.ts":"import { HttpErrorResponse, HttpInterceptorFn, HttpRequest } from \"@angular/common/http\";\nimport { inject } from \"@angular/core\";\nimport { catchError, retry, throwError, timer } from \"rxjs\";\nimport { AuthService } from \"./auth.service\";\n\nconst API_PREFIX = \"/api/\";\n\n/** Only safe, repeatable requests are retried, and only for network failures and 5xx answers. */\nconst retryable = (req: HttpRequest\u003cunknown>, error: unknown): boolean =>\n  req.method === \"GET\" &&\n  error instanceof HttpErrorResponse &&\n  (error.status === 0 || error.status >= 500);\n\nexport const authInterceptor: HttpInterceptorFn = (req, next) => {\n  if (!req.url.startsWith(API_PREFIX)) return next(req); // never send the token to another origin\n\n  const auth = inject(AuthService);\n  const session = auth.session();\n  const outgoing = session\n    ? req.clone({ setHeaders: { Authorization: `Bearer ${session.token}` } })\n    : req;\n\n  return next(outgoing).pipe(\n    retry({\n      count: 2,\n      delay: (error: unknown, attempt: number) =>\n        retryable(req, error)\n          ? timer(300 * 2 ** (attempt - 1) + Math.random() * 100)\n          : throwError(() => error),\n    }),\n    catchError((error: unknown) => {\n      if (error instanceof HttpErrorResponse && error.status === 401) auth.expire(); // one place ends a dead session\n      return throwError(() => error);\n    }),\n  );\n};\n","src/angular/validators.ts":"import { AbstractControl, ValidationErrors, ValidatorFn } from \"@angular/forms\";\n\n/** Accepts only https links with no embedded credentials. javascript: and data: links fail. */\nexport function httpsUrl(): ValidatorFn {\n  return (control: AbstractControl): ValidationErrors | null => {\n    const value = String(control.value ?? \"\").trim();\n    if (value === \"\") return null; // optional field: add Validators.required where it is mandatory\n    // The prefix check rejects \"https:example.com\", which the URL parser accepts\n    // but a browser would resolve as a link on the current site.\n    if (!/^https:\\/\\//i.test(value) || value.length > 200) return { httpsUrl: true };\n    try {\n      const url = new URL(value);\n      return !url.username && !url.password ? null : { httpsUrl: true };\n    } catch {\n      return { httpsUrl: true };\n    }\n  };\n}\n\n/** Only same-site paths are allowed after sign-in. This blocks open redirects like //evil.example. */\nexport function safeReturnUrl(url: string | null | undefined): string {\n  if (!url || !url.startsWith(\"/\") || url.startsWith(\"//\") || url.includes(\"\\\\\")) return \"/\";\n  return url;\n}\n","src/angular/risk.store.ts":"import { HttpClient } from \"@angular/common/http\";\nimport { DestroyRef, Injectable, computed, inject, signal } from \"@angular/core\";\nimport { takeUntilDestroyed } from \"@angular/core/rxjs-interop\";\nimport { finalize } from \"rxjs\";\n\nexport type RiskStatus = \"open\" | \"mitigating\" | \"resolved\";\nexport interface Risk {\n  readonly id: string;\n  title: string;\n  owner: string;\n  severity: \"low\" | \"medium\" | \"high\";\n  status: RiskStatus;\n}\ntype Load = \"idle\" | \"loading\" | \"ready\" | \"error\";\n\n/** Signal store: private writable state, public read-only views. */\n@Injectable({ providedIn: \"root\" })\nexport class RiskStore {\n  private readonly http = inject(HttpClient);\n  private readonly destroyRef = inject(DestroyRef);\n  private readonly items = signal\u003creadonly Risk[]>([]);\n  private readonly loadState = signal\u003cLoad>(\"idle\");\n  private readonly queryState = signal(\"\");\n  private readonly errorState = signal\u003cstring | null>(null);\n  private readonly pendingState = signal\u003cReadonlySet\u003cstring>>(new Set());\n\n  readonly load = this.loadState.asReadonly();\n  readonly query = this.queryState.asReadonly();\n  readonly error = this.errorState.asReadonly();\n  readonly pending = this.pendingState.asReadonly();\n\n  readonly visible = computed(() => {\n    const q = this.query().trim().toLowerCase();\n    return this.items().filter(\n      (r) => q === \"\" || `${r.id} ${r.title} ${r.owner}`.toLowerCase().includes(q),\n    );\n  });\n\n  setQuery(value: string): void {\n    this.queryState.set(value);\n  }\n\n  reload(): void {\n    this.loadState.set(\"loading\");\n    this.errorState.set(null);\n    this.http\n      .get\u003cRisk[]>(\"/api/risks\")\n      .pipe(takeUntilDestroyed(this.destroyRef))\n      .subscribe({\n        next: (rows) => {\n          this.items.set(rows);\n          this.loadState.set(\"ready\");\n        },\n        error: () => {\n          this.errorState.set(\"Could not load risks. Try again.\");\n          this.loadState.set(\"error\");\n        },\n      });\n  }\n\n  /** Optimistic update: change the row now, put the old one back if the request fails. */\n  setStatus(id: string, status: RiskStatus): void {\n    const previous = this.items().find((r) => r.id === id);\n    if (!previous || previous.status === status || this.pending().has(id)) return;\n    this.errorState.set(null);\n    this.replace({ ...previous, status });\n    this.mark(id, true);\n    this.http\n      .patch\u003cRisk>(`/api/risks/${id}`, { status })\n      .pipe(finalize(() => this.mark(id, false)))\n      .subscribe({\n        error: () => {\n          this.replace(previous);\n          this.errorState.set(`The update failed, so ${id} was restored.`);\n        },\n      });\n  }\n\n  private replace(next: Risk): void {\n    this.items.update((rows) => rows.map((r) => (r.id === next.id ? next : r)));\n  }\n\n  private mark(id: string, on: boolean): void {\n    this.pendingState.update((current) => {\n      const copy = new Set(current);\n      if (on) copy.add(id);\n      else copy.delete(id);\n      return copy;\n    });\n  }\n}\n","src/angular/risks.component.ts":"import { ChangeDetectionStrategy, Component, OnInit, computed, inject } from \"@angular/core\";\nimport { AuthService } from \"./auth.service\";\nimport { Risk, RiskStore } from \"./risk.store\";\n\n@Component({\n  selector: \"app-risks\",\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    \u003cinput\n      type=\"search\"\n      aria-label=\"Search risks\"\n      [value]=\"store.query()\"\n      (input)=\"onSearch($event)\"\n    />\n\n    \u003cp role=\"status\">{{ store.load() === \"loading\" ? \"Loading risks...\" : \"\" }}\u003c/p>\n    \u003cp role=\"alert\">{{ store.error() }}\u003c/p>\n\n    \u003ctable>\n      \u003ccaption class=\"sr-only\">\n        Program risks\n      \u003c/caption>\n      \u003cthead>\n        \u003ctr>\n          \u003cth scope=\"col\">ID\u003c/th>\n          \u003cth scope=\"col\">Risk\u003c/th>\n          \u003cth scope=\"col\">Status\u003c/th>\n          \u003cth scope=\"col\">\u003cspan class=\"sr-only\">Action\u003c/span>\u003c/th>\n        \u003c/tr>\n      \u003c/thead>\n      \u003ctbody>\n        @for (risk of store.visible(); track risk.id) {\n          \u003ctr [attr.aria-busy]=\"store.pending().has(risk.id)\">\n            \u003ctd>{{ risk.id }}\u003c/td>\n            \u003c!-- Interpolation is escaped by Angular. Untrusted text never becomes markup. -->\n            \u003ctd>{{ risk.title }}\u003c/td>\n            \u003ctd>{{ risk.status }}\u003c/td>\n            \u003ctd>\n              \u003cbutton\n                type=\"button\"\n                [disabled]=\"!canUpdate()\"\n                [attr.aria-disabled]=\"store.pending().has(risk.id) || null\"\n                [attr.aria-label]=\"actionLabel(risk)\"\n                (click)=\"toggle(risk)\"\n              >\n                {{ risk.status === \"resolved\" ? \"Reopen\" : \"Resolve\" }}\n              \u003c/button>\n            \u003c/td>\n          \u003c/tr>\n        } @empty {\n          @if (store.load() === \"ready\") {\n            \u003ctr>\n              \u003ctd colspan=\"4\">No risks match. Clear the search to see them all.\u003c/td>\n            \u003c/tr>\n          }\n        }\n      \u003c/tbody>\n    \u003c/table>\n  `,\n})\nexport class RisksComponent implements OnInit {\n  protected readonly store = inject(RiskStore);\n  private readonly auth = inject(AuthService);\n  protected readonly canUpdate = computed(() => this.auth.can(\"risk:update\"));\n\n  ngOnInit(): void {\n    this.store.reload();\n  }\n\n  protected onSearch(event: Event): void {\n    this.store.setQuery((event.target as HTMLInputElement).value);\n  }\n\n  protected actionLabel(risk: Risk): string {\n    return `${risk.status === \"resolved\" ? \"Reopen\" : \"Resolve\"} ${risk.id}`;\n  }\n\n  protected toggle(risk: Risk): void {\n    this.store.setStatus(risk.id, risk.status === \"resolved\" ? \"open\" : \"resolved\");\n  }\n}\n","src/angular/risk-form.component.ts":"import { HttpClient, HttpErrorResponse } from \"@angular/common/http\";\nimport {\n  ChangeDetectionStrategy,\n  ChangeDetectorRef,\n  Component,\n  ElementRef,\n  inject,\n  signal,\n} from \"@angular/core\";\nimport { NonNullableFormBuilder, ReactiveFormsModule, Validators } from \"@angular/forms\";\nimport { finalize } from \"rxjs\";\nimport { httpsUrl } from \"./validators\";\n\ntype FieldName = \"title\" | \"owner\" | \"severity\" | \"reference\";\n\n@Component({\n  selector: \"app-risk-form\",\n  imports: [ReactiveFormsModule],\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    \u003cform [formGroup]=\"form\" (ngSubmit)=\"submit()\" novalidate>\n      \u003clabel for=\"title\">Title\u003c/label>\n      \u003cinput\n        id=\"title\"\n        formControlName=\"title\"\n        [attr.aria-invalid]=\"invalid('title')\"\n        [attr.aria-describedby]=\"invalid('title') ? 'title-error' : null\"\n      />\n      @if (invalid(\"title\")) {\n        \u003cp id=\"title-error\" role=\"alert\">{{ message(\"title\") }}\u003c/p>\n      }\n\n      \u003clabel for=\"owner\">Owner email\u003c/label>\n      \u003cinput\n        id=\"owner\"\n        type=\"email\"\n        formControlName=\"owner\"\n        [attr.aria-invalid]=\"invalid('owner')\"\n        [attr.aria-describedby]=\"invalid('owner') ? 'owner-error' : null\"\n      />\n      @if (invalid(\"owner\")) {\n        \u003cp id=\"owner-error\" role=\"alert\">{{ message(\"owner\") }}\u003c/p>\n      }\n\n      \u003clabel for=\"severity\">Severity\u003c/label>\n      \u003cselect\n        id=\"severity\"\n        formControlName=\"severity\"\n        [attr.aria-invalid]=\"invalid('severity')\"\n        [attr.aria-describedby]=\"invalid('severity') ? 'severity-error' : null\"\n      >\n        @for (level of severities; track level) {\n          \u003coption [value]=\"level\">{{ level }}\u003c/option>\n        }\n      \u003c/select>\n      @if (invalid(\"severity\")) {\n        \u003cp id=\"severity-error\" role=\"alert\">{{ message(\"severity\") }}\u003c/p>\n      }\n\n      \u003clabel for=\"reference\">Reference link (optional)\u003c/label>\n      \u003cinput\n        id=\"reference\"\n        formControlName=\"reference\"\n        [attr.aria-invalid]=\"invalid('reference')\"\n        [attr.aria-describedby]=\"invalid('reference') ? 'reference-error' : null\"\n      />\n      @if (invalid(\"reference\")) {\n        \u003cp id=\"reference-error\" role=\"alert\">{{ message(\"reference\") }}\u003c/p>\n      }\n\n      \u003cbutton type=\"submit\" [disabled]=\"saving()\">\n        {{ saving() ? \"Creating...\" : \"Create risk\" }}\n      \u003c/button>\n      \u003cp role=\"alert\">{{ result() }}\u003c/p>\n    \u003c/form>\n  `,\n})\nexport class RiskFormComponent {\n  private readonly http = inject(HttpClient);\n  private readonly host = inject\u003cElementRef\u003cHTMLElement>>(ElementRef);\n  private readonly cdr = inject(ChangeDetectorRef);\n  private readonly fb = inject(NonNullableFormBuilder);\n\n  protected readonly severities = [\"low\", \"medium\", \"high\"] as const;\n  protected readonly saving = signal(false);\n  protected readonly result = signal(\"\");\n  protected readonly form = this.fb.group({\n    title: [\"\", [Validators.required, Validators.minLength(3), Validators.maxLength(80)]],\n    owner: [\"\", [Validators.required, Validators.email]],\n    severity: [\"medium\", Validators.required],\n    reference: [\"\", [httpsUrl()]],\n  });\n\n  protected invalid(name: FieldName): boolean {\n    const control = this.form.controls[name];\n    return control.invalid && (control.touched || control.dirty);\n  }\n\n  protected message(name: FieldName): string {\n    const errors = this.form.controls[name].errors;\n    if (errors?.[\"server\"]) return String(errors[\"server\"]); // the server has the last word\n    if (errors?.[\"httpsUrl\"]) return \"Use a full https:// link with no username or password.\";\n    if (errors?.[\"email\"]) return \"Enter a valid email address, like name@company.com.\";\n    if (name === \"severity\") return \"Choose low, medium or high.\";\n    return name === \"title\" ? \"Enter 3 to 80 characters.\" : \"This field is required.\";\n  }\n\n  protected submit(): void {\n    this.result.set(\"\");\n    if (this.form.invalid) {\n      this.form.markAllAsTouched();\n      this.cdr.detectChanges(); // render aria-invalid first, then move focus to the first problem\n      this.focusFirstProblem();\n      return;\n    }\n    this.saving.set(true);\n    this.http\n      .post(\"/api/risks\", this.form.getRawValue())\n      .pipe(finalize(() => this.saving.set(false)))\n      .subscribe({\n        next: () => {\n          this.form.reset();\n          this.result.set(\"Risk created.\");\n        },\n        error: (error: unknown) => this.onError(error),\n      });\n  }\n\n  private onError(error: unknown): void {\n    if (error instanceof HttpErrorResponse && error.status === 422) {\n      this.applyServerErrors(error.error?.fields ?? {});\n      this.result.set(\"Some fields need attention.\");\n    } else if (error instanceof HttpErrorResponse && error.status === 403) {\n      this.result.set(\"Your role does not allow this action.\");\n    } else {\n      this.result.set(\"The risk was not created. Try again.\");\n    }\n  }\n\n  /** The API re-checks every field, so show whatever it rejects. */\n  private applyServerErrors(fields: Record\u003cstring, string>): void {\n    for (const [name, message] of Object.entries(fields)) {\n      const control = this.form.get(name);\n      control?.setErrors({ server: message });\n      control?.markAsTouched(); // a field the person never touched still shows its error\n    }\n    this.cdr.detectChanges();\n    this.focusFirstProblem();\n  }\n\n  private focusFirstProblem(): void {\n    this.host.nativeElement.querySelector\u003cHTMLElement>('[aria-invalid=\"true\"]')?.focus();\n  }\n}\n","src/angular/sign-in.component.ts":"import { HttpErrorResponse } from \"@angular/common/http\";\nimport { ChangeDetectionStrategy, Component, ElementRef, inject, signal } from \"@angular/core\";\nimport { NonNullableFormBuilder, ReactiveFormsModule, Validators } from \"@angular/forms\";\nimport { ActivatedRoute, Router } from \"@angular/router\";\nimport { finalize } from \"rxjs\";\nimport { AuthService } from \"./auth.service\";\nimport { safeReturnUrl } from \"./validators\";\n\n@Component({\n  selector: \"app-sign-in\",\n  imports: [ReactiveFormsModule],\n  changeDetection: ChangeDetectionStrategy.OnPush,\n  template: `\n    \u003cform [formGroup]=\"form\" (ngSubmit)=\"submit()\" novalidate>\n      \u003clabel for=\"username\">Username\u003c/label>\n      \u003cinput id=\"username\" formControlName=\"username\" autocomplete=\"username\" />\n      \u003clabel for=\"password\">Password\u003c/label>\n      \u003cinput\n        id=\"password\"\n        type=\"password\"\n        formControlName=\"password\"\n        autocomplete=\"current-password\"\n      />\n      \u003cbutton type=\"submit\" [disabled]=\"pending()\">\n        {{ pending() ? \"Signing in...\" : \"Sign in\" }}\n      \u003c/button>\n      @if (error(); as message) {\n        \u003cp role=\"alert\">{{ message }}\u003c/p>\n      }\n    \u003c/form>\n  `,\n})\nexport class SignInComponent {\n  private readonly auth = inject(AuthService);\n  private readonly router = inject(Router);\n  private readonly route = inject(ActivatedRoute);\n  private readonly fb = inject(NonNullableFormBuilder);\n  private readonly host = inject\u003cElementRef\u003cHTMLElement>>(ElementRef);\n\n  protected readonly pending = signal(false);\n  protected readonly error = signal\u003cstring | null>(null);\n  protected readonly form = this.fb.group({\n    username: [\"\", Validators.required],\n    password: [\"\", Validators.required],\n  });\n\n  /** Plain language for each outcome. A wrong name and a wrong password get the same answer. */\n  private messageFor(error: unknown): string {\n    if (!(error instanceof HttpErrorResponse)) return \"Something unexpected went wrong.\";\n    if (error.status === 401) return \"Invalid username or password.\";\n    if (error.status === 429) return \"Too many attempts. Wait a moment, then try again.\";\n    if (error.status === 0) return \"You appear to be offline. Check your connection and try again.\";\n    return \"The server hit a problem. Try again.\";\n  }\n\n  protected submit(): void {\n    if (this.form.invalid) {\n      this.error.set(\"Enter your username and password.\");\n      const first = this.form.controls.username.invalid ? \"#username\" : \"#password\";\n      this.host.nativeElement.querySelector\u003cHTMLElement>(first)?.focus();\n      return;\n    }\n    this.pending.set(true);\n    this.error.set(null);\n    const { username, password } = this.form.getRawValue();\n    this.auth\n      .signIn(username, password)\n      .pipe(finalize(() => this.pending.set(false)))\n      .subscribe({\n        next: () =>\n          void this.router.navigateByUrl(\n            safeReturnUrl(this.route.snapshot.queryParamMap.get(\"returnUrl\")),\n          ),\n        error: (error: unknown) => {\n          this.form.controls.password.reset(); // never leave a rejected password in the field\n          this.error.set(this.messageFor(error));\n        },\n      });\n  }\n}\n"};
